/* ============ СИНХРОНИЗАЦИЯ С СЕРВЕРОМ SQLITE (/api/db) ============ */
(function () {
  var API_URL = "/api/db";
  // Ключи, которые принадлежат только текущему браузеру и не уходят в общую БД
  var LOCAL_ONLY_KEYS = {
    teamCurrentUser: 1,
    savedAccounts: 1,
    hideBalances: 1,
    loginAttempts: 1,
  };

  // Маппинг имён ключей между localStorage (app.js) и полями в backup.json / SQLite
  var KEY_TO_DB = { teamUsers: "users", auditLogs: "logs" };
  var DB_TO_KEY = { users: "teamUsers", logs: "auditLogs" };

  var _origSetItem = Storage.prototype.setItem;
  var _isSyncing = false;
  var _saveTimer = null;

  // 1. Синхронная загрузка базы из SQLite до запуска основного кода app.js
  try {
    var xhr = new XMLHttpRequest();
    xhr.open("GET", API_URL, false); // false = ждём ответа до инициализации переменных
    xhr.send(null);

    if (xhr.status === 200 && xhr.responseText) {
      var dbData = JSON.parse(xhr.responseText);
      if (dbData && Array.isArray(dbData.users) && dbData.users.length > 0) {
        _isSyncing = true;
        Object.keys(dbData).forEach(function (dbKey) {
          if (dbKey === "version") return;
          var lsKey = DB_TO_KEY[dbKey] || dbKey;
          if (!LOCAL_ONLY_KEYS[lsKey]) {
            _origSetItem.call(
              localStorage,
              lsKey,
              JSON.stringify(dbData[dbKey]),
            );
          }
        });
        _isSyncing = false;
        console.log("🗄️ База данных успешно загружена из SQLite");
      }
    }
  } catch (err) {
    _isSyncing = false;
    console.warn(
      "⚠️ Сервер SQLite недоступен, работаем с локальным кэшем:",
      err,
    );
  }

  // 2. Сбор всех данных из localStorage и отправка в SQLite
  function pushDatabaseToServer() {
    try {
      var payload = { version: "11.7" };
      for (var i = 0; i < localStorage.length; i++) {
        var lsKey = localStorage.key(i);
        if (
          !lsKey ||
          LOCAL_ONLY_KEYS[lsKey] ||
          lsKey.indexOf("dailyOps_") === 0 ||
          lsKey.indexOf("lim_") === 0
        ) {
          continue;
        }
        var raw = localStorage.getItem(lsKey);
        if (raw === null || raw === "undefined") continue;
        var dbKey = KEY_TO_DB[lsKey] || lsKey;
        try {
          payload[dbKey] = JSON.parse(raw);
        } catch (_) {
          payload[dbKey] = raw;
        }
      }

      if (!Array.isArray(payload.users) || payload.users.length === 0) return;

      fetch(API_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      }).catch(function (e) {
        console.error("Ошибка сохранения в SQLite:", e);
      });
    } catch (e) {
      console.error("Ошибка подготовки данных для SQLite:", e);
    }
  }

  // 3. Перехват любого сохранения в localStorage для авто-отправки в SQLite
  Storage.prototype.setItem = function (key, value) {
    _origSetItem.call(this, key, value);
    if (this === localStorage && !_isSyncing && !LOCAL_ONLY_KEYS[key]) {
      clearTimeout(_saveTimer);
      _saveTimer = setTimeout(pushDatabaseToServer, 300);
    }
  };
})();
window.__DISCORD_OAUTH_HASH =
  window.location.hash && window.location.hash.indexOf("access_token=") !== -1
    ? window.location.hash
    : "";

/* ============ ГЛОБАЛЬНАЯ ОБРАБОТКА ОШИБОК ============ */
// FIX: не показываем toast на каждую ошибку (шум от расширений) — только логируем
window.addEventListener("error", function (ev) {
  try {
    console.error(
      "[window.error]",
      ev.message,
      ev.filename,
      ev.lineno,
      ev.error,
    );
  } catch (e) {}
});

/* FIX #62: глобальный обработчик необработанных промисов */
var _lastUnhandledToast = 0;
window.addEventListener("unhandledrejection", function (ev) {
  try {
    console.error("[unhandledrejection]", ev && ev.reason ? ev.reason : ev);
  } catch (_) {}
  var now = Date.now();
  if (now - _lastUnhandledToast < 5000) return;
  _lastUnhandledToast = now;
  try {
    var msg =
      ev && ev.reason && ev.reason.message ? String(ev.reason.message) : "";
    if (msg.length > 200) msg = msg.slice(0, 200) + "…";
    toast(
      "❌ " + (msg || "Необработанная ошибка (детали в консоли)"),
      "error",
      { duration: 6000 },
    );
  } catch (_) {}
});

/* ============ БЕЗОПАСНЫЙ ПАРСИНГ localStorage ============ */
// FIX: универсальные хелперы — не дают упасть скрипту из-за битого localStorage
function safeParseJSON(key, fallback) {
  try {
    var raw = localStorage.getItem(key);
    if (
      raw === null ||
      raw === undefined ||
      raw === "" ||
      raw === "undefined" ||
      raw === "null"
    )
      return fallback;
    var v = JSON.parse(raw);
    return v === null || v === undefined ? fallback : v;
  } catch (e) {
    console.warn("safeParseJSON(" + key + ")", e);
    return fallback;
  }
}
function safeParseArray(key, fallback) {
  var v = safeParseJSON(key, fallback);
  return Array.isArray(v) ? v : fallback || [];
}
function safeParseObject(key, fallback) {
  var v = safeParseJSON(key, fallback);
  return v && typeof v === "object" && !Array.isArray(v) ? v : fallback || {};
}
/* FIX: защита от переполнения localStorage — авто-очистка старых записей */
(function () {
  var _origSet = Storage.prototype.setItem;
  Storage.prototype.setItem = function (key, value) {
    try {
      return _origSet.call(this, key, value);
    } catch (e) {
      if (
        e &&
        (e.name === "QuotaExceededError" || e.code === 22 || e.code === 1014) &&
        this === localStorage
      ) {
        try {
          /* 1) Обрезаем логи и уведомления */
          var _l = safeParseArray("auditLogs", []);
          if (_l.length > 100)
            _origSet.call(this, "auditLogs", JSON.stringify(_l.slice(-100)));
          var _t = safeParseArray("txLog", []);
          if (_t.length > 300)
            _origSet.call(this, "txLog", JSON.stringify(_t.slice(-300)));
          var _n = safeParseArray("notifications", []);
          if (_n.length > 200)
            _origSet.call(
              this,
              "notifications",
              JSON.stringify(_n.slice(-200)),
            );

          /* 2) Сжимаем/удаляем тяжёлые аватары и фоны */
          var _u = safeParseArray("teamUsers", []);
          var _changed = false;
          _u.forEach(function (usr) {
            if (
              usr &&
              typeof usr.avatar === "string" &&
              usr.avatar.length > 150000
            ) {
              usr.avatar = "";
              _changed = true;
            }
            if (
              usr &&
              typeof usr.profileBg === "string" &&
              usr.profileBg.length > 200000
            ) {
              usr.profileBg = "";
              _changed = true;
            }
          });
          if (_changed) _origSet.call(this, "teamUsers", JSON.stringify(_u));

          /* 3) Пробуем записать исходное */
          return _origSet.call(this, key, value);
        } catch (e2) {
          try {
            toast("⚠️ Хранилище переполнено — сохранение не удалось", "error", {
              duration: 5000,
            });
          } catch (_) {}
          console.error("localStorage quota:", e2);
          throw e;
        }
      }
      throw e;
    }
  };
})();

