/* Загрузка/сохранение */
var LIMITS = (function () {
  var merged = JSON.parse(JSON.stringify(DEFAULT_LIMITS));
  var saved = safeParseObject("limitsConfig", {});
  for (var s in saved) {
    if (!saved.hasOwnProperty(s) || !merged[s]) continue;
    for (var k in saved[s]) {
      if (
        typeof merged[s][k] === "number" &&
        typeof saved[s][k] === "number" &&
        isFinite(saved[s][k])
      ) {
        merged[s][k] = saved[s][k];
      }
    }
  }
  return merged;
})();
function saveLimitsConfig() {
  return _safeSet("limitsConfig", LIMITS, "лимиты");
}
function resetLimitsConfig() {
  localStorage.removeItem("limitsConfig");
  var fresh = JSON.parse(JSON.stringify(DEFAULT_LIMITS));
  for (var s in fresh) if (fresh.hasOwnProperty(s)) LIMITS[s] = fresh[s];
}
function getLimit(section, key, user) {
  if (
    user &&
    user.limitOverrides &&
    user.limitOverrides[section] &&
    typeof user.limitOverrides[section][key] === "number"
  ) {
    return user.limitOverrides[section][key];
  }
  if (LIMITS[section] && typeof LIMITS[section][key] === "number")
    return LIMITS[section][key];
  if (DEFAULT_LIMITS[section]) return DEFAULT_LIMITS[section][key];
  return 0;
}

/* Дневной трекер */
function getDailyTracker(userId, key) {
  var today = new Date().toDateString();
  var sKey = "lim_" + userId + "_" + key;
  var d = safeParseObject(sKey, { date: today, sum: 0, count: 0 });
  if (d.date !== today) {
    d = { date: today, sum: 0, count: 0 };
    localStorage.setItem(sKey, JSON.stringify(d));
  }
  return d;
}
function commitDailyTracker(userId, key, sum, count) {
  var d = getDailyTracker(userId, key);
  d.sum += Number(sum) || 0;
  d.count += count === undefined ? 1 : Number(count) || 0;
  if (d.sum < 0) d.sum = 0;
  if (d.count < 0) d.count = 0;
  localStorage.setItem("lim_" + userId + "_" + key, JSON.stringify(d));
}
function checkDailyLimit(userId, key, opts) {
  opts = opts || {};
  var d = getDailyTracker(userId, key);
  var addSum = Number(opts.addSum) || 0;
  var addCount = Number(opts.addCount !== undefined ? opts.addCount : 1);
  if (typeof opts.maxSum === "number" && d.sum + addSum > opts.maxSum) {
    return {
      ok: false,
      msg:
        "Дневной лимит по сумме. Осталось: " +
        fmtBalance(Math.max(0, opts.maxSum - d.sum)),
    };
  }
  if (typeof opts.maxCount === "number" && d.count + addCount > opts.maxCount) {
    return {
      ok: false,
      msg: "Дневной лимит. Осталось: " + (opts.maxCount - d.count),
    };
  }
  return { ok: true };
}
function checkHourlyLimit(userId, key, max) {
  var now = Date.now();
  var sKey = "limH_" + userId + "_" + key;
  var arr = safeParseArray(sKey, []).filter(function (t) {
    return now - t < 3600000;
  });
  if (arr.length >= max)
    return { ok: false, msg: "Часовой лимит операций (макс " + max + ")" };
  return { ok: true, _key: sKey, _arr: arr };
}
function commitHourlyLimit(peek) {
  if (!peek || !peek.ok || !peek._key) return;
  peek._arr.push(Date.now());
  localStorage.setItem(peek._key, JSON.stringify(peek._arr));
}

/* Brute-force защита */
function getLoginAttempts(login) {
  var now = Date.now();
  var arr = safeParseArray("loginAttempts", []).filter(function (x) {
    return now - x.time < getLimit("login", "lockoutMs", null);
  });
  return arr.filter(function (x) {
    return x.login === login.toLowerCase();
  });
}
function addLoginAttempt(login) {
  var lockout = getLimit("login", "lockoutMs", null);
  var arr = safeParseArray("loginAttempts", []).filter(function (x) {
    return Date.now() - x.time < lockout;
  });
  arr.push({ login: login.toLowerCase(), time: Date.now() });
  if (arr.length > 500) arr = arr.slice(-500);
  localStorage.setItem("loginAttempts", JSON.stringify(arr));
}
function clearLoginAttempts(login) {
  var arr = safeParseArray("loginAttempts", []).filter(function (x) {
    return x.login !== login.toLowerCase();
  });
  localStorage.setItem("loginAttempts", JSON.stringify(arr));
}
