function getDailyUsage(adminId, currency) {
  var today = new Date().toDateString();
  var key = "dailyOps_" + adminId + "_" + currency;
  var d = safeParseObject(key, { date: today, sum: 0 });
  if (d.date !== today) {
    d = { date: today, sum: 0 };
    localStorage.setItem(key, JSON.stringify(d));
  }
  return d;
}
function checkOpLimits(amount, currency) {
  var u = current();
  if (!u) return { ok: false, msg: "Нет сессии" };
  var sym = currency === "coins" ? " 🪙" : " ₽";
  var maxPerOp =
    currency === "coins" ? OP_LIMITS.maxCoinsPerOp : OP_LIMITS.maxBalancePerOp;
  var maxDaily =
    currency === "coins" ? OP_LIMITS.maxCoinsDaily : OP_LIMITS.maxBalanceDaily;
  if (amount > maxPerOp)
    return {
      ok: false,
      msg: "Максимум за операцию: " + fmtBalance(maxPerOp) + sym,
    };
  var usage = getDailyUsage(u.id, currency);
  if (usage.sum + amount > maxDaily) {
    var left = maxDaily - usage.sum;
    return {
      ok: false,
      msg:
        "Дневной лимит исчерпан. Осталось: " +
        fmtBalance(Math.max(0, left)) +
        sym,
    };
  }
  return { ok: true };
}
function commitOpLimit(amount, currency) {
  var u = current();
  if (!u) return;
  var key = "dailyOps_" + u.id + "_" + currency;
  var usage = getDailyUsage(u.id, currency);
  usage.sum += amount;
  localStorage.setItem(key, JSON.stringify(usage));
}
