var _rateLimitMap = {};
var _lastRateCleanup = 0;
function rateLimit(key) {
  var now = Date.now();
  var cd = RATE_LIMIT_OVERRIDES[key] || RATE_LIMIT_COOLDOWN;
  /* FIX #13: гарантированная очистка раз в 60 секунд (вместо 5% случайных) */
  if (now - _lastRateCleanup > 60000) {
    _lastRateCleanup = now;
    for (var k in _rateLimitMap) {
      if (now - _rateLimitMap[k] > 60000) delete _rateLimitMap[k];
    }
  }
  if (_rateLimitMap[key] && now - _rateLimitMap[key] < cd) {
    var left = Math.ceil((cd - (now - _rateLimitMap[key])) / 1000);
    toast("⏳ Подождите " + left + " с.", "warn");
    return false;
  }
  _rateLimitMap[key] = now;
  return true;
}
function avatarGradient(name) {
  var h = 0,
    s = String(name || "?");
  for (var i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
  var hue = h % 360;
  return (
    "linear-gradient(135deg,hsl(" +
    hue +
    ",55%,38%),hsl(" +
    ((hue + 45) % 360) +
    ",60%,22%))"
  );
}
var _EMOJI_CHARS =
  "\\u{1F000}-\\u{1FAFF}\\u{2600}-\\u{27BF}\\u{2B00}-\\u{2BFF}\\u{1F1E6}-\\u{1F1FF}\\u{2190}-\\u{21FF}\\u{2300}-\\u{23FF}\\u{2900}-\\u{297F}\\u{FE0F}\\u{200D}\\u{20E3}";
var _EMOJI_RE = new RegExp("^[" + _EMOJI_CHARS + "]+\\s*([\\s\\S]*)$", "u");
function extractToastEmoji(str) {
  var s = String(str || "").trim();
  var m = s.match(_EMOJI_RE);
  if (m && m[1] !== undefined) {
    var iconMatch = s.slice(0, s.length - m[1].length).trim();
    if (iconMatch) return { icon: iconMatch, text: m[1].trim() };
  }
  return { icon: null, text: s };
}
// FIX: заставляет браузер рисовать эмодзи цветным глифом, а не текстовым
function forceEmojiVS(ch) {
  if (!ch) return ch;
  ch = String(ch);
  if (ch.indexOf("\uFE0F") !== -1) return ch;
  var out = "";
  for (var i = 0; i < ch.length; i++) {
    var cp = ch.codePointAt(i);
    var c = String.fromCodePoint(cp);
    if (cp > 0xffff) i++;
    // Пропускаем пробелы/ZWJ
    if (c === " " || c === "\u200D" || c === "\u20E3") {
      out += c;
      continue;
    }
    out += c + "\uFE0F";
  }
  return out;
}
window.addEventListener("storage", function (e) {
  try {
    if (e.key === "notifications") {
      notifications = safeParseArray("notifications", []);
      updateNotifBadge();
      if (notifOpen) renderNotifications();
    } else if (e.key === "teamUsers") {
      users = safeParseArray("teamUsers", []);
      if (
        currentId &&
        !users.find(function (x) {
          return x.id === currentId;
        })
      ) {
        logout();
        return;
      }
      try {
        checkWarnedStatus();
      } catch (_) {}
      try {
        checkFrozenStatus();
      } catch (_) {}
      var _cu = current();
      if (
        _cu &&
        hasUnseenWarns(_cu) &&
        !document.getElementById("warnedModalOverlay")
      ) {
        setTimeout(function () {
          openWarnedModal();
        }, 400);
      }
      try {
        if (
          !wheelSpinning &&
          !document
            .getElementById("gamesSectionWheel")
            .classList.contains("hidden")
        ) {
          updateWheelTimer();
        }
      } catch (_) {}
      /* BP: другая вкладка могла изменить лутбоксы/спины/покупки — пересчитать XP */
      try {
        _bpRefreshIfVisible();
      } catch (_) {}
    } else if (e.key === "tasks") {
      tasks = safeParseArray("tasks", []);
      if (!document.getElementById("sectionTasks").classList.contains("hidden"))
        renderTasks();
      try {
        _bpRefreshIfVisible();
      } catch (_) {}
    } else if (e.key === "shopItems") {
      shopItems = safeParseArray("shopItems", []);
    } else if (e.key === "auditLogs") {
      logs = safeParseArray("auditLogs", []);
      if (!document.getElementById("sectionLogs").classList.contains("hidden"))
        renderLogs();
    } else if (e.key === "promoCodes") {
      promoCodes = safeParseArray("promoCodes", []);
      normalizePromoCodes();
      var el = document.getElementById("ecoSectionPromo");
      if (el && !el.classList.contains("hidden"))
        try {
          renderPromo();
        } catch (_) {}
    } else if (e.key === "lootboxes") {
      lootboxes = safeParseArray("lootboxes", []);
    } else if (e.key === "giftCards") {
      giftCards = safeParseArray("giftCards", []);
      try {
        normalizeGiftCards();
      } catch (_) {}
      var gEl = document.getElementById("ecoSectionGiftCards");
      if (gEl && !gEl.classList.contains("hidden"))
        try {
          renderGiftCardsSection();
        } catch (_) {}
    } else if (e.key === "wheelPrizes") {
      wheelPrizes = safeParseArray("wheelPrizes", wheelPrizes);
    } else if (e.key === "battlePass") {
      battlePass = safeParseObject("battlePass", battlePass);
      _bpRefreshIfVisible();
    } else if (e.key === "rulesData") {
      rulesData = safeParseObject("rulesData", rulesData);
      var rEl = document.getElementById("rulesContainer");
      if (
        rEl &&
        !document.getElementById("sectionRules").classList.contains("hidden")
      ) {
        try {
          renderRules();
        } catch (err) {}
      }
    }
  } catch (err) {
    console.warn("storage sync:", err);
  }
});
