function playSound(type) {
  var u = current();
  if (u && u.notificationSettings && u.notificationSettings.sounds === false)
    return;
  var vol =
    u &&
    u.notificationSettings &&
    typeof u.notificationSettings.volume === "number"
      ? u.notificationSettings.volume
      : 0.7;
  if (vol <= 0) return;
  try {
    var ctx = getAudioCtx();
    if (!ctx) return;
    if (ctx.state === "suspended") ctx.resume();
    var preset = SOUND_PRESETS[type];
    if (!preset) return;
    var t = ctx.currentTime;
    preset.notes.forEach(function (n) {
      playTone(ctx, n[0], t + n[1], n[2], n[3], (n[4] || 0.12) * vol);
    });
  } catch (e) {}
}

