var roleColors = safeParseObject("roleColors", {});
function saveRoleColors() {
  return _safeSet("roleColors", roleColors, "цвета ролей");
}
function getRoleColor(role) {
  if (!role) return "";
  var c = roleColors[role];
  // Если это обычный цвет (HEX) — возвращаем его
  if (c && (/^#[0-9a-fA-F]{6}$/.test(c) || c.indexOf("linear-gradient") === 0))
    return c;
  // Если это градиент — возвращаем его как есть
  if (c && c.indexOf("linear-gradient") === 0) return c;

  // fallback: сохраняем внешний вид «из коробки» через существующие CSS-классы
  var cls = roleClass(role);
  if (cls === "ga") return "#e5c35c";
  if (cls === "admin") return "#ff7e87";
  if (cls === "mod") return "#73b7ff";
  if (cls === "dev") return "#c890ff";
  return "";
}
function roleStyle(role) {
  var c = getRoleColor(role);
  return c ? "color:" + c + ";font-weight:700;" : "";
}
function roleLabelHtml(role, withIcon) {
  var c = getRoleColor(role);

  // font-size: 1.8em (размер), transform: translateY(-15%) (подъем на 15% от своего размера)
  var icon = withIcon
    ? '<span style="font-size:1.8em; display:inline-block; transform:translateY(-15%); margin-right:6px; line-height:1; vertical-align:middle;">' +
      (ROLE_ICONS[role] || "👤") +
      "</span>"
    : "";

  if (!c)
    return (
      '<span class="muted" style="font-size:11px;">' +
      icon +
      esc(role) +
      "</span>"
    );
  return (
    '<span style="font-size:11px;color:' +
    c +
    ';font-weight:700;">' +
    icon +
    esc(role) +
    "</span>"
  );
}

