function getTrustLevel(t) {
  t = Math.max(0, Math.min(100, Number(t) || 0));
  for (var i = TRUST_LEVELS.length - 1; i >= 0; i--)
    if (t >= TRUST_LEVELS[i].min) return TRUST_LEVELS[i];
  return TRUST_LEVELS[0];
}
function getTrustLevelIdx(t) {
  return TRUST_LEVELS.indexOf(getTrustLevel(t));
}
