/* ═══════ ЕДИНАЯ СИСТЕМА: TRUST = БАЗА + БОНУС ЗА АКТИВНОСТЬ ═══════ */
var TRUST_ACTIVITY_WEIGHT = 30; // макс. бонус/штраф за активность
var TRUST_ACTIVITY_TARGET = 300; // KPI, при котором бонус = 0

// Миграция: старый user.trust → user.trustBase. Вызывается один раз при init.
function migrateTrustToBase() {
  var changed = false;
  users.forEach(function (u) {
    if (!u || typeof u !== "object") return;
    if (u.trustBase === undefined) {
      u.trustBase =
        typeof u.trust === "number" && isFinite(u.trust)
          ? u.trust
          : trustSettings.start;
      changed = true;
    }
  });
  if (changed) saveUsers();
}

// Активность за ВСЁ время (для бонуса trust, без компоненты trust)
function computeActivityScore(user) {
  if (!user) return 0;
  var w = kpiConfig && kpiConfig.weights ? kpiConfig.weights : {};
  var num = function (v) {
    var n = Number(v);
    return isFinite(n) ? n : 0;
  };
  var doneTasks = tasks.filter(function (t) {
    return t.assignee === user.id && t.status === "done";
  });
  var onTime = doneTasks.filter(function (t) {
    return !t.deadline;
  }).length;
  var onTimeRate = doneTasks.length
    ? Math.round((onTime / doneTasks.length) * 100)
    : 0;
  return Math.round(
    doneTasks.length * num(w.tasksDone) +
      onTimeRate * num(w.onTimeRate) +
      transfers.filter(function (t) {
        return t.fromId === user.id;
      }).length *
        num(w.transfers) +
      (user.lootboxHistory || []).length * num(w.lootboxes) +
      (user.spinHistory || []).length * num(w.spins),
  );
}

// Итоговый рейтинг — ЭТО ЧИСЛО ИСПОЛЬЗУЕТСЯ ВЕЗДЕ ВМЕСТО user.trust
function getEffectiveTrust(user) {
  if (!user) return 0;
  // Если trustBase равен 0, он так и останется 0
  var base = 0;
  if (typeof user.trustBase === "number" && isFinite(user.trustBase)) {
    base = user.trustBase;
  } else if (typeof user.trust === "number" && isFinite(user.trust)) {
    base = user.trust;
  } else {
    base = trustSettings.start || 0;
  }
  base = Math.max(0, Math.min(100, base));
  var kpi = computeActivityScore(user);
  var bonus =
    ((kpi - TRUST_ACTIVITY_TARGET) / TRUST_ACTIVITY_TARGET) *
    TRUST_ACTIVITY_WEIGHT;
  bonus = Math.max(
    -TRUST_ACTIVITY_WEIGHT,
    Math.min(TRUST_ACTIVITY_WEIGHT, bonus),
  );
  return Math.max(0, Math.min(100, Math.round(base + bonus)));
}
