/* ============ УТИЛИТЫ ============ */
function uid() {
  return crypto.randomUUID
    ? crypto.randomUUID()
    : Date.now() + "_" + Math.random().toString(36).slice(2);
}
function generateSalt() {
  var arr = new Uint8Array(16);
  if (crypto.getRandomValues) crypto.getRandomValues(arr);
  else for (var i = 0; i < 16; i++) arr[i] = Math.floor(Math.random() * 256);
  return Array.from(arr)
    .map(function (x) {
      return x.toString(16).padStart(2, "0");
    })
    .join("");
}

async function hashPassword(p, salt) {
  try {
    if (
      !(typeof crypto !== "undefined" && crypto.subtle && crypto.subtle.digest)
    )
      throw new Error("no_subtle");
    var d = new TextEncoder().encode((salt || "") + ":" + p);
    var h = await crypto.subtle.digest("SHA-256", d);
    return Array.from(new Uint8Array(h))
      .map(function (x) {
        return x.toString(16).padStart(2, "0");
      })
      .join("");
  } catch (e) {
    var s = 5381;
    var str = String((salt || "") + ":" + (p || ""));
    for (var i = 0; i < str.length; i++) {
      s = (((s * 33) >>> 0) ^ str.charCodeAt(i)) >>> 0;
    }
    return "legacy_" + s.toString(16).padStart(8, "0");
  }
}
/* FIX #63: esc безопасен для HTML-текста и для значений в ДВОЙНЫХ кавычках.
   ⚠️ НЕЛЬЗЯ пихать в onclick="fn('...')" — там используйте jsArg() или escJs(). */
function esc(v) {
  if (v === null || v === undefined) v = "";
  return String(v).replace(/[&<>"']/g, function (m) {
    return {
      "&": "&amp;",
      "<": "&lt;",
      ">": "&gt;",
      '"': "&quot;",
      "'": "&#039;",
    }[m];
  });
}

/* FIX #63: esc для содержимого JS-строки внутри атрибута с одинарными кавычками.
   Использование: onclick="fn('...'+escJs(x)+'...')" */
function escJs(v) {
  var s = String(v === null || v === undefined ? "" : v);
  s = s
    .replace(/\\/g, "\\\\")
    .replace(/'/g, "\\'")
    .replace(/\r/g, "\\r")
    .replace(/\n/g, "\\n")
    .replace(/</g, "\\u003c")
    .replace(/>/g, "\\u003e");
  s = s.replace(/&/g, "&amp;").replace(/"/g, "&quot;");
  return s;
}
function jsArg(v) {
  return esc(JSON.stringify(v === undefined ? null : v));
}
// FIX: хелперы для безопасной подстановки в style / url() контексты
function safeColor(c) {
  return typeof c === "string" && /^#[0-9a-fA-F]{6}$/.test(c) ? c : "";
}
function nickStyle(u, extra) {
  var c = safeColor(u && u.nickColor);
  return c ? "color:" + c + ";font-weight:800;" + (extra || "") : "";
}
function safeUrl(url) {
  if (!url) return "";
  var s = String(url).trim();
  if (!/^(https?:\/\/|data:image\/[a-z+]+;)/i.test(s)) return "";
  return s.replace(/['"()\\<>\s]/g, function (c) {
    return "%" + c.charCodeAt(0).toString(16).padStart(2, "0");
  });
}
function dateNow() {
  return new Date().toISOString().slice(0, 10);
}
function fmtDate(d) {
  if (!d) return "";
  try {
    var dt = new Date(d);
    if (isNaN(dt.getTime())) return String(d);
    return dt.toLocaleDateString("ru-RU", {
      day: "2-digit",
      month: "short",
      year: "numeric",
    });
  } catch (e) {
    return String(d);
  }
}
function initials(name) {
  var s = String(name || "?").trim();
  if (!s) return "?";
  var parts = s.split(/\s+/).slice(0, 2);
  var out = "";
  for (var i = 0; i < parts.length; i++) {
    if (parts[i] && parts[i][0]) out += parts[i][0];
  }
  return out.toUpperCase() || "?";
}
function fmtBalance(v) {
  var n = Number(v) || 0;
  var neg = n < 0;
  n = Math.abs(Math.round(n));
  var s = n.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  return (neg ? "-" : "") + s;
}
/* FIX: расставляет разделители тысяч в подписях призов,
   которые хранятся готовыми строками ('💵 15000 ₽' → '💵 15,000 ₽') */
function formatLabelNumbers(label) {
  if (label === null || label === undefined) return label;
  return String(label).replace(/\d{4,}/g, function (m) {
    return m.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
  });
}
function roleClass(role) {
  if (role === "Гл. Администратор") return "ga";
  if (role.indexOf("Администратор") !== -1) return "admin";
  if (role.indexOf("Модератор") !== -1) return "mod";
  if (role === "Разработчик") return "dev";
  return "";
}
function downloadCSV(filename, rows) {
  var csv = rows
    .map(function (r) {
      return r
        .map(function (v) {
          return '"' + String(v == null ? "" : v).replace(/"/g, '""') + '"';
        })
        .join(";");
    })
    .join("\r\n");
  var a = document.createElement("a");
  a.href = URL.createObjectURL(
    new Blob(["\uFEFF" + csv], { type: "text/csv;charset=utf-8" }),
  );
  a.download = filename;
  a.click();
  URL.revokeObjectURL(a.href);
}
/* FIX: сокращает длинный список до «первые N + и ещё M».
   Используется в уведомлениях и логах, чтобы длинные выдачи не превращались в «кашу». */
function summarizeList(items, maxShow) {
  if (!Array.isArray(items)) items = [];
  maxShow = typeof maxShow === "number" && maxShow > 0 ? maxShow : 3;
  if (items.length <= maxShow) return items.join(", ");
  return (
    items.slice(0, maxShow).join(", ") + " и ещё " + (items.length - maxShow)
  );
}

