/* ============ ПОСТОЯННЫЕ РАЗБЛОКИРОВКИ (не кладём в инвентарь) ============ */
function isPermanentUnlockEffect(eff) {
  if (!eff) return false;
  if (
    eff === "unlockNickColor" ||
    eff === "unlockProfileAnim" ||
    eff === "unlockAdvancedStats" ||
    eff === "unlockProfileBg"
  )
    return true;
  if (eff.indexOf("unlockMultiOpen:") === 0) return true;
  return false;
}
function permanentUnlockLabel(eff) {
  if (eff === "unlockNickColor") return "🎨 Цвет ника";
  if (eff === "unlockProfileAnim") return "✨ Анимация профиля";
  if (eff === "unlockAdvancedStats") return "📊 Расширенная статистика";
  if (eff === "unlockProfileBg") return "🖼 Фон профиля";
  if (eff.indexOf("unlockMultiOpen:") === 0) {
    var _mn = parseInt(eff.split(":")[1], 10);
    return "🎰 Мульти-открытие ×" + _mn;
  }
  return eff;
}
function hasPermanentUnlock(user, eff) {
  if (!user || !eff) return false;
  if (eff === "unlockNickColor") return !!user.canNickColor;
  if (eff === "unlockProfileAnim") return !!user.canProfileAnim;
  if (eff === "unlockAdvancedStats") return !!user.canAdvancedStats;
  if (eff === "unlockProfileBg") return !!user.canProfileBg;
  if (eff.indexOf("unlockMultiOpen:") === 0) {
    var _mn = parseInt(eff.split(":")[1], 10);
    if (!user.multiOpen) return false;
    if (_mn === 3) return !!user.multiOpen.x3;
    if (_mn === 5) return !!user.multiOpen.x5;
    if (_mn === 10) return !!user.multiOpen.x10;
  }
  return false;
}
function applyPermanentUnlock(user, eff) {
  if (!user || !eff) return false;
  if (eff === "unlockNickColor") {
    user.canNickColor = true;
    return true;
  }
  if (eff === "unlockProfileAnim") {
    user.canProfileAnim = true;
    return true;
  }
  if (eff === "unlockAdvancedStats") {
    user.canAdvancedStats = true;
    return true;
  }
  if (eff === "unlockProfileBg") {
    user.canProfileBg = true;
    return true;
  }
  if (eff.indexOf("unlockMultiOpen:") === 0) {
    var _mn = parseInt(eff.split(":")[1], 10);
    if (!user.multiOpen) user.multiOpen = { x3: false, x5: false, x10: false };
    if (_mn === 3) {
      user.multiOpen.x3 = true;
      return true;
    }
    if (_mn === 5) {
      user.multiOpen.x5 = true;
      return true;
    }
    if (_mn === 10) {
      user.multiOpen.x10 = true;
      return true;
    }
  }
  return false;
}
