/* FIX: схлопываем старые дубликаты непрочитанных уведомлений */
(function cleanDuplicateNotifs() {
  try {
    var groups = {};
    notifications.forEach(function (n) {
      if (!n || !n.text || !n.userId) return;
      var key = n.userId + "|" + n.text;
      if (!groups[key]) groups[key] = [];
      groups[key].push(n);
    });
    var toRemove = {};
    Object.keys(groups).forEach(function (key) {
      var list = groups[key];
      if (list.length <= 1) return;
      list.sort(function (a, b) {
        return new Date(b.time) - new Date(a.time);
      });
      var kept = false;
      list.forEach(function (n) {
        if (!n.read) {
          if (kept) toRemove[n.id] = 1;
          else kept = true;
        }
      });
    });
    var removed = 0;
    notifications = notifications.filter(function (n) {
      if (toRemove[n.id]) {
        removed++;
        return false;
      }
      return true;
    });
    if (removed > 0) saveNotifications();
  } catch (e) {
    console.warn("cleanDuplicateNotifs:", e);
  }
})();
