/* ============================================================
KPI
============================================================ */
function computeKPI(user, period) {
  if (!user)
    return {
      tasks: 0,
      onTimeRate: 0,
      transfers: 0,
      lootboxes: 0,
      spins: 0,
      trust: 0,
      score: 0,
    };
  var w =
    kpiConfig && kpiConfig.weights && typeof kpiConfig.weights === "object"
      ? kpiConfig.weights
      : {
          tasksDone: 5,
          onTimeRate: 1,
          transfers: 1,
          lootboxes: 2,
          spins: 1,
          trust: 0.5,
        };
  var num = function (v) {
    var n = Number(v);
    return isFinite(n) ? n : 0;
  };
  var since =
    period === "week"
      ? Date.now() - 7 * 86400000
      : period === "month"
        ? Date.now() - 30 * 86400000
        : 0;
  var userTasks = (tasks || []).filter(function (t) {
    if (!t || t.assignee !== user.id || t.status !== "done") return false;
    if (since && new Date(t.createdAt || 0).getTime() < since) return false;
    return true;
  });
  var onTime = userTasks.filter(function (t) {
    return !t.deadline;
  }).length;
  var onTimeRate = userTasks.length
    ? Math.round((onTime / userTasks.length) * 100)
    : 0;
  var uTransfers = (transfers || []).filter(function (t) {
    if (!t || t.fromId !== user.id) return false;
    if (since && new Date(t.time).getTime() < since) return false;
    return true;
  }).length;
  var uLoot = (user.lootboxHistory || []).filter(function (l) {
    if (!l || !l.time) return true;
    if (since && new Date(l.time).getTime() < since) return false;
    return true;
  }).length;
  var uSpins = (user.spinHistory || []).filter(function (s) {
    if (!s || !s.time) return true;
    if (since && new Date(s.time).getTime() < since) return false;
    return true;
  }).length;
  var score = Math.round(
    userTasks.length * num(w.tasksDone) +
      onTimeRate * num(w.onTimeRate) +
      uTransfers * num(w.transfers) +
      uLoot * num(w.lootboxes) +
      uSpins * num(w.spins),
  );
  if (!isFinite(score)) score = 0;
  if (!isFinite(score)) score = 0;
  return {
    tasks: userTasks.length,
    onTimeRate: onTimeRate,
    transfers: uTransfers,
    lootboxes: uLoot,
    spins: uSpins,
    trust: getEffectiveTrust(user),
    score: score,
  };
}

function renderKPI() {
  renderLeaderboard();
}

/* ══════════════════════════════════════════════════════════════
   ШАБЛОНЫ ЗАДАЧ v4.5 (Команды, Награды, Чек-листы, Авто-повтор) + ЛИДЕРБОРД НЕДЕЛИ
   ══════════════════════════════════════════════════════════════ */
function _saveTaskTemplates() {
  try {
    if (typeof saveTaskTemplates === "function") {
      saveTaskTemplates();
      return;
    }
    localStorage.setItem(
      "taskTemplates",
      JSON.stringify(taskTemplates || new Array()),
    );
  } catch (_) {}
}

function processRecurringTaskTemplates() {
  if (!Array.isArray(taskTemplates) || !taskTemplates.length) return;
  var now = Date.now();
  var todayStr = new Date().toISOString().slice(0, 10);
  var createdCnt = 0;

  taskTemplates.forEach(function (tpl) {
    if (!tpl.recurrence || tpl.recurrence === "none") return;
    var lastRun = tpl.lastRunAt ? new Date(tpl.lastRunAt).getTime() : 0;
    var intervalMs = tpl.recurrence === "weekly" ? 7 * 86400000 : 86400000;
    if (tpl.lastRunDate === todayStr) return;
    if (lastRun && now - lastRun < intervalMs - 3600000) return;

    _spawnTaskFromTemplate(tpl, true);
    tpl.lastRunAt = new Date().toISOString();
    tpl.lastRunDate = todayStr;
    createdCnt++;
  });

  if (createdCnt > 0) {
    _saveTaskTemplates();
    saveTasks();
    toast("🔄 Авто-повтор: создано задач по шаблонам (" + createdCnt + ")");
  }
}

function _spawnTaskFromTemplate(tpl, isAuto) {
  if (!tpl) return null;
  var au = tpl.assigneeId
    ? users.find(function (u) {
        return u.id === tpl.assigneeId;
      })
    : null;
  var offsetDays = Math.max(0, Number(tpl.deadlineOffsetDays) || 0);
  var deadlineStr = "";
  if (offsetDays > 0) {
    var d = new Date(Date.now() + offsetDays * 86400000);
    deadlineStr = d.toISOString().slice(0, 10);
  }
  var clLines = Array.isArray(tpl.checklist)
    ? tpl.checklist.map(function (c) {
        return { text: typeof c === "string" ? c : c.text, done: false };
      })
    : new Array();

  var newTask = {
    id: uid(),
    title: tpl.title,
    description: tpl.description || "",
    assignee: au ? au.id : "",
    assignees: au ? new Array(au.id) : new Array(),
    assigneeName: au ? au.name : "",
    maxAssignees: Math.min(20, Math.max(1, Number(tpl.maxAssignees) || 1)),
    rewardMode: tpl.rewardMode || "each",
    createdBy: current() ? current().id : "system",
    createdAt: new Date().toISOString(),
    deadline: deadlineStr,
    priority: tpl.priority || "средний",
    status: "open",
    rewardCoins: Math.max(0, Number(tpl.rewardCoins) || 0),
    rewardBalance: Math.max(0, Number(tpl.rewardBalance) || 0),
    minTrust: Math.max(0, Number(tpl.minTrust) || 0),
    reqRole: tpl.assigneeRole || "",
    latePenaltyCoins: Math.max(0, Number(tpl.latePenaltyCoins) || 0),
    lateDiscountPct: Math.min(
      100,
      Math.max(0, Number(tpl.lateDiscountPct) || 0),
    ),
    dependsOn: "",
    checklist: clLines,
    comments: new Array(),
    history: new Array(),
  };

  logTaskEvent(
    newTask,
    isAuto ? "🔄" : "📋",
    isAuto
      ? "Создано автоматически по шаблону «" + tpl.title + "»"
      : "Запущено из шаблона «" + tpl.title + "»",
  );
  tasks.unshift(newTask);

  if (au && (!current() || au.id !== current().id)) {
    addNotification(au.id, "📋 Новая задача по шаблону: " + tpl.title);
  }
  return newTask;
}

function runTaskTemplate(tplId) {
  if (!checkBlocked()) return;
  if (!can(current(), "create_task")) {
    toast("❌ Нет прав");
    return;
  }
  var tpl = taskTemplates.find(function (x) {
    return x.id === tplId;
  });
  if (!tpl) return;
  _spawnTaskFromTemplate(tpl, false);
  tpl.lastRunAt = new Date().toISOString();
  tpl.lastRunDate = new Date().toISOString().slice(0, 10);
  _saveTaskTemplates();
  saveTasks();
  playSound("click");
  toast("🚀 Задача создана из шаблона!");
  renderTasks();
}

function deleteTaskTemplate(tplId) {
  if (!checkBlocked()) return;
  var idx = taskTemplates.findIndex(function (x) {
    return x.id === tplId;
  });
  if (idx === -1) return;
  if (!confirm("Удалить шаблон задачи?")) return;
  taskTemplates.splice(idx, 1);
  _saveTaskTemplates();
  playSound("click");
  toast("🗑 Шаблон удалён");
  renderTasks();
}

