function saveTaskTemplate(tplId) {
  var title = (document.getElementById("tplTitle")?.value || "").trim();
  if (!title) {
    toast("Введите название шаблона");
    return;
  }
  if (!Array.isArray(taskTemplates)) taskTemplates = new Array();

  var clLines = (document.getElementById("tplChecklist")?.value || "")
    .split("\n")
    .map(function (s) {
      return s.trim();
    })
    .filter(Boolean);
  var payload = {
    id: tplId || uid(),
    title: title,
    description: (document.getElementById("tplDesc")?.value || "").trim(),
    assigneeId: document.getElementById("tplAssignee")?.value || "",
    assigneeRole: document.getElementById("tplRole")?.value || "",
    priority: document.getElementById("tplPrio")?.value || "средний",
    recurrence: document.getElementById("tplRecurrence")?.value || "none",
    deadlineOffsetDays: Math.max(
      0,
      Number(document.getElementById("tplOffsetDays")?.value) || 0,
    ),
    maxAssignees: Math.min(
      20,
      Math.max(
        1,
        Number(document.getElementById("tplMaxAssignees")?.value) || 1,
      ),
    ),
    rewardMode: document.getElementById("tplRewardMode")?.value || "each",
    rewardCoins: Math.max(
      0,
      Number(document.getElementById("tplRewardCoins")?.value) || 0,
    ),
    rewardBalance: Math.max(
      0,
      Number(document.getElementById("tplRewardBalance")?.value) || 0,
    ),
    minTrust: Math.max(
      0,
      Number(document.getElementById("tplMinTrust")?.value) || 0,
    ),
    checklist: clLines,
  };
  var idx = tplId
    ? taskTemplates.findIndex(function (x) {
        return x.id === tplId;
      })
    : -1;
  if (idx !== -1) {
    payload.lastRunAt = taskTemplates.at(idx).lastRunAt || "";
    payload.lastRunDate = taskTemplates.at(idx).lastRunDate || "";
    taskTemplates.splice(idx, 1, payload);
  } else {
    taskTemplates.unshift(payload);
  }
  _saveTaskTemplates();
  closeModal();
  playSound("click");
  toast("💾 Шаблон сохранён");
  renderTasks();
}
