function saveWealthTax() {
  wealthTaxConfig.enabled = document.getElementById("wtEnabled").value === "1";
  wealthTaxConfig.threshold =
    parseAmountInput(document.getElementById("wtThreshold").value) || 100000;
  wealthTaxConfig.rate = Math.max(
    0.1,
    Math.min(50, parseFloat(document.getElementById("wtRate").value) || 2),
  );
  wealthTaxConfig.periodDays = Math.max(
    1,
    parseInt(document.getElementById("wtPeriod").value, 10) || 7,
  );
  saveWealthTaxConfig();
  toast("💾 Настройки налога сохранены");
  renderWealthTaxUI();
}

/* ============================================================
   СЕЗОННЫЕ СОБЫТИЯ — ПРЕСЕТЫ
   ============================================================ */
function launchSeasonalPreset(presetKey) {
  if (!checkBlocked()) return;
  if (!can(current(), "manage_shop")) return;
  var preset = SEASONAL_EVENT_PRESETS[presetKey];
  if (!preset) return;
  if (
    !confirm("Запустить «" + preset.name + "» на " + preset.duration + " дн.?")
  )
    return;
  var start = new Date().toISOString().slice(0, 10);
  var end = new Date(Date.now() + preset.duration * 86400000)
    .toISOString()
    .slice(0, 10);
  seasonalEvents.push({
    id: uid(),
    name: preset.name,
    icon: preset.icon,
    startDate: start,
    endDate: end,
    effectType: "none",
    effectValue: 0,
    active: true,
    createdBy: current().name,
    createdAt: new Date().toISOString(),
  });
  lootboxes.push({
    id: uid(),
    name: preset.lootboxName,
    icon: preset.icon,
    description: "Сезонный · ограниченная серия",
    price: 0,
    currency: "coins",
    requiredKeyId: "seasonal",
    active: true,
    stock: 500,
    rarity: preset.lootboxRarity,
    prizes: preset.prizes.map(function (p) {
      return Object.assign({}, p);
    }),
    eventTag: presetKey,
  });
  saveSeasonalEvents();
  saveLootboxes();
  playSound("notify");
  toast("🎉 Событие «" + preset.name + "» до " + fmtDate(end), "success", {
    duration: 5000,
  });
  addLog("Сезонное событие", preset.name);
  checkSeasonalEvent();
  renderShop();
  try {
    renderLootboxes();
  } catch (e) {}
  try {
    renderSeasonalManager();
  } catch (e) {}
}
function renderSeasonalManager() {
  var el = document.getElementById("seasonalEventsManagerContainer");
  if (!el) return;
  var user = current();
  if (!user || !can(user, "manage_shop")) {
    el.innerHTML = "";
    return;
  }
  var html = '<section class="card">';
  html +=
    '<div class="toolbar"><h3 style="margin:0;">🎉 Сезонные события</h3></div>';
  html += '<div style="padding:16px;">';
  html +=
    '<div class="muted" style="font-size:13px;margin-bottom:12px;">Быстрый запуск готового шаблона:</div>';
  html +=
    '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:10px;">';
  Object.keys(SEASONAL_EVENT_PRESETS).forEach(function (k) {
    var p = SEASONAL_EVENT_PRESETS[k];
    html +=
      '<button class="btn" style="padding:16px;flex-direction:column;align-items:flex-start;text-align:left;height:auto;" onclick="launchSeasonalPreset(' +
      jsArg(k) +
      ')">';
    html +=
      '<div style="font-size:24px;margin-bottom:4px;">' + p.icon + "</div>";
    html +=
      '<div style="font-weight:800;font-size:14px;">' + esc(p.name) + "</div>";
    html +=
      '<div style="font-size:11px;color:var(--muted);margin-top:2px;">' +
      p.duration +
      " дней · " +
      p.prizes.length +
      " призов</div>";
    html += "</button>";
  });
  html += "</div>";
  var activeEvents = seasonalEvents.filter(function (e) {
    if (!e.active) return false;
    var now = new Date();
    return (
      now >= new Date(e.startDate + "T00:00:00") &&
      now <= new Date(e.endDate + "T23:59:59")
    );
  });
  if (activeEvents.length) {
    html +=
      '<div style="margin-top:20px;"><b style="font-size:13px;">🔥 Активные сейчас:</b></div>';
    activeEvents.forEach(function (e) {
      html +=
        '<div style="padding:10px 12px;background:#0d1a13;border:1px solid var(--accent);border-radius:10px;margin-top:6px;display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;">';
      html +=
        "<span>" +
        esc(e.icon || "🎉") +
        " <b>" +
        esc(e.name) +
        "</b> · до " +
        fmtDate(e.endDate) +
        "</span>";
      html +=
        '<button class="btn small danger" onclick="deleteSeasonalEvent(' +
        jsArg(e.id) +
        ')">✕</button></div>';
    });
  }
  html += "</div></section>";
  el.innerHTML = html;
}

