/* ============================================================
   EXCEL EXPORT
   ============================================================ */
function exportExcel(filename, sheets) {
  if (typeof XLSX === "undefined") {
    toast("❌ Библиотека XLSX не загружена", "error");
    return;
  }
  var wb = XLSX.utils.book_new();
  sheets.forEach(function (sh) {
    var ws = XLSX.utils.aoa_to_sheet(sh.rows);
    var colWidths = [];
    if (sh.rows.length) {
      for (var c = 0; c < sh.rows[0].length; c++) {
        var maxLen = 8;
        sh.rows.forEach(function (row) {
          var v = row[c] === null || row[c] === undefined ? "" : String(row[c]);
          if (v.length > maxLen) maxLen = v.length;
        });
        colWidths.push({ wch: Math.min(maxLen + 2, 50) });
      }
      ws["!cols"] = colWidths;
    }
    XLSX.utils.book_append_sheet(wb, ws, sh.name);
  });
  XLSX.writeFile(wb, filename);
}
