function current() {
  return users.find(function (u) {
    return u.id === currentId;
  });
}
function hasPermission(user, perm) {
  if (!user) return false;
  // Владелец и Разработчик всегда всё могут (и их нельзя ограничить)
  if (user.role === "Владелец" || user.role === "Разработчик") return true;
  // Личный запрет — приоритет выше всего (даже extraPermissions)
  if (
    Array.isArray(user.deniedPermissions) &&
    user.deniedPermissions.indexOf(perm) !== -1
  )
    return false;
  // Личное разрешение — приоритет выше роли
  if (
    Array.isArray(user.extraPermissions) &&
    user.extraPermissions.indexOf(perm) !== -1
  )
    return true;
  // Ролевые права
  return (rolePermissions[user.role] || []).indexOf(perm) !== -1;
}
function can(user, perm) {
  return hasPermission(user, perm);
}
/* Универсальный парсер дат «до какого числа» — поддерживает и YYYY-MM-DD, и полный ISO */
function parseUntilTs(raw) {
  if (!raw) return NaN;
  var s = String(raw).trim();
  if (!s) return NaN;
  if (s.indexOf("T") !== -1) return new Date(s).getTime();
  return new Date(s + "T23:59:59.999").getTime();
}
function isFrozen(u) {
  if (!u || u.frozen !== true) return false;
  if (u.frozenUntil) {
    var _fEnd = parseUntilTs(u.frozenUntil);
    if (isFinite(_fEnd) && _fEnd < Date.now()) return false;
  }
  return true;
}
function isOnVacation(u) {
  if (!u || u.onVacation !== true) return false;
  if (u.vacationUntil) {
    var _vEnd = parseUntilTs(u.vacationUntil);
    if (isFinite(_vEnd) && _vEnd < Date.now()) return false;
  }
  return true;
}
function checkBlocked() {
  var u = current();
  if (isFrozen(u)) {
    toast("❌ Заморожен");
    return false;
  }
  return true;
}

/* ═══════════════════════════════════════════════════════
   #20 — АУДИТ «КТО СЕЙЧАС ОНЛАЙН» (lastSeen)
   ═══════════════════════════════════════════════════════ */
function updateLastSeen() {
  var u = current();
  if (!u) return;
  u.lastSeen = Date.now();
  saveUsers();
}
setInterval(updateLastSeen, 60 * 1000);

function getOnlineStatus(u) {
  if (!u) return { icon: "⚫", label: "Оффлайн", cls: "badge-frozen" };
  var ts = Number(u.lastSeen) || 0;
  if (!ts) return { icon: "⚫", label: "Оффлайн", cls: "badge-frozen" };
  var diff = Date.now() - ts;
  if (diff < 2 * 60 * 1000)
    return { icon: "🟢", label: "В сети", cls: "badge-active" };
  if (diff < 60 * 60 * 1000) {
    var mins = Math.max(1, Math.floor(diff / 60000));
    return {
      icon: "🟡",
      label: "Был " + mins + " мин назад",
      cls: "badge-high",
    };
  }
  if (diff < 24 * 60 * 60 * 1000) {
    var hrs = Math.floor(diff / 3600000);
    return { icon: "🟡", label: "Был " + hrs + " ч назад", cls: "badge-high" };
  }
  var days = Math.floor(diff / (24 * 3600000));
  return {
    icon: "⚫",
    label: "Был " + days + " дн назад",
    cls: "badge-frozen",
  };
}

/* Универсальный бейдж: приоритет у заморозки/отпуска, иначе — онлайн-статус */
function renderUserStatusBadge(u) {
  if (!u) return "";
  if (isFrozen(u)) {
    var f = u.frozenUntil ? " до " + fmtDate(u.frozenUntil) : "";
    return '<span class="badge badge-frozen">❄️ Заморожен' + f + "</span>";
  }
  if (isOnVacation(u)) {
    var v = u.vacationUntil ? " до " + fmtDate(u.vacationUntil) : "";
    return '<span class="badge badge-vacation">🌴 Отпуск' + v + "</span>";
  }
  var st = getOnlineStatus(u);
  return (
    '<span class="badge ' +
    st.cls +
    '">' +
    st.icon +
    " " +
    esc(st.label) +
    "</span>"
  );
}
