/* ============ DISCORD SYNC ============ */
async function sendDiscordEvent(titleOrObj, fields, color) {
  if (!discordSettings.enabled || !discordSettings.webhookUrl) return false;
  if (
    !/^https:\/\/discord(app)?\.com\/api\/webhooks\//.test(
      discordSettings.webhookUrl,
    )
  )
    return false;

  var data;
  if (typeof titleOrObj === "string") {
    data = {
      title: titleOrObj,
      fields: fields || [],
      color: color || 0x39c982,
    };
  } else {
    data = titleOrObj || {};
  }

  var embed = {
    title: data.title || undefined,
    description: data.description || undefined,
    color: data.color !== undefined ? data.color : 0x39c982,
    fields: data.fields || [],
    timestamp: new Date().toISOString(),
  };

  if (data.thumbnail) embed.thumbnail = { url: data.thumbnail };
  if (data.author) embed.author = data.author;
  if (data.footer) embed.footer = data.footer;
  if (data.url) embed.url = data.url;

  Object.keys(embed).forEach(function (key) {
    if (embed[key] === undefined) delete embed[key];
  });

  var payload = {
    username: "SpaceWorld Team",
    embeds: [embed],
  };

  try {
    var r = await fetch(discordSettings.webhookUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    return r.ok;
  } catch (e) {
    console.warn("Discord webhook failed:", e);
    return false;
  }
}

/* ============ БУФЕР ДЛЯ ОБЪЕДИНЕНИЯ СОБЫТИЙ ============ */
var _discordPending = {}; // { userId: { user, role, status, timer } }

function _scheduleDiscordFlush(userId) {
  var entry = _discordPending[userId];
  if (!entry) return;
  if (entry.timer) clearTimeout(entry.timer);
  entry.timer = setTimeout(function () {
    _flushDiscordPending(userId);
  }, 80);
}

function _flushDiscordPending(userId) {
  var p = _discordPending[userId];
  if (!p) return;
  delete _discordPending[userId];
  if (p.timer) clearTimeout(p.timer);

  if (!p.user || !p.user.discordId) return;
  if (!discordSettings.enabled || !discordSettings.webhookUrl) return;

  var role = p.role;
  var status = p.status;
  if (!role && !status) return;

  var user = p.user;

  // ── Заголовок ──
  var title;
  if (role && status) title = "🔄 Обновление профиля";
  else if (role)
    title = role.frozen
      ? "❄️ Заморозка сотрудника"
      : role.isDemotion
        ? "📉 Снятие с должности"
        : "🔄 Смена роли";
  else title = "🔔 Смена статуса";

  // ── Описание (цитата) ──
  var desc = "";
  function _md(s) {
    return String(s == null ? "" : s).replace(/([\\*_~`|>])/g, "\\$1");
  }
  desc += "> **Сотрудник:** " + _md(user.name) + "\n";
  desc += "> **Discord ID:** `" + user.discordId + "`\n";
  desc += "> **Роль на сайте:** " + _md(user.role) + "\n";
  if (role) desc += "> **Действие:** " + _md(role.actionText) + "\n";
  if (status) desc += "> **Новый статус:** " + _md(status.label) + "\n";

  // ── Цвет (приоритет: заморозка > снятие > выговор > отпуск > обычный) ──
  var color = 0x39c982;
  if ((status && status.status === "frozen") || (role && role.frozen))
    color = 0x7ad1ff;
  else if (role && role.isDemotion) color = 0xe45c6d;
  else if (status && status.status === "warned") color = 0xe5c35c;
  else if (status && status.status === "vacation") color = 0xe5e35c;

  // ── Поля ──
  var fields = [];

  if (role) {
    fields.push({
      name: "🎭 Роль",
      value: role.roleName || user.role,
      inline: true,
    });
    if (role.roleId)
      fields.push({
        name: "🆔 Новая роль (ID)",
        value: "`" + role.roleId + "`",
        inline: true,
      });
  }

  if (status) {
    fields.push({ name: "📌 Статус", value: status.label, inline: true });
    if (status.roleId)
      fields.push({
        name: "🎭 Роль статуса (ID)",
        value: "`" + status.roleId + "`",
        inline: true,
      });
    if (status.until)
      fields.push({
        name: "⏱ Действует до",
        value: status.until,
        inline: true,
      });
  }

  // Базовая роль
  if (discordSettings.baseRoleId) {
    var baseAction =
      (role && (role.frozen || role.isDemotion)) ||
      (status && status.status === "frozen")
        ? "🔴 Снята"
        : "🟢 Выдана";
    fields.push({
      name: "🛡️ Базовая роль",
      value: "`" + discordSettings.baseRoleId + "` (" + baseAction + ")",
      inline: true,
    });
  }

  // Снятые роли
  if (role && role.rolesToRemove) {
    var formattedRemove = role.rolesToRemove
      .split(",")
      .map(function (id) {
        return "`" + id + "`";
      })
      .join(", ");
    fields.push({
      name: "🗑️ Снятые роли",
      value: formattedRemove,
      inline: false,
    });
  }

  // Синхронизация статусов
  if (status && status.allStatusIds) {
    var formattedSync = status.allStatusIds
      .split(",")
      .map(function (id) {
        return "`" + id + "`";
      })
      .join(", ");
    fields.push({
      name: "🔄 Синхронизация",
      value: formattedSync,
      inline: false,
    });
  }

  // Причина
  var reason = (status && status.reason) || (role && role.reason);
  if (reason)
    fields.push({
      name: "📝 Причина",
      value: String(reason).slice(0, 200),
      inline: false,
    });

  // Миниатюра
  var thumb = null;
  if (user.avatar && /^https?:\/\//.test(user.avatar)) thumb = user.avatar;

  sendDiscordEvent({
    title: title,
    description: desc,
    color: color,
    fields: fields,
    thumbnail: thumb,
    author: { name: "SpaceWorld Team Manager" },
    footer: {
      text:
        "Guild ID: " +
        (discordSettings.guildId || "—") +
        " • " +
        (role && status
          ? "Роль + Статус"
          : role
            ? "Событие роли"
            : "Событие статуса"),
    },
  });
}
/* ============ /БУФЕР ============ */

function syncDiscordRole(user, roleName) {
  if (!discordSettings.enabled || !discordSettings.sendOnRoleChange) return;
  if (!user || !user.discordId) return;

  var frozen = isFrozen(user);
  var roleId = discordSettings.roleMap[roleName || user.role] || "";
  var isDemotion = roleName === "Пользователь" && !frozen;
  var allIds = Object.keys(discordSettings.roleMap)
    .map(function (k) {
      return discordSettings.roleMap[k];
    })
    .filter(Boolean)
    .join(",");

  var rolesToRemove = "";
  if (frozen || isDemotion) rolesToRemove = allIds;

  var actionText = frozen
    ? "❄️ Принудительная заморозка"
    : isDemotion
      ? "📉 Снятие с должности"
      : "🔄 Выдача роли";

  if (!_discordPending[user.id])
    _discordPending[user.id] = {
      user: user,
      role: null,
      status: null,
      timer: null,
    };
  _discordPending[user.id].user = user;
  _discordPending[user.id].role = {
    roleName: roleName || user.role,
    roleId: roleId,
    isDemotion: isDemotion,
    frozen: frozen,
    allIds: allIds,
    rolesToRemove: rolesToRemove,
    actionText: actionText,
  };
  _scheduleDiscordFlush(user.id);
}

function notifyDiscordStatus(user, status, extra) {
  if (!discordSettings.enabled || !discordSettings.sendOnStatusChange) return;
  if (!user || !user.discordId) return;

  var roleId = discordSettings.statusRoleMap[status] || "";

  var allStatusIds = "";
  if (status !== "warned") {
    allStatusIds = ["frozen", "vacation", "active"]
      .filter(function (k) {
        return k !== status;
      })
      .map(function (k) {
        return discordSettings.statusRoleMap[k];
      })
      .filter(Boolean)
      .join(",");
  }

  if (!allStatusIds && !discordSettings.baseRoleId && !roleId) return;

  var labels = {
    frozen: "❄️ Заморозка",
    vacation: "🌴 Отпуск",
    warned: "⚠️ Выговор",
    active: "🟢 В сети",
  };

  if (!_discordPending[user.id])
    _discordPending[user.id] = {
      user: user,
      role: null,
      status: null,
      timer: null,
    };
  _discordPending[user.id].user = user;
  _discordPending[user.id].status = {
    status: status,
    label: labels[status] || status,
    roleId: roleId,
    allStatusIds: allStatusIds,
    reason: extra && extra.reason ? extra.reason : null,
    until: extra && extra.until ? extra.until : null,
  };
  _scheduleDiscordFlush(user.id);
}

function syncDiscordUser(userId) {
  if (!checkBlocked()) return;
  if (!can(current(), "manage_permissions")) {
    toast("❌ Нет прав", "error");
    return;
  }
  var u = users.find(function (x) {
    return x.id === userId;
  });
  if (!u) return;
  if (!u.discordId) {
    toast("❌ У пользователя не указан Discord ID", "error");
    return;
  }
  if (!discordSettings.enabled || !discordSettings.webhookUrl) {
    toast("❌ Discord интеграция выключена или не настроена", "error");
    return;
  }
  if (!rateLimit("syncDiscordUser")) return;
  syncDiscordRole(u, u.role);
  var status = "active";
  if (isFrozen(u)) status = "frozen";
  else if (isOnVacation(u)) status = "vacation";
  else if (u.warned) status = "warned";
  var extra = {
    reason: u.frozenReason || u.vacationReason || u.warnedReason || "",
  };
  if (status === "frozen" || status === "vacation")
    extra.until = u.frozenUntil || u.vacationUntil;
  notifyDiscordStatus(u, status, extra);
  playSound("click");
  toast("🎮 Запрос на синхронизацию для " + u.name + " отправлен");
}

