// ============ DISCORD OAUTH2 (IMPLICIT GRANT) ============
var DISCORD_CLIENT_ID = "1474841846910812232"; // <-- ВСТАВЬТЕ СЮДА ВАШ CLIENT ID
var DISCORD_REDIRECT_URI = window.location.origin + window.location.pathname;
var DISCORD_SCOPES = "identify";

function startDiscordOAuth() {
  if (!checkBlocked()) return;
  var authUrl =
    "https://discord.com/oauth2/authorize?" +
    "client_id=" +
    encodeURIComponent(DISCORD_CLIENT_ID) +
    "&redirect_uri=" +
    encodeURIComponent(DISCORD_REDIRECT_URI) +
    "&response_type=token" +
    "&scope=" +
    encodeURIComponent(DISCORD_SCOPES);
  window.location.href = authUrl;
}

async function handleDiscordOAuthCallback() {
  var hash = window.__DISCORD_OAUTH_HASH || window.location.hash;
  window.__DISCORD_OAUTH_HASH = "";
  if (!hash || hash.indexOf("access_token=") === -1) return false;

  var params = new URLSearchParams(hash.substring(1));
  var accessToken = params.get("access_token");
  if (!accessToken) return false;

  history.replaceState(
    null,
    "",
    window.location.pathname + window.location.search,
  );

  try {
    var response = await fetch("https://discord.com/api/v10/users/@me", {
      headers: { Authorization: "Bearer " + accessToken },
    });
    if (!response.ok)
      throw new Error("Не удалось получить данные пользователя из Discord");

    var discordUser = await response.json();
    var u = current();

    // РЕЖИМ 1: Пользователь уже авторизован — привязываем Discord к профилю
    if (u) {
      u.discordId = discordUser.id;
      u.discord =
        discordUser.username +
        (discordUser.discriminator && discordUser.discriminator !== "0"
          ? "#" + discordUser.discriminator
          : "");
      saveUsers();

      toast("✅ Discord успешно привязан: " + u.discord, "success");
      syncMyDiscordRoles();
      if (profileUserId === u.id) renderProfileTab(u.id);
      return true;
    }

    // РЕЖИМ 2: Пользователь на экране логина — ищем аккаунт по discordId и входим
    var matched = users.find(function (x) {
      return String(x.discordId) === String(discordUser.id);
    });
    if (!matched) {
      throw new Error(
        "Аккаунт с этим Discord ID (" +
          discordUser.id +
          ") не найден. Сначала войдите по логину/паролю и привяжите Discord в профиле.",
      );
    }

    currentId = matched.id;
    localStorage.setItem("teamCurrentUser", matched.id);
    if (typeof initApp === "function") initApp();
    else location.reload();

    toast("✅ Вход выполнен через Discord: " + matched.name, "success");
    return true;
  } catch (err) {
    console.error("Discord OAuth error:", err);
    toast("❌ Ошибка Discord: " + err.message, "error");
    return false;
  }
}

function syncAllDiscordUsers() {
  if (!checkBlocked()) return;
  if (!can(current(), "manage_permissions")) {
    toast("❌ Нет прав", "error");
    return;
  }
  if (!discordSettings.enabled || !discordSettings.webhookUrl) {
    toast("❌ Discord интеграция выключена", "error");
    return;
  }
  if (
    !confirm(
      "Отправить запрос на синхронизацию для ВСЕХ сотрудников с Discord ID?\n\n⚠️ Внимание: это отправит много сообщений в Discord (займет время).",
    )
  )
    return;

  var validUsers = users.filter(function (u) {
    return u.discordId;
  });
  if (!validUsers.length) {
    toast("⚠️ Ни у кого не указан Discord ID", "warn");
    return;
  }

  toast("🔄 Синхронизация запущена (0/" + validUsers.length + ")...", "info", {
    duration: 3000,
  });

  var i = 0;
  function processNext() {
    if (i >= validUsers.length) {
      toast("✅ Синхронизация всех завершена!", "success");
      return;
    }
    var u = validUsers[i];

    syncDiscordRole(u, u.role);

    var status = "active";
    if (isFrozen(u)) status = "frozen";
    else if (isOnVacation(u)) status = "vacation";
    else if (u.warned) status = "warned";

    var extra = {
      reason: u.frozenReason || u.vacationReason || u.warnedReason || "",
    };
    if (status === "frozen" || status === "vacation")
      extra.until = u.frozenUntil || u.vacationUntil;

    notifyDiscordStatus(u, status, extra);

    i++;
    setTimeout(processNext, 1500);
  }

  processNext();
}

