async function login(e) {
  e.preventDefault();
  var err = document.getElementById("loginError");
  err.textContent = "";
  var login = document.getElementById("loginLogin").value.trim();
  var pass = document.getElementById("loginPass").value;
  var loginKey = login.toLowerCase();
  var maxAttempts = getLimit("login", "maxAttempts", null);
  var lockoutMs = getLimit("login", "lockoutMs", null);
  var attempts = getLoginAttempts(loginKey);
  if (attempts.length >= maxAttempts) {
    var remainingMin = Math.ceil(
      (lockoutMs - (Date.now() - attempts[0].time)) / 60000,
    );
    err.textContent =
      "Слишком много попыток. Подождите " + remainingMin + " мин.";
    return;
  }
  var u = users.find(function (x) {
    return x.login.toLowerCase() === login.toLowerCase();
  });
  var _loginOk = false;
  if (u) {
    if (u.salt) {
      var _hashedSalted = await hashPassword(pass, u.salt);
      _loginOk = _hashedSalted === u.password;
    } else {
      /* миграция со старого формата без соли */
      var _hashedLegacy = await hashPassword(pass);
      if (u.password === _hashedLegacy) {
        _loginOk = true;
        u.salt = generateSalt();
        u.password = await hashPassword(pass, u.salt);
        saveUsers();
      }
    }
  }
  if (!u || !_loginOk) {
    addLoginAttempt(loginKey);
    var left = maxAttempts - (attempts.length + 1);
    err.textContent =
      left > 0
        ? "Неверный логин или пароль. Осталось попыток: " + left
        : "Аккаунт заблокирован на " + Math.round(lockoutMs / 60000) + " мин.";
    return;
  }
  clearLoginAttempts(loginKey);

  addToSavedAccounts(u); // Сохраняем аккаунт для быстрого переключения

  if (isFrozen(u))
    toast(
      "⚠️ Заморожен" + (u.frozenUntil ? " до " + fmtDate(u.frozenUntil) : ""),
    );
  if (isOnVacation(u))
    toast(
      "🌴 В отпуске" +
        (u.vacationUntil ? " до " + fmtDate(u.vacationUntil) : ""),
    );
  currentId = u.id;
  localStorage.setItem("teamCurrentUser", currentId);
  addLoginLog(u);
  addLog("Вход");
  playSound("message");
  showApp();
}
function addLoginLog(user) {
  var ua = navigator.userAgent;
  var device = "Неизвестно";
  if (/Android/i.test(ua)) device = "📱 Android";
  else if (/iPhone|iPad|iPod/i.test(ua)) device = "📱 iOS";
  else if (/Windows/i.test(ua)) device = "🖥 Windows";
  else if (/Mac OS/i.test(ua)) device = "🍎 macOS";
  else if (/Linux/i.test(ua)) device = "🐧 Linux";
  var browser = "—";
  if (/Edg\//i.test(ua)) browser = "Edge";
  else if (/Chrome\//i.test(ua)) browser = "Chrome";
  else if (/Firefox\//i.test(ua)) browser = "Firefox";
  else if (/Safari\//i.test(ua)) browser = "Safari";
  loginLogs.push({
    userId: user.id,
    userName: user.name,
    role: user.role,
    time: new Date().toISOString(),
    device: device + " · " + browser,
    screen: window.innerWidth + "×" + window.innerHeight,
    resolution: screen.width + "×" + screen.height,
  });
  if (loginLogs.length > 500) loginLogs.shift();
  saveLoginLogs();
}
