function showAppInner() {
  if (!current()) {
    logout();
    return;
  }
  document.getElementById("auth").classList.add("hidden");
  document.getElementById("app").classList.remove("hidden");
  var u = current();
  var topUserEl = document.getElementById("topUser");
  topUserEl.innerHTML =
    '<span style="' + nickStyle(u) + '">' + esc(u.name) + "</span>";
  updateTopbarStats(); // <--- ДОБАВИЛИ ВЫЗОВ

  var topAv = document.getElementById("topAvatar");
  topAv.innerHTML = avatarContent(u);
  topAv.className = withFrame(u, "avatar");
  profileUserId = u.id;
  applyColors(getUserColors(u));
  try {
    if (!window.rolesChartInstance) initCharts();
  } catch (e) {}
  updateTabsVisibility();
  var safe = function (fn, name) {
    try {
      fn();
    } catch (e) {
      console.warn("render " + name + ":", e);
    }
  };
  safe(renderStaff, "renderStaff");
  safe(renderTasks, "renderTasks");
  safe(renderTransfers, "renderTransfers");
  safe(renderShop, "renderShop");
  safe(renderGames, "renderGames");
  safe(renderDuels, "renderDuels");
  safe(renderNews, "renderNews");
  safe(renderInventory, "renderInventory");
  safe(renderLoginLog, "renderLoginLog");
  safe(renderLogs, "renderLogs");
  safe(renderRolePermissions, "renderRolePermissions");
  safe(renderSfAnalytics, "renderSfAnalytics");
  safe(renderTrustSettings, "renderTrustSettings");
  updateNotifBadge();
  updateTopbarMood();
  checkFrozenStatus();
  checkWarnedStatus();
  checkSeasonalEvent();
  updateBannersLayout();
  updateCartBadge();
  updateLastSeen();
  setTimeout(function () {
    try {
      requestWebNotifPermission();
    } catch (_) {}
    try {
      checkAchievements(u);
    } catch (_) {}
    try {
      processRecurringTemplates();
    } catch (_) {}
  }, 1500);
  if (
    isFrozen(u) &&
    !sessionStorage.getItem(
      "frozen_shown_" + u.id + "_" + new Date().toDateString(),
    )
  ) {
    setTimeout(function () {
      openFrozenModal();
      sessionStorage.setItem(
        "frozen_shown_" + u.id + "_" + new Date().toDateString(),
        "1",
      );
    }, 500);
  }
  if (hasUnseenWarns(u) && !isFrozen(u)) {
    setTimeout(function () {
      openWarnedModal();
    }, 700);
  }
  /* FIX: восстанавливаем вкладку из URL (#profile/id или #tasks и т.д.) */
  var hashMatch = location.hash.match(/^#profile\/(.+)$/);
  if (
    hashMatch &&
    users.find(function (x) {
      return x.id === hashMatch[1];
    })
  ) {
    profileUserId = hashMatch[1];
    switchTab("profile");
    renderProfileTab(profileUserId);
  } else {
    var tabMatch = location.hash.replace("#", "");
    if (tabMatch === "kpi") tabMatch = "leaderboard";
    var validTabs = [
      "dashboard",
      "staffFunc",
      "staff",
      "tasks",
      "economy",
      "games",
      "news",
      "leaderboard",
      "rules",
      "jobDesc",
      "promotions",
      "battlePass",
    ];
    if (validTabs.indexOf(tabMatch) !== -1 && tabMatch !== "profile") {
      switchTab(tabMatch);
    } else {
      switchTab("dashboard");
    }
  }

  // Проверяем OAuth2 колбэк (если пользователь вернулся с Discord)
  try {
    var _dcOauthResult = handleDiscordOAuthCallback();
    if (_dcOauthResult && typeof _dcOauthResult.catch === "function") {
      _dcOauthResult.catch(function (e) {
        console.warn("Discord OAuth callback:", e);
      });
    }
  } catch (e) {
    console.warn("Discord OAuth callback sync:", e);
  }
  resetInactivityTimer();
}

