function getAllBadges(u) {
  var all = getAutoBadges(u).concat(u.customBadges || []);
  // FIX: дедупликация по имени
  var seen = {},
    out = [];
  all.forEach(function (b) {
    if (!b) return;
    var k = (b.name || "") + "|" + (b.icon || "");
    if (seen[k]) return;
    seen[k] = 1;
    out.push(b);
  });
  return out;
}
function renderBadgesCollapsed(u, limit) {
  limit = limit || 3;
  var badges = getAllBadges(u);
  if (!badges.length) return "—";
  var id = u.id;
  var isExpanded = expandedBadgesUsers.has(id);
  var visible = isExpanded ? badges : badges.slice(0, limit);
  var hiddenCount = badges.length - limit;
  var html =
    '<div style="display:flex;flex-wrap:wrap;gap:4px;align-items:center;">';
  visible.forEach(function (b) {
    html +=
      '<span class="badge ' +
      esc(b.class || "") +
      '">' +
      esc(b.icon || "🏅") +
      " " +
      esc(b.name) +
      "</span>";
  });
  if (hiddenCount > 0) {
    if (isExpanded) {
      html +=
        '<button class="btn small" style="font-size:11px;padding:3px 8px;" onclick="toggleBadgesExpand(\'' +
        id +
        "')\">▲ Свернуть</button>";
    } else {
      html +=
        '<button class="btn small primary2" style="font-size:11px;padding:3px 8px;" onclick="toggleBadgesExpand(\'' +
        id +
        "')\">+" +
        hiddenCount +
        " ещё</button>";
    }
  }
  html += "</div>";
  return html;
}
function toggleBadgesExpand(userId) {
  if (expandedBadgesUsers.has(userId)) expandedBadgesUsers.delete(userId);
  else expandedBadgesUsers.add(userId);
  try {
    renderSfEmployees();
  } catch (e) {}
  try {
    renderStaff();
  } catch (e) {}
}
function renderTrustMiniBadge(u) {
  if (!trustSettings.enabled) return "";
  var t = getEffectiveTrust(u);
  var lvIdx = getTrustLevelIdx(t);
  var lv = TRUST_LEVELS[lvIdx];
  return (
    '<span class="trust-mini-badge trust-mini-' +
    lvIdx +
    '">' +
    lv.icon +
    " " +
    Math.round(t) +
    "</span>"
  );
}
function renderStaff(noCharts) {
  var u = current();
  if (!u) return;
  var tbody = document.getElementById("tbody");
  if (!tbody) return;
  /* FIX: сначала проверка прав, чтобы skeleton не мигал пользователям без доступа */
  if (!can(u, "view_staff")) {
    tbody.innerHTML = '<tr><td colspan="8" class="empty">Нет доступа</td></tr>';
    return;
  }
  /* FIX #30: skeleton при первом рендере */
  if (!noCharts && tbody && !tbody.children.length) {
    tbody.innerHTML =
      '<tr><td colspan="8" style="padding:12px;">' +
      '<div class="skeleton skeleton-row" style="width:30%"></div>' +
      '<div class="skeleton skeleton-row" style="width:60%"></div>' +
      '<div class="skeleton skeleton-row" style="width:45%"></div>' +
      '<div class="skeleton skeleton-row" style="width:75%"></div>' +
      "</td></tr>";
    requestAnimationFrame(function () {
      renderStaff(true);
    });
    return;
  }
  var f = getFilters();
  var rf = document.getElementById("roleFilter");
  var cr = rf.value;
  rf.innerHTML =
    '<option value="">Все должности</option>' +
    rolesList
      .map(function (r) {
        return (
          "<option " + (r === cr ? "selected" : "") + ">" + r + "</option>"
        );
      })
      .join("");
  var list = filterUsers(users, f);
  var sortBy =
    (document.getElementById("staffSort") || {}).value || "trust_desc";
  list.sort(function (a, b) {
    if (sortBy === "trust_desc")
      return getEffectiveTrust(b) - getEffectiveTrust(a);
    if (sortBy === "trust_asc")
      return getEffectiveTrust(a) - getEffectiveTrust(b);
    if (sortBy === "name_asc")
      return (a.name || "").localeCompare(b.name || "", "ru");
    if (sortBy === "name_desc")
      return (b.name || "").localeCompare(a.name || "", "ru");
    if (sortBy === "join_desc")
      return new Date(b.join || 0) - new Date(a.join || 0);
    if (sortBy === "join_asc")
      return new Date(a.join || 0) - new Date(b.join || 0);
    if (sortBy === "warns_desc")
      return getActiveWarnsCount(b) - getActiveWarnsCount(a);
    return 0;
  });
  var listIds = new Set(
    list.map(function (x) {
      return x.id;
    }),
  );
  Array.from(selectedStaffIds).forEach(function (id) {
    if (!listIds.has(id)) selectedStaffIds.delete(id);
  });
  tbody.innerHTML = list.length
    ? list
        .map(function (u) {
          var sh = renderUserStatusBadge(u);
          var sel = selectedStaffIds.has(u.id);
          return (
            '<tr class="' +
            (sel ? "row-selected" : "") +
            '"><td><input type="checkbox" class="staff-checkbox" ' +
            (sel ? "checked" : "") +
            " onchange=\"toggleStaffSelection('" +
            u.id +
            '\', this.checked)"></td><td><button class="btn" onclick="openProfileInTab(\'' +
            u.id +
            '\')" style="display:inline-flex;align-items:center;gap:8px;"><span class="' +
            withFrame(u, "mini-avatar") +
            '">' +
            avatarContent(u) +
            '</span><span style="' +
            nickStyle(u) +
            '">' +
            esc(u.name) +
            "</span> " +
            moodIcon(u.mood || "online", u) +
            "</button></td><td>" +
            esc(u.login) +
            '</td><td class="role ' +
            roleClass(u.role) +
            '" style="' +
            roleStyle(u.role) +
            '">' +
            esc(u.role) +
            "</td><td>" +
            esc(u.join || "—") +
            "</td><td>" +
            renderTrustMiniBadge(u) +
            "</td><td>" +
            renderWarnsBadge(u) +
            "</td><td>" +
            sh +
            "</td></tr>"
          );
        })
        .join("")
    : '<tr><td colspan="8" style="padding:0;"><div class="empty" data-icon="🔍"><b>Никого не найдено</b><small>Попробуйте изменить фильтры или очистить поиск</small></div></td></tr>';
  document.getElementById("count").textContent = users.length;
  document.getElementById("rolesCount").textContent = new Set(
    users.map(function (u) {
      return u.role;
    }),
  ).size;
  document.getElementById("withNotes").textContent = users.filter(function (u) {
    return u.notes && u.notes.trim();
  }).length;
  var at = document.getElementById("avgTrust");
  if (at)
    at.textContent = users.length
      ? Math.round(
          users.reduce(function (s, x) {
            return s + getEffectiveTrust(x);
          }, 0) / users.length,
        )
      : 50;
  updateBulkBar();
  if (!noCharts) updateCharts();
}
