    rolesList
      .map(function (r) {
        return "<option>" + r + "</option>";
      })
      .join("") +
    '</select></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Отмена</button><button class="btn primary2" onclick="applyBulkRole()">OK</button></div>';
