function applyBulkRole() {
  if (!checkBlocked()) return;
  if (!rateLimit("bulkRole")) return;
  if (selectedStaffIds.size > getLimit("admin", "maxBulkSize")) {
    toast(
      "❌ Макс. за раз: " + getLimit("admin", "maxBulkSize") + " сотрудников",
    );
    return;
  }
  var newRole = document.getElementById("bulkNewRole").value;
  var targets = getSelectedUsers().filter(function (u) {
    return u.id !== currentId;
  });
  if (!targets.length) {
    toast("Никто не выбран");
    return;
  }
  var hasOwner = newRole === "Владелец";
  if (hasOwner && current().role !== "Владелец") {
    toast("❌ Только Владелец может назначать Владельцев", "error");
    return;
  }
  var apply = function () {
    targets.forEach(function (u) {
      u.role = newRole;
      addHistoryEntry(u.id, "Смена роли", "→" + newRole);
      syncDiscordRole(u, newRole);
    });
    saveUsers();
    closeModal();
    toast("🎭 Роль «" + newRole + "» выдана: " + targets.length + " чел.");
    clearSelection();
    renderStaff();
  };
  if (hasOwner || targets.length > 5) {
    confirmCritical({
      title: hasOwner ? "Выдать роль Владелец?" : "Массовая смена роли",
      message:
        "Будет изменена роль у " +
        targets.length +
        " сотрудников на «" +
        newRole +
        "».",
      requireLogin: hasOwner,
      loginToConfirm: current().login,
      danger: hasOwner,
      okText: "🎭 Подтвердить",
    }).then(function (ok) {
      if (ok) apply();
    });
  } else apply();
}
