  html +=
    "<button onclick=\"switchProfileTabInProfile('badges','" +
    u.id +
    "')\">🏅 Бейджи</button>";
  html +=
    "<button onclick=\"switchProfileTabInProfile('notes','" +
    u.id +
    "')\">📝 Заметки</button>";
