async function doResetPassword(userId) {
  if (!checkBlocked()) return;
  var admin = current();
  if (!admin) return;
  if (
    userId !== currentId &&
    !can(admin, "manage_permissions") &&
    !can(admin, "edit_user")
  ) {
    toast("❌ Нет прав", "error");
    return;
  }
  var u = users.find(function (x) {
    return x.id === userId;
  });
  if (!u) return;
  var newPass = document.getElementById("resetPassInput").value.trim();
  if (newPass.length < 6) {
    toast("❌ Минимум 6 символов", "error");
    return;
  }
  u.salt = generateSalt();
  u.password = await hashPassword(newPass, u.salt);
  saveUsers();
  addLog("Сброс пароля", u.name + " (админ: " + admin.name + ")");
  addHistoryEntry(u.id, "Сброс пароля", "Админ: " + admin.name);
  addNotification(u.id, "🔑 Пароль был изменён администратором", {
    mention: true,
  });
  toast("🔑 Пароль сброшен: " + newPass, "success", { duration: 8000 });
  closeModal();
}

