/* ============ БАЛАНС / КОИНЫ ============ */
function changeBalance(userId, amount, reason, silent, skipSave) {
  reason = reason || "";
  var u = users.find(function (x) {
    return x.id === userId;
  });
  if (!u) return { ok: false, after: 0, delta: 0, reason: "user_not_found" };
  if (!u.balanceHistory) u.balanceHistory = [];
  var before = Number(u.balance) || 0;
  var delta = Number(amount) || 0;
  if (!isFinite(delta))
    return { ok: false, after: before, delta: 0, reason: "bad_amount" };
  var after = before + delta;
  var clamped = false;
  if (after < 0) {
    console.warn("changeBalance clamp:", userId, before, delta);
    after = 0;
    clamped = true;
  }
  var actualDelta = after - before;
  u.balance = after;
  var by = current() ? current().name : "Система";
  u.balanceHistory.push({
    time: new Date().toISOString(),
    by: by,
    amount: actualDelta,
    after: after,
    reason: reason,
  });
  if (u.balanceHistory.length > 500) u.balanceHistory.shift();
  if (!skipSave) saveUsers();
  if (actualDelta !== 0 && !silent) {
    var sign = actualDelta > 0 ? "+" : "";
    addNotification(
      u.id,
      "💵 Баланс: " +
        sign +
        fmtBalance(actualDelta) +
        " ₽ · " +
        (reason || "—"),
    );
  }
  if (actualDelta > 0 && !silent) playSound("coin");
  if (currentId === userId) updateTopbarStats(); // <--- ДОБАВИЛИ
  return { ok: true, after: after, delta: actualDelta, clamped: clamped };
}

function changeCoins(userId, amount, reason, silent) {
  reason = reason || "";
  var u = users.find(function (x) {
    return x.id === userId;
  });
  if (!u) return { ok: false, after: 0, delta: 0, reason: "user_not_found" };
  if (!u.coinHistory) u.coinHistory = [];
  var before = Number(u.coins) || 0;
  var delta = Number(amount) || 0;
  if (!isFinite(delta))
    return { ok: false, after: before, delta: 0, reason: "bad_amount" };
  var after = before + delta;
  var clamped = false;
  if (after < 0) {
    console.warn("changeCoins clamp:", userId, before, delta);
    after = 0;
    clamped = true;
  }
  var actualDelta = after - before;
  u.coins = after;
  var by = current() ? current().name : "Система";
  u.coinHistory.push({
    time: new Date().toISOString(),
    by: by,
    amount: actualDelta,
    after: after,
    reason: reason,
  });
  if (u.coinHistory.length > 500) u.coinHistory.shift();
  saveUsers();
  if (actualDelta !== 0 && !silent) {
    var sign = actualDelta > 0 ? "+" : "";
    addNotification(
      u.id,
      "🪙 Коины: " + sign + fmtBalance(actualDelta) + " · " + (reason || "—"),
    );
  }
  if (actualDelta > 0 && !silent) playSound("coin");
  if (currentId === userId) updateTopbarStats();
  return { ok: true, after: after, delta: actualDelta, clamped: clamped };
}

