function onCurOpAmountChange(v) {
  var s = window._curOp;
  if (!s || !s.userId) return;
  s.amount = parseAmountInput(v);
  var u = users.find(function (x) {
    return x.id === s.userId;
  });
  if (!u) return;
  var isCoins = s.currency === "coins";
  var have = isCoins ? Number(u.coins) || 0 : Number(u.balance) || 0;
  var sym = isCoins ? "🪙" : "₽";
  var amt = s.amount;
  var after = have + (s.sign > 0 ? amt : -amt);
  if (after < 0) after = 0;
  var tooMuch = s.sign < 0 && amt > have;

  var afterEl = document.getElementById("curOpAfterPreview");
  if (afterEl) {
    afterEl.textContent = sym + " " + fmtBalance(after);
  }

  var btnAmt = document.getElementById("curOpSubmitAmt");
  if (btnAmt) {
    btnAmt.textContent = sym + " " + fmtBalance(amt);
  }

  var warnWrap = document.getElementById("curOpTooMuchWrap");
  if (warnWrap) {
    if (tooMuch) {
      warnWrap.innerHTML =
        '<div style="background:#2a141a;border:1px solid #5a3039;border-radius:10px;padding:12px 14px;color:#ffd9df;font-size:13px;margin-bottom:12px;display:flex;gap:8px;align-items:center;"><span style="font-size:18px;">⚠️</span><div>Недостаточно средств. Максимум: <b>' +
        sym +
        " " +
        fmtBalance(have) +
        "</b></div></div>";
    } else {
      warnWrap.innerHTML = "";
    }
  }

  var btn = document.getElementById("curOpSubmitBtn");
  if (btn) {
    btn.disabled = tooMuch;
    btn.style.opacity = tooMuch ? ".5" : "1";
    btn.style.cursor = tooMuch ? "not-allowed" : "";
  }
}
function parseAmountInput(str) {
  if (str === null || str === undefined) return 0;
  str = String(str).trim().toLowerCase().replace(/\s+/g, "");
  if (!str) return 0;
  var mult = 1;
  var sufMatch = str.match(/(трлн|млрд|млн|кк|kk|к|k|м|m|б|b|т|t)$/);
  if (sufMatch) {
    var s = sufMatch[1];
    if (s === "к" || s === "k") mult = 1000;
    else if (s === "кк" || s === "kk") mult = 1000000;
    else if (s === "м" || s === "m" || s === "млн") mult = 1000000;
    else if (s === "б" || s === "b" || s === "млрд") mult = 1000000000;
    else if (s === "т" || s === "t" || s === "трлн") mult = 1000000000000;
    str = str.slice(0, str.length - s.length);
  }
  if (/^\d{1,3}([.,]\d{3})+$/.test(str) || /^\d+([.,]\d{3})+$/.test(str)) {
    str = str.replace(/[.,]/g, "");
  } else {
    str = str.replace(/,/g, ".");
  }
  if (!/^\d+(\.\d+)?$/.test(str)) {
    return 0;
  }
  var num = parseFloat(str);
  if (!isFinite(num) || num < 0) return 0;
  return Math.max(0, Math.round(num * mult));
}
function setCurOpReason(r) {
  window._curOp.reason = r;
  var el = document.getElementById("curOpReason");
  if (el) el.value = r;
}
function applyCurrencyOp() {
  var s = window._curOp;
  if (!s || !s.userId) {
    toast("❌ Ошибка");
    return;
  }
  if (!rateLimit("curOp")) return;
  var u = users.find(function (x) {
    return x.id === s.userId;
  });
  if (!u) {
    toast("❌ Сотрудник не найден");
    return;
  }
  if (s.userId === currentId && !canEditOwnBalance()) {
    toast(
      "❌ Свой баланс может редактировать только Владелец или Тех. Администратор",
    );
    return;
  }
  var reasonEl = document.getElementById("curOpReason");
  var reason =
    (reasonEl && reasonEl.value.trim()) ||
    (s.sign > 0 ? "Начисление" : "Списание");
  var amount = Math.max(1, parseInt(s.amount, 10) || 0);
  if (!amount) {
    toast("❌ Введите сумму");
    return;
  }
  var isCoins = s.currency === "coins";
  if (isCoins) {
    if (!can(current(), "manage_coins")) {
      toast("❌ Нет прав на управление коинами");
      return;
    }
  } else {
    if (!can(current(), "manage_balance")) {
      toast("❌ Нет прав на управление балансом");
      return;
    }
  }
  var have = isCoins ? Number(u.coins) || 0 : Number(u.balance) || 0;
  if (s.sign < 0 && amount > have) {
    toast("❌ Недостаточно средств");
    return;
  }
  var check = checkOpLimits(amount, s.currency);
  if (!check.ok) {
    toast("⛔ " + check.msg, "error");
    return;
  }
  var _hOpPeek = checkHourlyLimit(
    current().id,
    "curOp",
    getLimit("admin", "curOpPerHour"),
  );
  if (!_hOpPeek.ok) {
    toast("❌ " + _hOpPeek.msg);
    return;
  }
  var applied = amount * s.sign;
  var result;
  if (isCoins) result = changeCoins(u.id, applied, reason);
  else result = changeBalance(u.id, applied, reason);
  if (!result || result.ok === false) {
    toast("❌ Не удалось применить операцию", "error");
    return;
  }
  if (result.clamped) {
    toast(
      "⚠️ Применено частично: " +
        (isCoins ? "🪙" : "₽") +
        " " +
        fmtBalance(Math.abs(result.delta)) +
        " (недостаточно средств)",
      "warn",
    );
  }
  commitHourlyLimit(_hOpPeek);
  commitOpLimit(amount, s.currency);
  addTx({
    type: "manual",
    fromId: s.sign < 0 ? u.id : null,
    fromName: s.sign < 0 ? u.name : "Система",
    toId: s.sign > 0 ? u.id : null,
    toName: s.sign > 0 ? u.name : "Система",
    amount: amount,
    netAmount: amount,
    currency: s.currency,
    reason: reason,
    refundable: true,
  });
  addLog(
    (s.sign > 0 ? "Начислено" : "Списано") + " " + u.name,
    fmtBalance(amount) + (isCoins ? " 🪙" : " ₽") + " · " + reason,
  );
  playSound(s.sign > 0 ? "coin" : "sell");
  toast(
    (s.sign > 0 ? "➕" : "➖") +
      " " +
      fmtBalance(amount) +
      (isCoins ? " 🪙" : " ₽") +
      " · " +
      u.name,
    isCoins ? "coin" : "money",
    {
      duration: 6000,
      undoText: "↩ Отменить",
      undo: function () {
        if (isCoins) changeCoins(u.id, -applied, "Отмена операции");
        else changeBalance(u.id, -applied, "Отмена операции");
        toast("↩ Отменено");
        renderStaff();
        if (profileUserId === u.id)
          try {
            renderProfileTab(u.id);
          } catch (e) {}
        try {
          renderSfBalances();
        } catch (e) {}
      },
    },
  );
  closeModal();
  try {
    renderSfBalances();
  } catch (e) {}
  try {
    renderBalanceSection();
  } catch (e) {}
  try {
    renderTxLogSection();
  } catch (e) {}
  renderStaff();
  if (profileUserId === u.id)
    try {
      renderProfileTab(u.id);
    } catch (e) {}
}

/* ============ ЗАМОРОЗКА / ОТПУСК ============ */
function checkFrozenStatus() {
  var u = current();
  if (!u) return;
  var banner = document.getElementById("frozenBanner");
  if (!banner) return;
  if (isFrozen(u)) {
    banner.classList.remove("hidden");
    document.getElementById("frozenBannerReason").textContent =
      u.frozenReason || "Без причины";
    var untilEl = document.getElementById("frozenBannerUntil");
    if (u.frozenUntil) {
      var _endTs = parseUntilTs(u.frozenUntil);
      var days = isFinite(_endTs)
        ? Math.ceil((_endTs - Date.now()) / (1000 * 60 * 60 * 24))
        : 0;
      untilEl.textContent =
        "· до " +
        fmtDate(u.frozenUntil) +
        (isFinite(days) && days > 0 ? " (" + days + " дн.)" : " (истёк)");
    } else {
      untilEl.textContent = "· бессрочно";
    }
  } else banner.classList.add("hidden");
  updateBannersLayout();
}
window.addEventListener("resize", function () {
  try {
    updateBannersLayout();
  } catch (e) {}
});
(function () {
  var _topEl = document.querySelector(".top");
  if (_topEl && typeof ResizeObserver !== "undefined") {
    try {
      new ResizeObserver(function () {
        try {
          updateBannersLayout();
        } catch (e) {}
      }).observe(_topEl);
    } catch (e) {}
  }
})();
function updateBannersLayout() {
  var seasonal = document.getElementById("seasonalBanner");
  var frozen = document.getElementById("frozenBanner");
  var warned = document.getElementById("warnedBanner");
  var top = document.querySelector(".top");
  var headerH = top ? top.offsetHeight : 72;
  var offset = 0;
  if (seasonal && !seasonal.classList.contains("hidden")) {
    seasonal.style.top = headerH + "px";
    offset += seasonal.offsetHeight || 40;
  }
  if (frozen && !frozen.classList.contains("hidden")) {
    frozen.style.top = headerH + offset + "px";
    offset += frozen.offsetHeight || 52;
  }
  if (warned && !warned.classList.contains("hidden")) {
    warned.style.top = headerH + offset + "px";
    offset += warned.offsetHeight || 48;
  }
  if (top) top.style.marginBottom = offset ? offset + "px" : "0";
}

function checkWarnedStatus() {
  var u = current();
  if (!u) return;
  var banner = document.getElementById("warnedBanner");
  if (!banner) return;
  var active = getActiveWarns(u);
  if (active.length > 0) {
    banner.classList.remove("hidden");
    var cnt = document.getElementById("warnedBannerCount");
    if (cnt) cnt.textContent = active.length;
  } else {
    banner.classList.add("hidden");
  }
  updateBannersLayout();
}

function openWarnedModal() {
  var u = current();
  if (!u) return;
  if (document.getElementById("warnedModalOverlay")) return;
  var active = getActiveWarns(u);
  if (!active.length) return;

  var div = document.createElement("div");
  div.className = "frozen-modal-overlay";
  div.id = "warnedModalOverlay";

  var warnsHtml = "";
  active.forEach(function (w, i) {
    var at = (w.at || "").slice(0, 19).replace("T", " ");
    warnsHtml +=
      '<div class="frozen-info" style="margin:8px 0;border-color:#e5c35c33;">' +
      '<div class="row"><span>#' +
      (i + 1) +
      "</span><span>" +
      esc(w.reason || "без причины") +
      "</span></div>" +
      '<div class="row"><span>Выдал</span><span>' +
      esc(w.byName || "—") +
      "</span></div>" +
      '<div class="row"><span>Дата</span><span>' +
      at +
      "</span></div>" +
      "</div>";
  });

  var consequences = "";
  var remaining = MAX_WARNS - active.length;
  if (remaining === 1) {
    consequences =
      '<div class="crit-warn-box" style="margin-top:12px;background:#2a1a0e;border-color:#e5c35c66;color:#f8e6c0;"><span class="ico">🎭</span><div>Ещё <b>один выговор</b> — и вы будете <b>сняты с должности</b>.</div></div>';
  } else if (remaining === 0) {
    consequences =
      '<div class="crit-warn-box" style="margin-top:12px;background:#2a1a0e;border-color:#e5c35c66;color:#f8e6c0;"><span class="ico">🚫</span><div>Достигнут <b>максимум</b> выговоров.</div></div>';
  } else if (active.length === AUTO_FREEZE_ON_WARNS - 1) {
    consequences =
      '<div class="crit-warn-box" style="margin-top:12px;background:#0a1a2e;border-color:#7ad1ff66;color:#e0f2ff;"><span class="ico">❄️</span><div>После <b>следующего</b> выговора будет <b>авто-заморозка на 24 часа</b>.</div></div>';
  }

  div.innerHTML =
    '<div class="frozen-modal" style="border-color:#e5c35c;">' +
    '<div class="frozen-icon">⚠️</div>' +
    '<div class="frozen-title" style="color:#e5c35c;">У вас выговоры</div>' +
    '<div class="frozen-subtitle">Активных: <b style="color:#e5c35c;">' +
    active.length +
    " / " +
    MAX_WARNS +
    "</b></div>" +
    warnsHtml +
    consequences +
    '<div class="modal-actions" style="justify-content:center;margin-top:20px;">' +
    '<button class="btn primary2" onclick="closeWarnedModal()">Понятно</button>' +
    "</div>" +
    "</div>";
  document.body.appendChild(div);

  // Помечаем как «просмотрено»
  markWarnsSeen(u);
  checkWarnedStatus();
}

function closeWarnedModal() {
  var el = document.getElementById("warnedModalOverlay");
  if (el) el.remove();
}

function openFrozenModal() {
  var u = current();
  if (!u || !isFrozen(u)) return;
  if (document.getElementById("frozenModalOverlay")) return;
  var div = document.createElement("div");
  div.className = "frozen-modal-overlay";
  div.id = "frozenModalOverlay";
  var untilText = u.frozenUntil ? fmtDate(u.frozenUntil) : "бессрочно";
  div.innerHTML =
    '<div class="frozen-modal"><div class="frozen-icon">❄️</div><div class="frozen-title">Заморозка</div><div class="frozen-subtitle">Ваш аккаунт временно ограничен</div><div class="frozen-info"><div class="row"><span>Причина</span><span>' +
    (u.frozenReason ? esc(u.frozenReason) : "не указана") +
    '</span></div><div class="row"><span>До</span><span>' +
    untilText +
    '</span></div><div class="row"><span>Доступно</span><span style="font-size:12px;">Обмен валют, покупка разморозки</span></div></div><button class="btn primary2" onclick="closeFrozenModal()">Понятно</button><button class="btn" style="margin-left:8px;background:#1a3050;color:#7ad1ff;" onclick="closeFrozenModal();window._ecoSubTab=\'shop\';switchTab(\'economy\');">🛒 Магазин</button></div>';
  document.body.appendChild(div);
}
function closeFrozenModal() {
  var el = document.getElementById("frozenModalOverlay");
  if (el) el.remove();
  // После закрытия окна заморозки — показать выговоры (если есть непрочитанные)
  var u = current();
  if (u && hasUnseenWarns(u)) {
    setTimeout(openWarnedModal, 200);
  }
}
function openFreezeModal(userId) {
  if (!checkBlocked()) return;
  if (!can(current(), "freeze_user")) {
    toast("Нет прав");
    return;
  }
  var u = users.find(function (x) {
    return x.id === userId;
  });
  if (!u || u.id === currentId) return toast("Нельзя себя");
  var isEdit = isFrozen(u);
  document.getElementById("modalContent").innerHTML =
    "<h2>" +
    (isEdit ? "✎ Заморозка" : "❄️ Заморозка") +
    '</h2><p class="muted">' +
    esc(u.name) +
    '</p><div class="field"><label>Причина</label><textarea id="freezeReason" rows="2">' +
    esc(u.frozenReason || "") +
    '</textarea></div><div class="field"><label>До (пусто = бессрочно)</label><input id="freezeUntil" type="date" value="' +
    esc(u.frozenUntil || "") +
    '"></div><div id="freezeError" class="error"></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Отмена</button>' +
    (isEdit
      ? '<button class="btn danger" onclick="closeModal();unfreezeUser(\'' +
        userId +
        "')\">🔓 Разморозить</button>"
      : "") +
    '<button class="btn danger" onclick="confirmFreeze(\'' +
    userId +
    "')\">" +
    (isEdit ? "💾 Обновить" : "❄️ Заморозить") +
    "</button></div>";
  document.getElementById("modal").classList.remove("hidden");
}
function confirmFreeze(userId) {
  if (!checkBlocked() || !rateLimit("freeze")) return;
  var u = users.find(function (x) {
    return x.id === userId;
  });
  if (!u) return;
  var reason = document.getElementById("freezeReason").value.trim();
  if (!reason) {
    document.getElementById("freezeError").textContent = "Причина?";
    return;
  }
  var wasFrozen = isFrozen(u);
  var untilEl = document.getElementById("freezeUntil");
  if (!wasFrozen) {
    confirmCritical({
      title: "Заморозить сотрудника?",
      message: u.name + " потеряет доступ к системе.",
      requireLogin: true,
      loginToConfirm: u.login,
      danger: true,
      okText: "❄️ Заморозить",
    }).then(function (ok) {
      if (ok) doFreeze(u, reason, untilEl);
    });
  } else {
    doFreeze(u, reason, untilEl);
  }
}
function doFreeze(u, reason, untilEl) {
  var wasFrozen = isFrozen(u);
  u.frozen = true;
  u.frozenReason = reason;
  u.frozenUntil = (untilEl && untilEl.value) || "";
  addHistoryEntry(
    u.id,
    wasFrozen ? "Обновление заморозки" : "Заморозка",
    (reason || "без причины") +
      (u.frozenUntil ? " · до " + u.frozenUntil : " · бессрочно"),
  );
  saveUsers();
  syncDiscordRole(u, u.role);
  notifyDiscordStatus(u, "frozen", { reason: reason, until: u.frozenUntil });
  addNotification(
    u.id,
    (wasFrozen ? "✎ Обновлено" : "❄️ Заморожен") +
      (u.frozenUntil ? " до " + u.frozenUntil : " (бессрочно)") +
      " · " +
      reason,
  );
  if (!wasFrozen && trustSettings.enabled)
    changeTrust(u.id, trustSettings.weights.freeze, "Заморозка");
  playSound("freeze");
  closeModal();
  toast(
    (wasFrozen ? "✎ Заморозка обновлена" : "❄️ Заморожен") +
      (u.frozenUntil ? " до " + fmtDate(u.frozenUntil) : ""),
  );
  renderStaff();
  try {
    renderSfFreeze();
  } catch (e) {}
  try {
    renderSfEmployees();
  } catch (e) {}
  checkFrozenStatus();
}
function unfreezeUser(userId) {
  var u = users.find(function (x) {
    return x.id === userId;
  });
  if (!u || !isFrozen(u)) return;
  if (userId === currentId) {
    toast("❌ Нельзя разморозить себя");
    return;
  }
  if (!can(current(), "freeze_user")) {
    toast("❌ Нет прав");
    return;
  }
  u.frozen = false;
  u.frozenReason = "";
  u.frozenUntil = "";
  addHistoryEntry(
    u.id,
    "Разморозка",
    "Снял: " + (current() ? current().name : "—"),
  );
  saveUsers();
  syncDiscordRole(u, u.role);
  notifyDiscordStatus(u, "active", { reason: "Разморозка" });
  addNotification(u.id, "🔓 Разморожен");
  playSound("unfreeze");
  toast("🔓 Сотрудник разморожен");
  renderStaff();
  try {
    renderSfFreeze();
  } catch (e) {}
  try {
    renderSfEmployees();
  } catch (e) {}
  checkFrozenStatus();
}
function openVacationModal(userId) {
  if (!checkBlocked()) return;
  if (!can(current(), "edit_user")) {
    toast("Нет прав");
    return;
  }
  var u = users.find(function (x) {
    return x.id === userId;
  });
  if (!u || u.id === currentId) return toast("Нельзя себе");
  var isEdit = isOnVacation(u);
  var html =
    "<h2>" +
    (isEdit ? "✎ Отпуск" : "🌴 Отпуск") +
    '</h2><p class="muted">' +
    esc(u.name) +
    "</p>";
  html +=
    '<div class="field"><label>Причина</label><textarea id="vacationReason" rows="2">' +
    esc(u.vacationReason || "") +
    "</textarea></div>";
  html +=
    '<div class="field"><label>Срок</label><div style="display:flex;gap:6px;flex-wrap:wrap;">';
  [
    { d: 1, l: "1 день" },
    { d: 3, l: "3 дня" },
    { d: 7, l: "7 дней" },
    { d: 14, l: "2 недели" },
    { d: 30, l: "1 месяц" },
  ].forEach(function (p) {
    html +=
      '<button type="button" class="btn small" onclick="pickVacationDays(' +
      p.d +
      ')">' +
      p.l +
      "</button>";
  });
  html +=
    '<button type="button" class="btn small primary2" onclick="pickVacationDays(0)">📅 Другое</button></div>';
  var defaultDate =
    u.vacationUntil ||
    new Date(Date.now() + 7 * 86400000).toISOString().slice(0, 10);
  html +=
    '<div id="vacationCustomWrap" class="hidden" style="margin-top:10px;"><input id="vacationUntil" type="date" value="' +
    esc(defaultDate) +
    '" onchange="updateVacationPreview()"></div>';
  html +=
    '<div id="vacationPreview" class="rate-box" style="margin-top:12px;"></div>';
  html += '<div id="vacationError" class="error"></div>';
  html +=
    '<div class="modal-actions"><button class="btn" onclick="closeModal()">Отмена</button>' +
    (isEdit
      ? '<button class="btn danger" onclick="closeModal();unvacation(\'' +
        userId +
        "')\">🔙 Вернуть</button>"
      : "") +
    '<button class="btn primary2" onclick="confirmVacation(\'' +
    userId +
    "')\">" +
    (isEdit ? "💾 Обновить" : "🌴 Отправить") +
    "</button></div>";
  document.getElementById("modalContent").innerHTML = html;
  if (isEdit && u.vacationUntil) {
    window._vacationDays = 0;
    document.getElementById("vacationCustomWrap").classList.remove("hidden");
  } else {
    window._vacationDays = 7;
  }
  updateVacationPreview();
  document.getElementById("modal").classList.remove("hidden");
}
function pickVacationDays(n) {
  window._vacationDays = n;
  var wrap = document.getElementById("vacationCustomWrap");
  if (n === 0) {
    wrap.classList.remove("hidden");
  } else {
    wrap.classList.add("hidden");
  }
  updateVacationPreview();
}
function updateVacationPreview() {
  var prev = document.getElementById("vacationPreview");
  if (!prev) return;
  var until;
  if (window._vacationDays === 0) {
    var inp = document.getElementById("vacationUntil");
    if (!inp || !inp.value) {
      prev.textContent = "Выберите дату";
      return;
    }
    until = inp.value;
  } else {
    until = new Date(Date.now() + window._vacationDays * 86400000)
      .toISOString()
      .slice(0, 10);
  }
  var end = new Date(until + "T23:59:59");
  var days = Math.max(0, Math.ceil((end - new Date()) / 86400000));
  prev.innerHTML =
    "📅 До <b>" + fmtDate(until) + "</b> · осталось <b>" + days + " дн.</b>";
}
function confirmVacation(userId) {
  if (!checkBlocked() || !rateLimit("vacation")) return;
  var u = users.find(function (x) {
    return x.id === userId;
  });
  if (!u) return;
  var reason = document.getElementById("vacationReason").value.trim();
  if (!reason) {
    document.getElementById("vacationError").textContent = "Укажите причину";
    return;
  }
  var until;
  if (window._vacationDays === 0) {
    var inp = document.getElementById("vacationUntil");
    if (!inp || !inp.value) {
      document.getElementById("vacationError").textContent = "Укажите дату";
      return;
    }
    until = inp.value;
  } else {
    until = new Date(Date.now() + window._vacationDays * 86400000)
      .toISOString()
      .slice(0, 10);
  }
  var was = isOnVacation(u);
  u.onVacation = true;
  u.vacationUntil = until;
  u.vacationReason = reason;
  addHistoryEntry(
    u.id,
    was ? "Обновление отпуска" : "Отпуск",
    reason + " · до " + until,
  );
  saveUsers();
  syncDiscordRole(u, u.role);
  notifyDiscordStatus(u, "vacation", { reason: reason, until: until });
  addNotification(
    u.id,
    (was ? "✎ Обновлено" : "🌴 Отпуск") + " до " + until + " · " + reason,
  );
  closeModal();
  toast(
    (was ? "✎ Отпуск обновлён" : "🌴 Отправлен в отпуск") +
      " до " +
      fmtDate(until),
  );
  renderStaff();
  try {
    renderSfVacation();
  } catch (e) {}
  try {
    renderSfEmployees();
  } catch (e) {}
}
function unvacation(userId) {
  var u = users.find(function (x) {
    return x.id === userId;
  });
  if (!u || !u.onVacation) return;
  if (userId === currentId) {
    toast("❌ Нельзя вернуть себя");
    return;
  }
  if (!can(current(), "edit_user")) {
    toast("❌ Нет прав");
    return;
  }
  u.onVacation = false;
  u.vacationReason = "";
  u.vacationUntil = "";
  addHistoryEntry(
    u.id,
    "Возврат из отпуска",
    "Вернул: " + (current() ? current().name : "—"),
  );
  saveUsers();
  syncDiscordRole(u, u.role);
  notifyDiscordStatus(u, "active", { reason: "Возврат из отпуска" });
  addNotification(u.id, "🔙 Возврат из отпуска");
  toast("🔙 Сотрудник вернулся из отпуска");
  renderStaff();
  try {
    renderSfVacation();
  } catch (e) {}
  try {
    renderSfEmployees();
  } catch (e) {}
}

/* ============ ПЕРЕВОДЫ ============ */
function renderTransfers() {
  var el = document.getElementById("ecoSectionTransfers");
  if (!el) return;
  var user = current();
  if (!user) return;

  var myCoins = Number(user.coins) || 0;
  var myBalance = Number(user.balance) || 0;

  // Получаем список других пользователей для выпадающего списка
  var otherUsers = users.filter(function (x) {
    return x.id !== user.id;
  });
  var userOptions = otherUsers
    .map(function (x) {
      return '<option value="' + x.id + '">' + esc(x.name) + "</option>";
    })
    .join("");

  // --- ИСПРАВЛЕНИЕ ОШИБКИ ---
  // Ищем историю переводов. Если её нет, берем пустой массив.
  // (Если у вас история хранится в другом поле, например user.transfersHistory,
  // просто добавьте его через || )
  var list = user.transferHistory || user.transfers || [];

  var historyHtml = "";
  if (list.length === 0) {
    // Красивая заглушка вместо скучного текста
    historyHtml =
      '<div class="empty" data-icon="💸" style="margin-top:20px; padding: 30px;"><b>Нет переводов</b><small>Здесь появится история ваших переводов.</small></div>';
  } else {
    // Отрисовка списка, если переводы есть (используем ваши классы tx-row)
    historyHtml = list
      .map(function (t) {
        var isPos = t.amount > 0;
        return (
          '<div class="tx-row">' +
          '<div class="tx-ico">' +
          (isPos ? "⬇️" : "⬆️") +
          "</div>" +
          '<div class="tx-info">' +
          '<div class="tx-main">' +
          esc(t.reason || t.comment || "Перевод") +
          "</div>" +
          '<div class="tx-meta">' +
          (t.time ? new Date(t.time).toLocaleString() : "—") +
          "</div>" +
          "</div>" +
          '<div class="tx-amount ' +
          (isPos ? "pos" : "") +
          '">' +
          (isPos ? "+" : "") +
          fmtBalance(t.amount) +
          "</div>" +
          "</div>"
        );
      })
      .join("");
  }

  // Сборка всего интерфейса вкладки
  var html = "";

  // Кошелек сверху
  html += '<section class="wallet-hero" style="margin-bottom:16px;">';
  html += '<div class="wallet-hero-cards">';
  html +=
    '<div class="wallet-hero-card balance"><span class="wh-ico">💵</span><div class="wh-label">Мой баланс</div><div class="wh-value">' +
    fmtBalance(myBalance) +
    " ₽</div></div>";
  html +=
    '<div class="wallet-hero-card coins"><span class="wh-ico">🪙</span><div class="wh-label">Мои коины</div><div class="wh-value">' +
    fmtBalance(myCoins) +
    "</div></div>";
  html += "</div></section>";

  // Форма перевода
  html += '<section class="card" style="margin-bottom:16px;">';
  html += '<div class="toolbar"><h3 style="margin:0;">💸 Переводы</h3></div>';
  html += '<div style="padding:20px;">';

  // Плашка с комиссией
  var feePct =
    typeof TRANSFER_FEE !== "undefined" ? Math.round(TRANSFER_FEE * 100) : 10;
  html +=
    '<div class="rate-box" style="margin-bottom:20px;"><span>Комиссия:</span> <b>' +
    feePct +
    "%</b></div>";

  html +=
    '<div style="background:#0d1a13;border:1px solid var(--line);border-radius:14px;padding:16px;margin-bottom:16px;">';
  html += '<h4 style="margin:0 0 12px;color:var(--accent);">📤 Отправить</h4>';
  html +=
    '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px;">';

  html +=
    '<div class="field"><label>Получатель</label><select id="transferTo">' +
    userOptions +
    "</select></div>";
  html +=
    '<div class="field"><label>Валюта</label><select id="transferCurrency"><option value="coins">🪙 Коины</option><option value="balance">💵 Рубли</option></select></div>';
  html +=
    '<div class="field"><label>Сумма</label><input id="transferAmount" type="text" placeholder="1к = 1000"></div>';
  html +=
    '<div class="field"><label>Комментарий</label><input id="transferComment" type="text" placeholder="Необязательно"></div>';
  html +=
    '<div id="transferError" class="error" style="margin-bottom: 10px;"></div>';

  html += "</div>";
  html += '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px;">';
  html +=
    '<button class="btn primary2" onclick="doTransfer()">🚀 Отправить</button>';
  html +=
    '<button class="btn" onclick="openMassTransfer()">👥 Массовый перевод</button>'; // Если у вас есть эта функция
  html += "</div></div>";

  // Блок истории
  html += '<h4 style="margin:0 0 12px;">📜 История</h4>';
  html += '<div id="transferHistoryList">' + historyHtml + "</div>";

  html += "</div></section>";

  el.innerHTML = html;
}
function renderTransferHistory(user) {
  var el = document.getElementById("transferHistory");
  if (!el) return;
  var my = transfers
    .filter(function (t) {
      return t.fromId === user.id || t.toId === user.id;
    })
    .slice()
    .reverse()
    .slice(0, 50);
  if (list.length === 0) {
    el.innerHTML =
      '<div class="empty" data-icon="💸" style="margin-top:20px; padding: 30px;"><b>Нет переводов</b><small>Здесь появится история ваших переводов.</small></div>';
    return;
  }
  var html =
    '<div class="table-wrap"><table style="min-width:800px;"><thead><tr><th>Время</th><th>От</th><th>Кому</th><th>Сумма</th><th>Комиссия</th><th>Получено</th></tr></thead><tbody>';
  html += my
    .map(function (t) {
      var inc = t.toId === user.id;
      var sym = t.currency === "coins" ? "🪙 " : "💵 ";
      var suf = t.currency === "coins" ? "" : " ₽";
      var col = inc ? "var(--accent)" : "var(--danger)";
      return (
        '<tr class="' +
        (inc ? "transfer-row-in" : "transfer-row-out") +
        '"><td>' +
        new Date(t.time).toLocaleString() +
        "</td><td>" +
        esc(t.fromName) +
        "</td><td>" +
        esc(t.toName) +
        "</td><td>" +
        sym +
        fmtBalance(t.amount) +
        suf +
        "</td><td>" +
        sym +
        fmtBalance(t.fee) +
        suf +
        '</td><td><b style="color:' +
        col +
        '">' +
        (inc ? "+" : "−") +
        sym +
        fmtBalance(t.netAmount) +
        suf +
        "</b></td></tr>"
      );
    })
    .join("");
  html += "</tbody></table></div>";
  el.innerHTML = html;
}
