function renderLoginLog() {
  var user = current();
  if (!user) return;
  var grid = document.getElementById("loginLogGrid");
  if (!grid) return;
  if (!can(user, "view_login_logs")) {
    grid.innerHTML =
      '<div class="empty" data-icon="🔒" style="grid-column:1/-1;"><b>Нет доступа</b><small>Требуется разрешение на просмотр журнала входов</small></div>';
    return;
  }
  var q = (document.getElementById("loginLogSearch").value || "")
    .toLowerCase()
    .trim();
  var list = loginLogs.filter(function (l) {
    if (!q) return true;
    if ((l.userName || "").toLowerCase().indexOf(q) !== -1) return true;
    if ((l.device || "").toLowerCase().indexOf(q) !== -1) return true;
    if ((l.role || "").toLowerCase().indexOf(q) !== -1) return true;
    return false;
  });
  list = list.slice().reverse();
  document.getElementById("loginLogCount").textContent = list.length;
  if (!list.length) {
    grid.innerHTML =
      '<div class="empty" data-icon="🔐" style="grid-column:1/-1;"><b>Входов не зафиксировано</b><small>История появится после первого входа</small></div>';
    return;
  }
  grid.innerHTML = list
    .slice(0, 200)
    .map(function (l) {
      var u = users.find(function (x) {
        return x.id === l.userId;
      });
      var avatarHtml = u ? avatarContent(u) : esc(initials(l.userName));
      var devParts = (l.device || "").split("·").map(function (s) {
        return s.trim();
      });
      var deviceChip = devParts[0]
        ? '<span class="chip">' + esc(devParts[0]) + "</span>"
        : '<span class="chip">—</span>';
      var browserChip = devParts[1]
        ? '<span class="chip">🌐 ' + esc(devParts[1]) + "</span>"
        : "";
      return (
        '<div class="login-card"><div class="lc-head"><div class="lc-user"><span class="mini-avatar" style="width:36px;height:36px;font-size:14px;">' +
        avatarHtml +
        '</span><div style="min-width:0;"><div style="font-weight:800;font-size:14px;' +
        (u && safeColor(u.nickColor)
          ? "color:" + safeColor(u.nickColor) + ";"
          : "") +
        '">' +
        esc(l.userName) +
        "</div><div>" +
        roleLabelHtml(l.role || "—", false) +
        '</div></div></div><div class="log-time" style="font-size:11px;color:var(--muted);text-align:right;white-space:nowrap;">🕐 ' +
        new Date(l.time).toLocaleString() +
        '</div></div><div class="lc-device">' +
        deviceChip +
        browserChip +
        '<span class="chip">📐 ' +
        esc(l.screen || "—") +
        '</span><span class="chip">🖥 ' +
        esc(l.resolution || "—") +
        "</span></div></div>"
      );
    })
    .join("");
}
