function cancelChallenge(id) {
  if (!checkBlocked()) return;
  var c = challenges.find(function (x) {
    return x.id === id;
  });
  if (!c || c.status !== "pending" || c.creatorId !== currentId) return;
  if (!confirm("Отменить?")) return;
  if (c.prize) {
    if (c.prize.currency === "coins")
      changeCoins(c.creatorId, c.prize.amount, "Возврат");
    else changeBalance(c.creatorId, c.prize.amount, "Возврат");
  }
  c.status = "cancelled";
  saveChallenges();
  toast("❌ Челлендж отменён");
  renderDuels();
}
function finishChallenge(id) {
  if (!checkBlocked()) return;
  var c = challenges.find(function (x) {
    return x.id === id;
  });
  if (!c || c.status !== "active") return;
  // FIX: защита от отсутствия prize
  if (!c.prize) {
    toast("❌ Повреждённый челлендж");
    c.status = "cancelled";
    saveChallenges();
    renderDuels();
    return;
  }
  var user = current();
  var canForce =
    can(user, "manage_permissions") ||
    c.creatorId === user.id ||
    c.opponentId === user.id;
  if (!canForce) {
    toast("❌ Нет прав");
    return;
  }
  function getProgress(userId) {
    var since = new Date(c.createdAt).getTime();
    if (!isFinite(since)) since = 0;
    if (c.type === "tasks_done")
      return tasks.filter(function (t) {
        return (
          t.assignee === userId &&
          t.status === "done" &&
          new Date(t.createdAt).getTime() > since
        );
      }).length;
    if (c.type === "transfers_made")
      return transfers.filter(function (t) {
        return t.fromId === userId && new Date(t.time).getTime() > since;
      }).length;
    if (c.type === "coins_earned") {
      var u = users.find(function (x) {
        return x.id === userId;
      });
      var sum = 0;
      ((u && u.coinHistory) || []).forEach(function (h) {
        if (h.amount > 0 && new Date(h.time).getTime() > since) sum += h.amount;
      });
      return sum;
    }
    if (c.type === "spins") {
      var u = users.find(function (x) {
        return x.id === userId;
      });
      if (!u) return 0;
      // FIX: считаем только спины с начала челленджа — по trustHistory/coinHistory нет, берём дельту
      var log = u.spinHistory || [];
      if (!log.length) return 0;
      var sum = 0;
      log.forEach(function (h) {
        if (new Date(h.time).getTime() > since) sum++;
      });
      return sum;
    }
    return 0;
  }
  var cp = getProgress(c.creatorId),
    op = getProgress(c.opponentId);
  var winnerId, winnerName;
  if (cp > op) {
    winnerId = c.creatorId;
    winnerName = c.creatorName;
  } else if (op > cp) {
    winnerId = c.opponentId;
    winnerName = c.opponentName;
  } else {
    winnerId = null;
  }
  var pot = c.prize.amount * 2;
  if (winnerId) {
    if (c.prize.currency === "coins")
      changeCoins(winnerId, pot, "Победа в челлендже");
    else changeBalance(winnerId, pot, "Победа в челлендже");
  } else {
    if (c.prize.currency === "coins") {
      changeCoins(c.creatorId, c.prize.amount, "Ничья");
      changeCoins(c.opponentId, c.prize.amount, "Ничья");
    } else {
      changeBalance(c.creatorId, c.prize.amount, "Ничья");
      changeBalance(c.opponentId, c.prize.amount, "Ничья");
    }
  }
  c.winnerId = winnerId;
  c.status = "finished";
  c.finishedAt = new Date().toISOString();
  c.progress = { creator: cp, opponent: op };
  saveChallenges();
  saveUsers();
  addNotification(c.creatorId, "⚔️ Челлендж завершён: " + cp + " / " + op);
  addNotification(c.opponentId, "⚔️ Челлендж завершён: " + op + " / " + cp);
  toast(winnerId ? "🏆 " + winnerName + " победил!" : "🤝 Ничья");
  renderDuels();
}
