/* ============ /UI ПРАВ РОЛЕЙ ============ */

/* ============ ЛИЧНЫЕ ПРАВА ============ */
function getEffectivePermissions(user) {
  if (!user) return [];
  if (user.role === "Владелец" || user.role === "Разработчик")
    return ALL_PERMISSIONS.slice();
  var base = (rolePermissions[user.role] || []).slice();
  var extra = Array.isArray(user.extraPermissions) ? user.extraPermissions : [];
  var denied = Array.isArray(user.deniedPermissions)
    ? user.deniedPermissions
    : [];
  var result = base.filter(function (p) {
    return denied.indexOf(p) === -1;
  });
  extra.forEach(function (p) {
    if (result.indexOf(p) === -1) result.push(p);
  });
  return result;
}

function renderUserPermsList() {
  var el = document.getElementById("userPermsList");
  if (!el) return;
  var admin = current();
  if (!admin || !can(admin, "manage_permissions")) {
    el.innerHTML = '<div class="empty" data-icon="🔒"><b>Нет доступа</b></div>';
    return;
  }
  var _fs = _saveFocusByIds(["userPermsSearch"]);
  var q = ((document.getElementById("userPermsSearch") || {}).value || "")
    .toLowerCase()
    .trim();
  var list = users.slice();
  if (q)
    list = list.filter(function (u) {
      return (
        (u.name || "").toLowerCase().indexOf(q) !== -1 ||
        (u.role || "").toLowerCase().indexOf(q) !== -1
      );
    });
  list.sort(function (a, b) {
    return (a.name || "").localeCompare(b.name || "", "ru");
  });
  if (!list.length) {
    el.innerHTML =
      '<div class="empty" data-icon="🔍"><b>Никого не найдено</b></div>';
    _restoreFocus(_fs);
    return;
  }
  var html = '<div class="shop-grid" style="padding:0;">';
  list.forEach(function (u) {
    var eff = getEffectivePermissions(u);
    var base = (rolePermissions[u.role] || []).length;
    var extraCnt = (u.extraPermissions || []).length;
    var deniedCnt = (u.deniedPermissions || []).length;
    var isMe = u.id === currentId;
    var avHTML =
      '<span class="' +
      withFrame(u, "mini-avatar") +
      '" style="width:44px;height:44px;font-size:16px;">' +
      avatarContent(u) +
      "</span>";
    var hasOverride = extraCnt > 0 || deniedCnt > 0;
    html += '<div class="shop-item" style="cursor:default;gap:10px;">';
    html += '<div style="display:flex;gap:10px;align-items:center;">' + avHTML;
    html +=
      '<div style="flex:1;min-width:0;"><div style="font-weight:800;font-size:15px;' +
      (safeColor(u.nickColor) ? "color:" + safeColor(u.nickColor) + ";" : "") +
      '">' +
      esc(u.name) +
      (isMe ? ' <span class="muted" style="font-size:11px;">(вы)</span>' : "") +
      "</div><div>" +
      roleLabelHtml(u.role, true) +
      "</div></div></div>";
    html +=
      '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;">';
    html +=
      '<div style="background:#00000055;border:1px solid #ffffff0d;border-radius:8px;padding:6px;text-align:center;"><div style="font-size:9px;color:var(--muted);text-transform:uppercase;">Роль</div><div style="font-weight:800;font-size:14px;">' +
      base +
      "</div></div>";
    html +=
      '<div style="background:#00000055;border:1px solid #ffffff0d;border-radius:8px;padding:6px;text-align:center;"><div style="font-size:9px;color:var(--muted);text-transform:uppercase;">+ Личных</div><div style="font-weight:800;font-size:14px;color:var(--accent);">' +
      (extraCnt > 0 ? "+" + extraCnt : "—") +
      "</div></div>";
    html +=
      '<div style="background:#00000055;border:1px solid #ffffff0d;border-radius:8px;padding:6px;text-align:center;"><div style="font-size:9px;color:var(--muted);text-transform:uppercase;">− Запрет</div><div style="font-weight:800;font-size:14px;color:var(--danger);">' +
      (deniedCnt > 0 ? "−" + deniedCnt : "—") +
      "</div></div>";
    html += "</div>";
    html +=
      '<div style="font-size:11px;color:var(--muted);text-align:center;">Итого: <b style="color:var(--gold);">' +
      eff.length +
      "</b> / " +
      ALL_PERMISSIONS.length +
      "</div>";
    if (hasOverride) {
      html +=
        '<div style="background:#1a3d2a;border:1px solid #39c982;border-radius:8px;padding:6px;text-align:center;font-size:11px;color:#83e6ad;font-weight:700;">⚡ Есть личные переопределения</div>';
    }
    html += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;">';
    html +=
      '<button class="btn small primary2" onclick="openUserPermsModal(' +
      jsArg(u.id) +
      ')">⚙ Настроить</button>';
    html +=
      '<button class="btn small" onclick="openProfileInTab(' +
      jsArg(u.id) +
      ')">👤 Профиль</button>';
    html += "</div>";
    if (hasOverride) {
      html +=
        '<button class="btn small danger" style="width:100%;" onclick="resetUserOverrides(' +
        jsArg(u.id) +
        ')">↺ Сбросить личные права</button>';
    }
    html += "</div>";
  });
  html += "</div>";
  el.innerHTML = html;
  _restoreFocus(_fs);
}

function resetUserOverrides(userId) {
  if (!checkBlocked()) return;
  var admin = current();
  if (!admin || !can(admin, "manage_permissions")) return;
  var u = users.find(function (x) {
    return x.id === userId;
  });
  if (!u) return;
  if (
    !confirm(
      "Сбросить личные права у «" + u.name + "»? Вернутся только ролевые.",
    )
  )
    return;
  u.extraPermissions = [];
  u.deniedPermissions = [];
  saveUsers();
  toast("↺ Личные права сброшены у " + u.name);
  addLog("Сброс личных прав", u.name);
  renderUserPermsList();
  if (profileUserId === u.id)
    try {
      renderProfileTab(u.id);
    } catch (e) {}
}

var _userPermsDraft = null;
function openUserPermsModal(userId, keepDraft) {
  if (!checkBlocked()) return;
  var admin = current();
  if (!admin || !can(admin, "manage_permissions")) {
    toast("Нет прав");
    return;
  }
  var u = users.find(function (x) {
    return x.id === userId;
  });
  if (!u) return;
  if (u.role === "Владелец" && u.id !== admin.id) {
    toast("Нельзя ограничивать Владельца", "warn");
    return;
  }
  var base = rolePermissions[u.role] || [];
  if (!keepDraft || !_userPermsDraft || _userPermsDraft.userId !== userId) {
    _userPermsDraft = {
      userId: userId,
      extra: Array.isArray(u.extraPermissions)
        ? u.extraPermissions.slice()
        : [],
      denied: Array.isArray(u.deniedPermissions)
        ? u.deniedPermissions.slice()
        : [],
    };
  }
  var html = "<h2>⚙ Личные права — " + esc(u.name) + "</h2>";
  html +=
    '<p class="muted">Роль: <b>' +
    ROLE_ICONS[u.role] +
    " " +
    esc(u.role) +
    "</b> · Ролевых прав: <b>" +
    base.length +
    "</b></p>";
  html +=
    '<div class="notes-section" style="background:#0b1710;margin-bottom:14px;"><b>💡 Как это работает</b><div style="font-size:12px;color:var(--muted);line-height:1.6;margin-top:6px;">';
  html +=
    '<div>🟢 <b style="color:var(--accent);">Разрешено</b> — добавить право сверх роли (даже если роли его не хватает)</div>';
  html +=
    '<div>🔴 <b style="color:var(--danger);">Запрещено</b> — отобрать право, которое даёт роль</div>';
  html += "<div>⚪ <b>Наследовать</b> — как в роли (по умолчанию)</div>";
  html += "</div></div>";
  html +=
    '<input class="search" id="userPermsFilter" placeholder="🔍 Поиск права..." oninput="filterUserPermItems(this.value)" style="width:100%;margin-bottom:12px;">';
  html +=
    '<div style="display:flex;gap:6px;margin-bottom:12px;flex-wrap:wrap;"><button class="btn small" onclick="userPermsBulk(true)">✅ Разрешить всё</button><button class="btn small danger" onclick="userPermsBulk(false)">✖ Запретить всё</button><button class="btn small" onclick="userPermsBulk(null)">↺ Наследовать всё</button></div>';
  html +=
    '<div id="userPermsEditor" style="max-height:55vh;overflow-y:auto;padding-right:6px;">';
  for (var cat in PERM_CATEGORIES) {
    if (!PERM_CATEGORIES.hasOwnProperty(cat)) continue;
    var catPerms = PERM_CATEGORIES[cat];
    var catIcon = PERM_CATEGORY_ICONS[cat] || "📁";
    html +=
      '<div class="perm-cat-card expanded" data-cat="' +
      esc(cat) +
      '" style="margin-bottom:8px;">';
    html +=
      '<div class="perm-cat-header" style="cursor:default;"><span class="perm-cat-icon">' +
      catIcon +
      '</span><span class="perm-cat-title">' +
      esc(cat) +
      "</span></div>";
    html +=
      '<div class="perm-cat-body" style="max-height:none;"><div class="perm-cat-body-inner" style="grid-template-columns:1fr;">';
    catPerms.forEach(function (p) {
      var inRole = base.indexOf(p) !== -1;
      var isExtra = _userPermsDraft.extra.indexOf(p) !== -1;
      var isDenied = _userPermsDraft.denied.indexOf(p) !== -1;
      var state = isDenied
        ? "deny"
        : isExtra
          ? "grant"
          : inRole
            ? "inherit"
            : "inherit";
      var label = PERM_LABELS[p] || p;
      var desc = PERM_DESCRIPTIONS[p] || "";
      html +=
        '<div class="perm-item-v2" data-perm="' +
        esc(p) +
        '" style="cursor:default;padding:8px 10px;">';
      html +=
        '<div class="pi-body" style="flex:1;"><div class="pi-name" style="font-size:12px;">' +
        esc(label) +
        ' <span style="font-size:10px;opacity:.6;">' +
        (inRole ? "(в роли)" : "(нет в роли)") +
        "</span></div>" +
        (desc
          ? '<div class="pi-desc" style="font-size:10px;">' +
            esc(desc) +
            "</div>"
          : "") +
        "</div>";
      html += '<div style="display:flex;gap:3px;flex-shrink:0;">';
      html +=
        '<button type="button" class="btn small" style="padding:4px 8px;font-size:10px;' +
        (state === "inherit"
          ? "background:#1a3d2a;border-color:var(--accent);color:#83e6ad;"
          : "") +
        '" onclick="setUserPermState(\'' +
        esc(p) +
        "','inherit',this)\">⚪</button>";
      html +=
        '<button type="button" class="btn small" style="padding:4px 8px;font-size:10px;' +
        (state === "grant"
          ? "background:#1a3d2a;border-color:var(--accent);color:#83e6ad;"
          : "") +
        '" onclick="setUserPermState(\'' +
        esc(p) +
        "','grant',this)\">🟢</button>";
      html +=
        '<button type="button" class="btn small danger" style="padding:4px 8px;font-size:10px;' +
        (state === "deny" ? "opacity:1;" : "opacity:.5;") +
        '" onclick="setUserPermState(\'' +
        esc(p) +
        "','deny',this)\">🔴</button>";
      html += "</div></div>";
    });
    html += "</div></div></div>";
  }
  html += "</div>";
  html +=
    '<div class="modal-actions"><button class="btn" onclick="closeModal()">Отмена</button><button class="btn primary2" onclick="saveUserPerms()">💾 Сохранить</button></div>';
  document.getElementById("modalContent").innerHTML = html;
  document.getElementById("modal").classList.remove("hidden");
}

function setUserPermState(perm, state, btn) {
  if (!_userPermsDraft) return;
  _userPermsDraft.extra = _userPermsDraft.extra.filter(function (p) {
    return p !== perm;
  });
  _userPermsDraft.denied = _userPermsDraft.denied.filter(function (p) {
    return p !== perm;
  });
  if (state === "grant") _userPermsDraft.extra.push(perm);
  else if (state === "deny") _userPermsDraft.denied.push(perm);
  /* Перерисовать кнопки только у этого элемента */
  var wrap = btn.closest(".perm-item-v2");
  if (wrap) {
    var btns = wrap.querySelectorAll("button");
    btns.forEach(function (b) {
      b.style.background = "";
      b.style.borderColor = "";
      b.style.color = "";
      b.style.opacity = ".5";
    });
    btn.style.opacity = "1";
    btn.style.background = state === "deny" ? "#3d1a1a" : "#1a3d2a";
    btn.style.borderColor =
      state === "deny" ? "var(--danger)" : "var(--accent)";
    btn.style.color = state === "deny" ? "#ff8a8a" : "#83e6ad";
  }
}

function filterUserPermItems(q) {
  q = (q || "").toLowerCase().trim();
  document
    .querySelectorAll("#userPermsEditor .perm-item-v2")
    .forEach(function (item) {
      var perm = item.getAttribute("data-perm") || "";
      var text = (
        (PERM_LABELS[perm] || "") +
        " " +
        (PERM_DESCRIPTIONS[perm] || "") +
        " " +
        perm
      ).toLowerCase();
      item.style.display = !q || text.indexOf(q) !== -1 ? "" : "none";
    });
}

function userPermsBulk(state) {
  if (!_userPermsDraft) return;
  _userPermsDraft.extra = [];
  _userPermsDraft.denied = [];
  if (state === true) _userPermsDraft.extra = ALL_PERMISSIONS.slice();
  else if (state === false) _userPermsDraft.denied = ALL_PERMISSIONS.slice();
  openUserPermsModal(_userPermsDraft.userId, true);
}

function saveUserPerms() {
  if (!checkBlocked()) return;
  var admin = current();
  if (!admin || !can(admin, "manage_permissions")) return;
  if (!_userPermsDraft) return;
  var u = users.find(function (x) {
    return x.id === _userPermsDraft.userId;
  });
  if (!u) return;
  u.extraPermissions = _userPermsDraft.extra.slice();
  u.deniedPermissions = _userPermsDraft.denied.slice();
  saveUsers();
  addLog("Личные права изменены", u.name);
  toast("💾 Личные права сохранены для " + u.name);
  _userPermsDraft = null;
  closeModal();
  renderUserPermsList();
  if (profileUserId === u.id)
    try {
      renderProfileTab(u.id);
    } catch (e) {}
}
