/* ============ #52 — ЛИМИТЫ ПО ЮЗЕРУ ============ */
function openUserLimitsModal(userId) {
  if (!checkBlocked()) return;
  var admin = current();
  if (!admin || !can(admin, "manage_limits")) {
    toast("❌ Нет прав", "error");
    return;
  }
  var u = users.find(function (x) {
    return x.id === userId;
  });
  if (!u) {
    toast("❌ Пользователь не найден", "error");
    return;
  }
  if (u.role === "Владелец" && u.id !== admin.id) {
    toast("⚠️ Нельзя ограничивать Владельца", "warn");
    return;
  }
  if (
    !u.limitOverrides ||
    typeof u.limitOverrides !== "object" ||
    Array.isArray(u.limitOverrides)
  )
    u.limitOverrides = {};
  renderUserLimitsModal(u);
}

function renderUserLimitsModal(u) {
  if (!u) return;
  var html = "<h2>🔢 Лимиты — " + esc(u.name) + "</h2>";
  html +=
    '<p class="muted" style="font-size:12px;margin:0 0 12px;line-height:1.5;">Значения применяются <b>только к этому сотруднику</b> и переопределяют глобальные. Оставьте поле пустым — будет использоваться глобальное значение.</p>';
  html +=
    '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px;">';
  html +=
    '<button class="btn small danger" onclick="clearAllUserLimits(\'' +
    u.id +
    "')\">↺ Сбросить всё к глобальным</button>";
  html +=
    '<input class="search" id="userLimitSearch" placeholder="🔍 Поиск поля..." oninput="filterUserLimitFields(this.value)" style="flex:1;min-width:180px;">';
  html += "</div>";
  html +=
    '<div id="userLimitsEditor" style="max-height:60vh;overflow-y:auto;padding-right:6px;">';
  for (var section in LIMITS_META) {
    if (!LIMITS_META.hasOwnProperty(section)) continue;
    var meta = LIMITS_META[section];
    var globalData = LIMITS[section] || {};
    var userData = u.limitOverrides[section] || {};
    html +=
      '<div class="perm-role-card expanded" data-lim-section="' +
      section +
      '" style="margin-bottom:10px;">';
    html +=
      '<div class="perm-role-header" style="cursor:default;"><span class="perm-role-icon">' +
      meta.icon +
      '</span><span class="perm-role-title">' +
      esc(meta.label) +
      "</span></div>";
    html +=
      '<div class="perm-role-body" style="max-height:none;"><div class="perm-role-body-inner">';
    for (var groupName in meta.sections) {
      if (!meta.sections.hasOwnProperty(groupName)) continue;
      html += '<div style="margin-bottom:12px;">';
      html +=
        '<div style="font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em;font-weight:800;margin-bottom:6px;padding-bottom:3px;border-bottom:1px solid #ffffff08;">' +
        esc(groupName) +
        "</div>";
      html +=
        '<div class="grid" style="grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:8px;">';
      var fields = meta.sections[groupName];
      for (var key in fields) {
        if (!fields.hasOwnProperty(key)) continue;
        var f = fields[key];
        var globalVal = globalData[key];
        var overrideVal = userData[key];
        var hasOverride = typeof overrideVal === "number";
        var displayGlobal = globalVal;
        var shown = hasOverride ? overrideVal : "";
        if (f.kind === "minutes") {
          displayGlobal = Math.round((globalVal || 0) / 60000);
          if (hasOverride) shown = Math.round(overrideVal / 60000);
        } else if (f.kind === "seconds") {
          displayGlobal = Math.round((globalVal || 0) / 1000);
          if (hasOverride) shown = Math.round(overrideVal / 1000);
        } else if (f.kind === "mb") {
          displayGlobal = Math.round((globalVal || 0) / 1048576);
          if (hasOverride) shown = Math.round(overrideVal / 1048576);
        }
        html +=
          '<div class="field lim-field" data-search="' +
          esc((f.l + " " + key + " " + meta.label).toLowerCase()) +
          '" style="margin:0;">';
        html +=
          '<label style="display:flex;justify-content:space-between;align-items:center;gap:6px;font-size:11px;">';
        html +=
          "<span>" +
          esc(f.l) +
          ' <span class="muted" style="font-weight:400;">' +
          esc(f.u || "") +
          "</span></span>";
        if (hasOverride)
          html +=
            '<span class="badge badge-gold" style="font-size:9px;padding:1px 5px;">override</span>';
        html += "</label>";
        html +=
          '<input type="number" class="user-lim-input" data-section="' +
          esc(section) +
          '" data-key="' +
          esc(key) +
          '" data-kind="' +
          (f.kind || "") +
          '" data-min="' +
          f.min +
          '" data-max="' +
          f.max +
          '" value="' +
          shown +
          '" placeholder="глобальное: ' +
          displayGlobal +
          '" min="' +
          f.min +
          '" max="' +
          f.max +
          '" style="font-size:13px;padding:7px 9px;' +
          (hasOverride ? "border-color:var(--gold);" : "") +
          '">';
        html += "</div>";
      }
      html += "</div></div>";
    }
    html += "</div></div></div>";
  }
  html += "</div>";
  html += '<div class="modal-actions">';
  html += '<button class="btn" onclick="closeModal()">Отмена</button>';
  html +=
    '<button class="btn primary2" onclick="saveUserLimits(\'' +
    u.id +
    "')\">💾 Сохранить</button>";
  html += "</div>";
  document.getElementById("modalContent").innerHTML = html;
  document.getElementById("modal").classList.remove("hidden");
}

function filterUserLimitFields(q) {
  q = (q || "").toLowerCase().trim();
  document
    .querySelectorAll("#userLimitsEditor .lim-field")
    .forEach(function (el) {
      var hay = el.getAttribute("data-search") || "";
      el.style.display = !q || hay.indexOf(q) !== -1 ? "" : "none";
    });
}

function saveUserLimits(userId) {
  if (!checkBlocked()) return;
  var admin = current();
  if (!admin || !can(admin, "manage_limits")) {
    toast("❌ Нет прав", "error");
    return;
  }
  if (!rateLimit("saveLimits")) return;
  var u = users.find(function (x) {
    return x.id === userId;
  });
  if (!u) return;
  var errors = [];
  var newOverrides = {};
  document.querySelectorAll(".user-lim-input").forEach(function (inp) {
    var section = inp.getAttribute("data-section");
    var key = inp.getAttribute("data-key");
    var kind = inp.getAttribute("data-kind");
    var min = parseFloat(inp.getAttribute("data-min"));
    var max = parseFloat(inp.getAttribute("data-max"));
    var rawStr = (inp.value || "").trim();
    if (rawStr === "") return; /* пусто = наследовать глобальное */
    var raw = parseFloat(rawStr);
    if (!isFinite(raw)) {
      errors.push(section + "." + key + ": не число");
      return;
    }
    if (raw < min || raw > max) {
      errors.push(section + "." + key + ": " + min + "–" + max);
      return;
    }
    var finalVal = raw;
    if (kind === "minutes") finalVal = Math.round(raw * 60000);
    else if (kind === "seconds") finalVal = Math.round(raw * 1000);
    else if (kind === "mb") finalVal = Math.round(raw * 1048576);
    else finalVal = Math.round(raw);
    if (!newOverrides[section]) newOverrides[section] = {};
    newOverrides[section][key] = finalVal;
  });
  if (errors.length) {
    toast("❌ " + errors.slice(0, 3).join(" · "), "error");
    return;
  }
  var prevCount = 0;
  Object.keys(u.limitOverrides || {}).forEach(function (s) {
    prevCount += Object.keys(u.limitOverrides[s] || {}).length;
  });
  u.limitOverrides = newOverrides;
  var newCount = 0;
  Object.keys(newOverrides).forEach(function (s) {
    newCount += Object.keys(newOverrides[s] || {}).length;
  });
  saveUsers();
  addLog(
    "Лимиты пользователя изменены",
    u.name + " · " + prevCount + "→" + newCount,
  );
  toast("💾 Лимиты сохранены (" + newCount + " переопределений)", "success");
  closeModal();
  if (profileUserId === u.id)
    try {
      renderProfileTab(u.id);
    } catch (e) {}
}

function clearAllUserLimits(userId) {
  if (!checkBlocked()) return;
  var admin = current();
  if (!admin || !can(admin, "manage_limits")) {
    toast("❌ Нет прав", "error");
    return;
  }
  var u = users.find(function (x) {
    return x.id === userId;
  });
  if (!u) return;
  var cnt = 0;
  Object.keys(u.limitOverrides || {}).forEach(function (s) {
    cnt += Object.keys(u.limitOverrides[s] || {}).length;
  });
  if (!cnt) {
    toast("⚠️ Нет переопределений", "warn");
    return;
  }
  if (!confirm("Сбросить все личные лимиты (" + cnt + " шт.) к глобальным?"))
    return;
  u.limitOverrides = {};
  saveUsers();
  addLog("Сброс личных лимитов", u.name);
  toast("↺ Все лимиты сброшены к глобальным", "success");
  renderUserLimitsModal(u);
}
/* ============ /ЛИМИТЫ ПО ЮЗЕРУ ============ */

/* ============ #48 — ДОСТИЖЕНИЯ: ЛОГИКА ============ */
function getUserAchievementProgress(user, def) {
  try {
    var raw = def.check(user);
    var num = Number(raw);
    if (!isFinite(num) || isNaN(num)) return 0;
    return Math.max(0, num);
  } catch (e) {
    try {
      console.warn("[achievement] check failed for", def && def.id, e);
    } catch (_) {}
    return 0;
  }
}

function getUserAchievements(user) {
  if (!user) return [];
  if (!Array.isArray(ACHIEVEMENTS)) {
    try {
      console.error("[achievements] ACHIEVEMENTS is not array");
    } catch (_) {}
    return [];
  }

  if (
    !user.claimedAchievements ||
    typeof user.claimedAchievements !== "object" ||
    Array.isArray(user.claimedAchievements)
  ) {
    user.claimedAchievements = {};
  }

  var result = [];
  ACHIEVEMENTS.forEach(function (def) {
    if (!def || !def.id) {
      return;
    }
    var prog = 0;
    try {
      prog = getUserAchievementProgress(user, def);
    } catch (_) {
      prog = 0;
    }
    var goal = typeof def.goal === "number" && def.goal > 0 ? def.goal : 1;
    var done = prog >= goal;
    var claimed = !!user.claimedAchievements[def.id];
    result.push({
      def: def,
      progress: prog,
      done: done,
      claimed: claimed,
      ready: done && !claimed,
    });
  });
  return result;
}

function checkAchievements(user) {
  if (!user) return [];
  if (user.id !== currentId) return [];
  var list = getUserAchievements(user);
  var readyList = list.filter(function (a) {
    return a.ready;
  });
  if (readyList.length) {
    var names = summarizeList(
      readyList.map(function (a) {
        return a.def.icon + " " + a.def.name;
      }),
      2,
    );
    var text = "🏆 Достижение готово к получению: " + names;
    var exists = notifications.some(function (n) {
      return n.userId === user.id && !n.read && n.text === text;
    });
    if (!exists) {
      addNotification(user.id, text);
      playSound("levelup");
    }
  }
  return readyList;
}

function claimAchievement(userId, achId) {
  if (!checkBlocked()) return;
  var u = users.find(function (x) {
    return x.id === userId;
  });
  if (!u) return;
  if (userId !== currentId) {
    toast("❌ Только свои достижения", "error");
    return;
  }
  var def = ACHIEVEMENTS.find(function (d) {
    return d.id === achId;
  });
  if (!def) {
    toast("❌ Достижение не найдено", "error");
    return;
  }
  if (!u.claimedAchievements) u.claimedAchievements = {};
  if (u.claimedAchievements[achId]) {
    toast("⚠️ Уже получено", "warn");
    return;
  }
  var prog = getUserAchievementProgress(u, def);
  if (prog < def.goal) {
    toast("⚠️ Ещё не выполнено (" + prog + "/" + def.goal + ")", "warn");
    return;
  }
  u.claimedAchievements[achId] = new Date().toISOString();
  changeCoins(u.id, def.reward, "Достижение: " + def.name);
  if (!u.customBadges) u.customBadges = [];
  if (
    !u.customBadges.some(function (b) {
      return b.name === def.name;
    })
  ) {
    u.customBadges.push({
      name: def.name,
      icon: def.icon,
      class: "badge-gold",
    });
  }
  saveUsers();
  playSound("badge");
  toast(
    "🏆 Достижение получено: " +
      def.icon +
      " " +
      def.name +
      " · 🪙 +" +
      def.reward,
    "success",
    { duration: 4000 },
  );
  addLog("Достижение получено", u.name + " · " + def.name);
  if (profileUserId === u.id)
    try {
      renderProfileTab(u.id);
    } catch (e) {}
  renderStaff();
}

function claimAllAchievements(userId) {
  if (!checkBlocked()) return;
  var u = users.find(function (x) {
    return x.id === userId;
  });
  if (!u) return;
  if (userId !== currentId) {
    toast("❌ Только свои", "error");
    return;
  }
  var list = getUserAchievements(u).filter(function (a) {
    return a.ready;
  });
  if (!list.length) {
    toast("⚠️ Нет готовых", "warn");
    return;
  }
  var total = list.reduce(function (s, a) {
    return s + a.def.reward;
  }, 0);
  if (
    !confirm(
      "Забрать " + list.length + " достижений и получить 🪙 " + total + "?",
    )
  )
    return;
  list.forEach(function (a) {
    u.claimedAchievements[a.def.id] = new Date().toISOString();
    if (!u.customBadges) u.customBadges = [];
    if (
      !u.customBadges.some(function (b) {
        return b.name === a.def.name;
      })
    ) {
      u.customBadges.push({
        name: a.def.name,
        icon: a.def.icon,
        class: "badge-gold",
      });
    }
  });
  changeCoins(u.id, total, "Достижения ×" + list.length);
  saveUsers();
  playSound("levelup");
  toast(
    "🏆 Получено " + list.length + " достижений · 🪙 +" + total,
    "success",
    { duration: 4000 },
  );
  if (profileUserId === u.id)
    try {
      renderProfileTab(u.id);
    } catch (e) {}
  renderStaff();
}
/* ============ /ДОСТИЖЕНИЯ: ЛОГИКА ============ */

function renderFieldChangesTab(u) {
  var cu = current();
  if (!cu) return "";

  if (u.id !== cu.id && !can(cu, "view_staff")) {
    return '<div class="empty" data-icon="🔒"><b>Нет доступа</b><small>Требуется право на просмотр сотрудников</small></div>';
  }

  var userChanges = changeLog
    .filter(function (c) {
      return c.userId === u.id;
    })
    .sort(function (a, b) {
      return new Date(b.at) - new Date(a.at);
    });

  if (!userChanges.length) {
    return '<div class="empty" data-icon="📝"><b>Изменений пока не было</b><small>Все изменения профиля будут записываться здесь</small></div>';
  }

  var filter = window["_chFilter_" + u.id] || "all";

  var counts = {
    all: userChanges.length,
    profile: 0,
    money: 0,
    status: 0,
    security: 0,
    other: 0,
  };
  userChanges.forEach(function (c) {
    var cat = _changeCategory(c.field);
    if (counts[cat] !== undefined) counts[cat]++;
  });

  var filtered =
    filter === "all"
      ? userChanges
      : userChanges.filter(function (c) {
          return _changeCategory(c.field) === filter;
        });

  var html =
    '<div class="profile-section-title">📝 История изменений (' +
    counts.all +
    ")</div>";

  html += '<div class="shop-cats" style="margin-bottom:14px;">';
  var catList = [
    ["all", "📋 Все (" + counts.all + ")"],
    ["profile", "👤 Профиль (" + counts.profile + ")"],
    ["money", "💰 Деньги (" + counts.money + ")"],
    ["status", "❄️ Статус (" + counts.status + ")"],
    ["security", "🔐 Пароль (" + counts.security + ")"],
  ];
  catList.forEach(function (o) {
    if (o[0] !== "all" && o[1].indexOf("(0)") !== -1) return;
    html +=
      '<button class="shop-cat ' +
      (filter === o[0] ? "active" : "") +
      '" onclick="window._chFilter_' +
      u.id +
      "='" +
      o[0] +
      "';switchProfileTabInProfile('changes','" +
      u.id +
      "')\">" +
      o[1] +
      "</button>";
  });
  html += "</div>";

  html +=
    '<div style="display:flex;flex-direction:column;gap:8px;max-height:600px;overflow-y:auto;">';
  filtered.forEach(function (c) {
    var cat = _changeCategory(c.field);
    var ico =
      { profile: "👤", money: "💰", status: "❄️", security: "🔐", other: "✏️" }[
        cat
      ] || "✏️";
    var beforeHtml =
      '<span style="background:#3d1a1a;color:#ffb0b8;padding:3px 10px;border-radius:6px;font-size:12px;text-decoration:line-through;word-break:break-word;">' +
      esc(c.before) +
      "</span>";
    var afterHtml =
      '<span style="background:#1a3d2a;color:#a8f0c5;padding:3px 10px;border-radius:6px;font-size:12px;word-break:break-word;">' +
      esc(c.after) +
      "</span>";

    html +=
      '<div style="display:grid;grid-template-columns:44px 1fr auto;gap:12px;align-items:flex-start;padding:12px 14px;background:#0d1a13;border:1px solid var(--line);border-radius:10px;">';
    html +=
      '  <div style="width:44px;height:44px;border-radius:10px;background:#0a1710;border:1px solid var(--line);display:grid;place-items:center;font-size:20px;">' +
      ico +
      "</div>";
    html += '  <div style="min-width:0;">';
    html +=
      '    <div style="font-size:12px;color:var(--muted);font-weight:800;text-transform:uppercase;letter-spacing:.05em;margin-bottom:4px;">' +
      esc(c.fieldLabel) +
      "</div>";
    html +=
      '    <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;font-size:13px;">' +
      beforeHtml +
      '<span style="color:var(--muted);font-weight:900;">→</span>' +
      afterHtml +
      "</div>";
    html +=
      '    <div style="font-size:11px;color:var(--muted);margin-top:5px;">👤 ' +
      esc(c.by) +
      "</div>";
    html += "  </div>";
    html +=
      '  <div style="font-size:11px;color:var(--muted);white-space:nowrap;text-align:right;">' +
      new Date(c.at).toLocaleString("ru-RU") +
      "</div>";
    html += "</div>";
  });
  html += "</div>";

  return html;
}

function renderAchievementsTab(u) {
  if (!u) return '<p class="muted">Нет данных</p>';

  var list = [];
  try {
    list = getUserAchievements(u);
  } catch (e) {
    console.error("[achievements] getUserAchievements failed:", e);
    return (
      '<div class="empty" data-icon="⚠️"><b>Не удалось загрузить достижения</b><small>Ошибка: ' +
      esc(e && e.message ? e.message : String(e)) +
      "</small></div>"
    );
  }

  var claimedCount = list.filter(function (a) {
    return a.claimed;
  }).length;
  var readyCount = list.filter(function (a) {
    return a.ready;
  }).length;
  var isMe = u.id === currentId;
  var totalDefs = Array.isArray(ACHIEVEMENTS) ? ACHIEVEMENTS.length : 0;

  var html = "";
  try {
    html +=
      '<div class="profile-section-title">🏆 Достижения (' +
      claimedCount +
      "/" +
      totalDefs +
      ")</div>";
    html +=
      '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px;align-items:center;">';
    html +=
      '<span class="badge" style="background:#1a3d2a;color:#83e6ad;">✅ Получено: ' +
      claimedCount +
      "</span>";
    html +=
      '<span class="badge" style="background:#3d3420;color:#e5c35c;">🎁 Готово к получению: ' +
      readyCount +
      "</span>";
    if (isMe && readyCount > 0) {
      html +=
        '<button class="btn small primary2" onclick="claimAllAchievements(\'' +
        u.id +
        "')\">🏆 Забрать все (" +
        readyCount +
        ")</button>";
    }
    html += "</div>";

    if (!list.length) {
      html +=
        '<div class="empty" data-icon="🏆"><b>Нет достижений</b><small>Список достижений пуст или ещё не инициализирован</small></div>';
      return html;
    }

    var CATS =
      typeof ACHIEVEMENT_CATS === "object" && ACHIEVEMENT_CATS
        ? ACHIEVEMENT_CATS
        : {};
    var catKeys = Object.keys(CATS);
    if (!catKeys.length) {
      catKeys = ["_all"];
      CATS._all = { name: "🏆 Все", color: "#39c982" };
    }

    catKeys.forEach(function (catKey) {
      var cat = CATS[catKey] || { name: catKey, color: "#39c982" };
      var catList =
        catKey === "_all"
          ? list
          : list.filter(function (a) {
              return a.def && a.def.cat === catKey;
            });
      if (!catList.length) return;

      var catClaimed = catList.filter(function (a) {
        return a.claimed;
      }).length;
      html +=
        '<div class="profile-section-title" style="margin-top:18px;">' +
        esc(cat.name) +
        " (" +
        catClaimed +
        "/" +
        catList.length +
        ")</div>";
      html +=
        '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px;">';

      catList.forEach(function (a) {
        try {
          var def = a.def || {};
          var goal =
            typeof def.goal === "number" && def.goal > 0 ? def.goal : 1;
          var progShown = Math.min(a.progress, goal);
          var pct = Math.max(
            0,
            Math.min(100, Math.round((a.progress / goal) * 100)),
          );
          var barColor = a.claimed
            ? "#39c982"
            : a.ready
              ? "#e5c35c"
              : "#73b7ff";
          var borderColor = a.claimed
            ? "#39c98266"
            : a.ready
              ? "#e5c35c66"
              : "var(--line)";
          var statusLabel = a.claimed
            ? "✅ Получено"
            : a.ready
              ? "🎁 Забрать"
              : "⏳ " + progShown + "/" + goal;
          var statusColor = a.claimed
            ? "#83e6ad"
            : a.ready
              ? "#e5c35c"
              : "#73b7ff";
          var rewardVal = typeof def.reward === "number" ? def.reward : 0;

          html +=
            '<div style="background:linear-gradient(160deg,#0f1e16,#0a1710);border:1px solid ' +
            borderColor +
            ";border-radius:14px;padding:14px;display:flex;flex-direction:column;gap:8px;" +
            (a.claimed ? "opacity:.85;" : "") +
            '">';
          html += '<div style="display:flex;align-items:flex-start;gap:10px;">';
          html +=
            '<div style="font-size:32px;line-height:1;flex-shrink:0;">' +
            (def.icon || "🏆") +
            "</div>";
          html += '<div style="flex:1;min-width:0;">';
          html +=
            '<div style="font-weight:800;font-size:14px;line-height:1.2;">' +
            esc(def.name || "—") +
            "</div>";
          html +=
            '<div class="muted" style="font-size:11.5px;margin-top:3px;line-height:1.35;">' +
            esc(def.desc || "") +
            "</div>";
          html += "</div>";
          html += "</div>";

          html +=
            '<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:11px;">';
          html +=
            '<span class="muted">Прогресс: <b style="color:' +
            barColor +
            ';">' +
            progShown +
            "/" +
            goal +
            "</b></span>";
          html +=
            '<span style="color:' +
            statusColor +
            ';font-weight:800;">' +
            statusLabel +
            "</span>";
          html += "</div>";

          html +=
            '<div style="height:8px;background:#0a1710;border:1px solid var(--line);border-radius:5px;overflow:hidden;">';
          html +=
            '<div style="width:' +
            pct +
            "%;height:100%;background:" +
            barColor +
            ';border-radius:5px;transition:width .4s;"></div>';
          html += "</div>";

          html +=
            '<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;">';
          html +=
            '<span class="badge" style="background:#3d3420;color:var(--gold);font-size:10px;">🪙 ' +
            rewardVal +
            "</span>";
          if (a.ready && isMe) {
            html +=
              '<button class="btn small primary2" onclick="claimAchievement(\'' +
              esc(u.id) +
              "','" +
              esc(def.id) +
              "')\">🎁 Забрать</button>";
          }
          html += "</div>";

          html += "</div>";
        } catch (eAch) {
          console.error(
            "[achievements] render failed for",
            a && a.def && a.def.id,
            eAch,
          );
          html +=
            '<div style="background:#2a141a;border:1px solid #5a3039;border-radius:14px;padding:12px;color:#ffd9df;font-size:12px;">⚠️ Ошибка отрисовки «' +
            esc((a && a.def && a.def.name) || "—") +
            "»</div>";
        }
      });

      html += "</div>";
    });
  } catch (e) {
    console.error("[achievements] renderAchievementsTab failed:", e);
    return (
      '<div class="empty" data-icon="⚠️"><b>Ошибка рендера достижений</b><small>' +
      esc(e && e.message ? e.message : String(e)) +
      "</small></div>"
    );
  }

  return html;
}

function renderTrustSettings() {
  var el = document.getElementById("trustSettingsContainer");
  if (!el) return;
  var u = current();
  if (!u || !can(u, "manage_permissions")) {
    el.innerHTML = '<p class="muted">Нет прав</p>';
    return;
  }
  var ts = trustSettings;
  var html = "";
  html +=
    '<div class="notes-section" style="margin-bottom:14px;"><b>🎖️ Основные настройки</b>';
  html += '<div class="grid" style="margin-top:10px;">';
  html +=
    '<div class="field"><label>Система включена</label><select id="tsEnabled"><option value="1" ' +
    (ts.enabled ? "selected" : "") +
    '>Да</option><option value="0" ' +
    (!ts.enabled ? "selected" : "") +
    ">Нет</option></select></div>";
  html +=
    '<div class="field"><label>Стартовое значение (0-100)</label><input id="tsStart" type="number" min="0" max="100" value="' +
    ts.start +
    '"></div>';
  html +=
    '<div class="field"><label>Кулдаун между изменениями (мин)</label><input id="tsCooldown" type="number" min="0" value="' +
    (ts.cooldownMinutes || 0) +
    '"><div class="muted" style="font-size:10px;margin-top:3px;">0 = без ограничений</div></div>';
  html += "</div></div>";

  html +=
    '<div class="notes-section" style="margin-bottom:14px;"><b>❄️ Авто-заморозка</b>';
  html += '<div class="grid" style="margin-top:10px;">';
  html +=
    '<div class="field"><label>Включена</label><select id="tsAutoFreeze"><option value="1" ' +
    (ts.autoFreeze ? "selected" : "") +
    '>Да</option><option value="0" ' +
    (!ts.autoFreeze ? "selected" : "") +
    ">Нет</option></select></div>";
  html +=
    '<div class="field"><label>Порог заморозки</label><input id="tsFreezeThresh" type="number" min="0" max="99" value="' +
    ts.autoFreezeThreshold +
    '"><div class="muted" style="font-size:10px;margin-top:3px;">Если trust падает ниже — заморозка</div></div>';
  html += "</div></div>";

  html +=
    '<div class="notes-section" style="margin-bottom:14px;"><b>⏳ Авто-снижение (decay)</b>';
  html += '<div class="grid" style="margin-top:10px;">';
  html +=
    '<div class="field"><label>Включено</label><select id="tsDecayEnabled"><option value="1" ' +
    (ts.decayEnabled ? "selected" : "") +
    '>Да</option><option value="0" ' +
    (!ts.decayEnabled ? "selected" : "") +
    ">Нет</option></select></div>";
  html +=
    '<div class="field"><label>Каждые N дней</label><input id="tsDecayDays" type="number" min="1" value="' +
    (ts.decayDays || 7) +
    '"></div>';
  html +=
    '<div class="field"><label>Снижать на</label><input id="tsDecayAmount" type="number" min="1" value="' +
    (ts.decayAmount || 1) +
    '"></div>';
  html +=
    '</div><div class="muted" style="font-size:11px;margin-top:6px;">Если сотрудник не получает событий +trust N дней — рейтинг снижается.</div></div>';

  html +=
    '<div class="notes-section"><b>⚖ Веса событий</b><div class="muted" style="font-size:11px;margin-bottom:10px;">Сколько trust прибавляется/убавляется за каждое событие.</div>';
  html += '<div class="grid">';
  var weightLabels = {
    taskOnTime: "📋 Задача выполнена в срок",
    transferSent: "💸 Отправлен перевод",
    reactionGiven: "👍 Поставлена реакция",
    twoFAEnabled: "🔐 Включена 2FA",
    avatarUploaded: "📷 Загружен аватар",
    freeze: "❄️ Заморозка",
    cancelBattle: "⚔️ Отменён кейс-баттл",
    warn: "⚠️ Выговор",
    kick: "🚫 Кик",
  };
  Object.keys(ts.weights || {}).forEach(function (k) {
    html +=
      '<div class="field"><label>' +
      esc(weightLabels[k] || k) +
      '</label><input type="number" step="0.5" data-weight="' +
      esc(k) +
      '" value="' +
      (ts.weights[k] || 0) +
      '"></div>';
  });
  html += "</div></div>";

  html +=
    '<div class="modal-actions"><button class="btn primary2" onclick="saveTrustSettingsFromUI()">💾 Сохранить настройки доверия</button></div>';
  el.innerHTML = html;
}

function saveTrustSettingsFromUI() {
  if (!checkBlocked()) return;
  var admin = current();
  if (!admin || !can(admin, "manage_permissions")) return;
  trustSettings.enabled = document.getElementById("tsEnabled").value === "1";
  trustSettings.start = Math.max(
    0,
    Math.min(100, parseInt(document.getElementById("tsStart").value, 10) || 50),
  );
  trustSettings.cooldownMinutes = Math.max(
    0,
    parseInt(document.getElementById("tsCooldown").value, 10) || 0,
  );
  trustSettings.autoFreeze =
    document.getElementById("tsAutoFreeze").value === "1";
  trustSettings.autoFreezeThreshold = Math.max(
    0,
    Math.min(
      99,
      parseInt(document.getElementById("tsFreezeThresh").value, 10) || 20,
    ),
  );
  trustSettings.decayEnabled =
    document.getElementById("tsDecayEnabled").value === "1";
  trustSettings.decayDays = Math.max(
    1,
    parseInt(document.getElementById("tsDecayDays").value, 10) || 7,
  );
  trustSettings.decayAmount = Math.max(
    1,
    parseInt(document.getElementById("tsDecayAmount").value, 10) || 1,
  );
  document.querySelectorAll("[data-weight]").forEach(function (inp) {
    var k = inp.getAttribute("data-weight");
    var v = parseFloat(inp.value);
    if (!isNaN(v)) trustSettings.weights[k] = v;
  });
  saveTrustSettings();
  addLog("Настройки доверия изменены", admin.name);
  toast("✅ Настройки доверия сохранены");
}
/* удалено: дубликат saveTrustSettingsFromUI — полная версия определена выше */

