function renderPromotions() {
  var el = document.getElementById("sectionPromotions");
  if (!el) return;
  var user = current();
  if (!user) return;
  var existing = document.getElementById("myPromotionRequests");
  if (!existing) {
    var wrapper = document.createElement("section");
    wrapper.className = "card";
    wrapper.style.marginTop = "16px";
    wrapper.innerHTML =
      '<div class="toolbar"><h3 style="margin:0;">📜 Мои запросы</h3></div><div style="padding:16px;" id="myPromotionRequests"></div>';
    el.appendChild(wrapper);
    existing = document.getElementById("myPromotionRequests");
  }
  var myReqs = promotionRequests
    .filter(function (r) {
      return r.userId === user.id;
    })
    .slice()
    .reverse();
  if (!myReqs.length) {
    existing.innerHTML =
      '<div class="empty" data-icon="📈" style="margin-top:20px;"><b>Нет запросов</b><small>У вас пока нет активных запросов на повышение.</small></div>';
    return;
  }
  existing.innerHTML = myReqs
    .map(function (r) {
      var cls =
        r.status === "pending"
          ? "pending"
          : r.status === "approved"
            ? "approved"
            : "rejected";
      var statusLabel =
        r.status === "pending"
          ? "⏳ На рассмотрении"
          : r.status === "approved"
            ? "✅ Одобрено"
            : "❌ Отклонено";
      var rejectLine = r.rejectReason
        ? '<div class="pr-reason" style="background:#2a141a;color:#ffd9df;margin-top:6px;">Причина отказа: ' +
          esc(r.rejectReason) +
          "</div>"
        : "";
      return (
        '<div class="promo-request-card ' +
        cls +
        '">' +
        '<div class="pr-head">' +
        "<div>" +
        '<div class="pr-title">' +
        esc(r.currentRole || "—") +
        ' <span class="pr-arrow">→</span> ' +
        esc(r.requestedRole || "—") +
        "</div>" +
        '<div class="pr-meta"><span>🕐 ' +
        new Date(r.createdAt).toLocaleString() +
        "</span><span>" +
        statusLabel +
        "</span></div>" +
        "</div>" +
        "</div>" +
        '<div class="pr-reason">' +
        esc(r.reason || "") +
        "</div>" +
        rejectLine +
        "</div>"
      );
    })
    .join("");
}
