function openManageKeysModal(userId) {
  if (!checkBlocked()) return;
  var admin = current();
  if (!admin) return;
  if (!can(admin, "manage_shop")) {
    toast("❌ Нет прав");
    return;
  }
  var u = users.find(function (x) {
    return x.id === userId;
  });
  if (!u) {
    toast("❌ Сотрудник не найден");
    return;
  }

  var totalKeys = LOOTBOX_KEYS.reduce(function (s, k) {
    return s + getUserKeyCount(u, k.id);
  }, 0);

  var html = "<h2>🔑 Управление ключами</h2>";
  html +=
    '<p class="muted">Сотрудник: <b>' +
    esc(u.name) +
    '</b> · Всего ключей: <b style="color:var(--gold);">' +
    totalKeys +
    "</b></p>";

  html +=
    '<div style="display:flex;gap:6px;margin-bottom:14px;flex-wrap:wrap;">';
  html +=
    '<button type="button" class="btn small" onclick="document.querySelectorAll(\'.manage-key-input\').forEach(function(i){i.value=(parseInt(i.value,10)||0)+1;})">+1 всем</button>';
  html +=
    '<button type="button" class="btn small" onclick="document.querySelectorAll(\'.manage-key-input\').forEach(function(i){i.value=(parseInt(i.value,10)||0)+5;})">+5 всем</button>';
  html +=
    '<button type="button" class="btn small" onclick="document.querySelectorAll(\'.manage-key-input\').forEach(function(i){i.value=(parseInt(i.value,10)||0)+10;})">+10 всем</button>';
  html +=
    '<button type="button" class="btn small danger" onclick="document.querySelectorAll(\'.manage-key-input\').forEach(function(i){i.value=0;})">✖ Забрать все</button>';
  html +=
    '<button type="button" class="btn small" onclick="document.querySelectorAll(\'.manage-key-input\').forEach(function(i){i.value=i.dataset.current||0;})">↺ Сброс</button>';
  html += "</div>";

  html += '<div class="grid" style="gap:8px;">';
  LOOTBOX_KEYS.forEach(function (k) {
    var have = getUserKeyCount(u, k.id);
    html +=
      '<div style="display:flex;gap:6px;align-items:center;background:#0008;border:1px solid ' +
      (have > 0 ? k.color + "55" : "var(--line)") +
      ";border-radius:10px;padding:8px 10px;" +
      (have === 0 ? "opacity:.7;" : "") +
      '">';
    html +=
      '<span style="font-size:22px;filter:drop-shadow(0 0 6px ' +
      k.color +
      '88);flex-shrink:0;">' +
      k.icon +
      "</span>";
    html +=
      '<span style="font-size:12px;font-weight:800;flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="' +
      esc(k.name) +
      '">' +
      esc(k.name) +
      "</span>";
    html +=
      '<input type="number" min="0" value="' +
      have +
      '" data-current="' +
      have +
      '" data-keyid="' +
      k.id +
      '" class="manage-key-input" style="width:80px;text-align:center;font-weight:800;padding:6px 8px;">';
    html += "</div>";
  });
  html += "</div>";
  html +=
    '<div class="muted" style="font-size:11px;margin-top:10px;">Введите <b>итоговое количество</b> ключей. <b>0</b> — забрать все ключи этого типа.</div>';
  html +=
    '<div class="modal-actions"><button class="btn" onclick="closeModal()">Отмена</button><button class="btn primary2" onclick="applyManageKeys(\'' +
    userId +
    "')\">💾 Сохранить</button></div>";

  document.getElementById("modalContent").innerHTML = html;
  document.getElementById("modal").classList.remove("hidden");
}

function applyManageKeys(userId) {
  if (!checkBlocked() || !rateLimit("giveItem")) return;
  var admin = current();
  if (!can(admin, "manage_shop")) {
    toast("❌ Нет прав");
    return;
  }
  var u = users.find(function (x) {
    return x.id === userId;
  });
  if (!u) {
    toast("❌ Не найден");
    return;
  }

  var changes = [];
  document.querySelectorAll(".manage-key-input").forEach(function (inp) {
    var keyId = inp.getAttribute("data-keyid");
    if (!keyId) return;
    var kd = getKeyDef(keyId);
    if (!kd) return;
    var have = getUserKeyCount(u, keyId);
    var wanted = Math.max(0, parseInt(inp.value, 10) || 0);
    var _capKeys = getLimit("inventory", "maxKeysPerType", u);
    if (wanted > _capKeys) {
      toast("⚠️ " + getKeyName(keyId) + ": максимум " + _capKeys, "warn");
      wanted = _capKeys;
    }
    if (wanted === have) return;
    if (!u.keys) u.keys = {};
    if (wanted === 0) {
      delete u.keys[keyId];
    } else {
      u.keys[keyId] = wanted;
    }
    var diff = wanted - have;
    changes.push(kd.icon + " " + kd.name + ": " + (diff > 0 ? "+" : "") + diff);
  });

  if (!changes.length) {
    toast("⚠️ Ничего не изменено", "warn");
    closeModal();
    return;
  }
  saveUsers();
  var summary = summarizeList(changes, 4);
  addNotification(u.id, "🔑 Изменены ключи: " + summary);
  addLog("Изменение ключей", u.name + " · " + summary);
  playSound("gift");
  toast("🔑 Обновлено: " + summary, "success");
  closeModal();
  try {
    renderInvEditor();
  } catch (e) {}
  try {
    renderLootboxes();
  } catch (e) {}
  try {
    renderStaff();
  } catch (e) {}
  if (profileUserId === u.id)
    try {
      renderProfileTab(u.id);
    } catch (e) {}
}
