async function applyTakeItems(userId) {
  if (!checkBlocked() || !rateLimit("takeItem")) return;
  var admin = current();
  if (!can(admin, "manage_shop")) {
    toast("❌ Нет прав");
    return;
  }
  var u = users.find(function (x) {
    return x.id === userId;
  });
  if (!u) return;

  /* Сначала собираем предполагаемые изменения БЕЗ мутации */
  var pendingKeyChanges = [];
  var keysChangedLabels = [];
  var keysRemovedTotal = 0;
  document.querySelectorAll(".take-key-input").forEach(function (inp) {
    var keyId = inp.getAttribute("data-keyid");
    if (!keyId) return;
    var kd = getKeyDef(keyId);
    if (!kd) return;
    var currentQty = getUserKeyCount(u, keyId);
    var wanted = Math.max(0, parseInt(inp.value, 10) || 0);
    if (wanted >= currentQty) return;
    pendingKeyChanges.push({
      keyId: keyId,
      kd: kd,
      wanted: wanted,
      currentQty: currentQty,
    });
    var diff = currentQty - wanted;
    keysRemovedTotal += diff;
    keysChangedLabels.push("−" + diff + " " + kd.icon + " " + kd.name);
  });

  var ids = Array.from(document.querySelectorAll(".take-item-cb:checked")).map(
    function (c) {
      return c.value;
    },
  );
  var note = (document.getElementById("takeItemsNote").value || "").trim();

  if (!ids.length && !pendingKeyChanges.length) {
    toast("⚠️ Ничего не выбрано", "warn");
    return;
  }

  var confirmLines = [];
  if (ids.length) confirmLines.push("Предметов: " + ids.length);
  if (pendingKeyChanges.length)
    confirmLines.push("Ключей к изъятию: " + keysRemovedTotal);
  var _takeMsg = "Сотрудник: " + u.name + "\n" + confirmLines.join("\n");
  if (note) _takeMsg += "\nКомментарий: " + note;
  var _takeOk = await confirmCritical({
    title: "✂️ Применить изъятие?",
    message: _takeMsg,
    danger: true,
    okText: "✂️ Применить",
  });
  if (!_takeOk) return;

  /* Только теперь мутируем */
  var keysChanged = keysChangedLabels;
  pendingKeyChanges.forEach(function (ch) {
    if (!u.keys) u.keys = {};
    if (ch.wanted === 0) {
      delete u.keys[ch.keyId];
    } else {
      u.keys[ch.keyId] = ch.wanted;
    }
  });

  var removed = 0;
  var removedEffects = [];
  ids.forEach(function (invId) {
    var inv = (u.inventory || []).find(function (x) {
      return x.id === invId;
    });
    if (!inv) return;
    if (inv.used && inv.effect) removedEffects.push(inv.effect);
    if (inv.source !== "gift" && inv.source !== "admin") {
      var p = (u.purchases || []).find(function (x) {
        return x.itemId === inv.itemId && !x.sold;
      });
      if (p) {
        p.sold = true;
        p.soldAt = new Date().toISOString();
        p.soldBy = admin.name;
      }
    }
    removed++;
  });
  if (removed)
    u.inventory = (u.inventory || []).filter(function (x) {
      return ids.indexOf(x.id) === -1;
    });
  removedEffects.forEach(function (eff) {
    try {
      revokeEffectOnSell(u, eff);
    } catch (e) {}
  });

  saveUsers();

  var parts = [];
  if (removed) parts.push("предметов: " + removed);
  if (keysRemovedTotal) parts.push("ключей: " + keysRemovedTotal);
  var summary = parts.join(" · ") + (note ? " · " + note : "");

  if (removed || keysChanged.length) {
    addNotification(u.id, "✂️ Изъято — " + summary);
    addLog("Изъятие", u.name + " · " + summary);
    playSound("sell");
    toast("✂️ Изъято — " + summary, "success");
  }

  closeModal();
  try {
    renderInventory();
  } catch (e) {}
  if (profileUserId === u.id)
    try {
      renderProfileTab(u.id);
    } catch (e) {}
  try {
    renderStaff();
  } catch (e) {}
  try {
    renderWheel();
  } catch (e) {}
  try {
    renderSfBalances();
  } catch (e) {}
  try {
    renderInvEditor();
  } catch (e) {}
  try {
    renderLootboxes();
  } catch (e) {}
}
async function takeAllItems(userId) {
  if (!checkBlocked()) return;
  var admin = current();
  if (!can(admin, "manage_shop")) {
    toast("❌ Нет прав");
    return;
  }
  var u = users.find(function (x) {
    return x.id === userId;
  });
  if (!u) return;
  var inv = u.inventory || [];
  if (!inv.length) {
    toast("Инвентарь пуст");
    return;
  }
  var _takeAllOk = await confirmCritical({
    title: "🗑 Очистить инвентарь?",
    message:
      "У " +
      u.name +
      " будут удалены все " +
      inv.length +
      " предметов.\nДействие необратимо.",
    danger: true,
    okText: "🗑 Очистить",
  });
  if (!_takeAllOk) return;
  var count = inv.length;
  // FIX: собираем itemId всех изымаемых предметов, чтобы пометить связанные покупки
  var removedItemIds = {};
  var removedEffects = [];
  inv.forEach(function (it) {
    if (it.itemId) removedItemIds[it.itemId] = true;
    if (it.used && it.effect) removedEffects.push(it.effect);
  });
  u.inventory = [];
  removedEffects.forEach(function (eff) {
    try {
      revokeEffectOnSell(u, eff);
    } catch (e) {}
  });
  // FIX: помечаем все связанные purchases как изъятые, чтобы они не висели в «Моих покупках»
  if (Array.isArray(u.purchases)) {
    u.purchases.forEach(function (p) {
      if (p && !p.sold && p.itemId && removedItemIds[p.itemId]) {
        p.sold = true;
        p.soldAt = new Date().toISOString();
        p.soldBy = admin.name;
        p.soldReason = "admin_take_all";
      }
    });
  }
  saveUsers();
  addNotification(u.id, "🗑 Инвентарь очищен (" + count + " шт.)");
  addLog("Очистка инвентаря", u.name + " · " + count + " шт.");
  playSound("sell");
  toast("🗑 Инвентарь очищен: " + count + " предметов");
  closeModal();
  try {
    renderInventory();
  } catch (e) {}
  if (profileUserId === u.id)
    try {
      renderProfileTab(u.id);
    } catch (e) {}
  try {
    renderStaff();
  } catch (e) {}
  try {
    renderWheel();
  } catch (e) {}
  try {
    renderSfBalances();
  } catch (e) {}
  try {
    renderInvEditor();
  } catch (e) {}
  try {
    renderShop();
  } catch (e) {}
}
function takeKeysFromUser(userId, keyId) {
  if (!checkBlocked()) return;
  if (!can(current(), "manage_shop")) {
    toast("❌ Нет прав");
    return;
  }
  var u = users.find(function (x) {
    return x.id === userId;
  });
  if (!u) return;
  var kd = getKeyDef(keyId);
  if (!kd) return;
  var had = getUserKeyCount(u, keyId);
  if (!had) {
    toast("Уже нет");
    return;
  }
  if (!confirm("Забрать все " + kd.icon + " " + kd.name + " (×" + had + ")?"))
    return;
  if (!u.keys) u.keys = {};
  delete u.keys[keyId];
  saveUsers();
  addNotification(u.id, "🗑 Изъято ключей: " + kd.icon + " ×" + had);
  addLog("Изъятие ключей", u.name + " · " + had + " × " + kd.name);
  toast("🗑 Изъято " + had + " × " + kd.name);
  openTakeItemsModal(userId);
  try {
    renderLootboxes();
  } catch (e) {}
}
/* ============ РЕДАКТОР ИНВЕНТАРЯ (админ-панель) ============ */
function renderInvEditor() {
  var el = document.getElementById("invEditorList");
  if (!el) return;
  var user = current();
  if (!user) return;
  if (!can(user, "manage_shop")) {
    el.innerHTML =
      '<div class="empty" data-icon="🔒"><b>Нет доступа</b><small>Требуется разрешение «manage_shop»</small></div>';
    return;
  }
  var searchEl = document.getElementById("invEditorSearch");
  var q = searchEl ? (searchEl.value || "").toLowerCase().trim() : "";
  var list = users.slice();
  if (q)
    list = list.filter(function (u) {
      return (
        (u.name || "").toLowerCase().indexOf(q) !== -1 ||
        (u.role || "").toLowerCase().indexOf(q) !== -1 ||
        (u.login || "").toLowerCase().indexOf(q) !== -1
      );
    });
  list.sort(function (a, b) {
    return (a.name || "").localeCompare(b.name || "", "ru");
  });

  var listIds = {};
  list.forEach(function (x) {
    listIds[x.id] = 1;
  });
  Array.from(_invEditorSelected).forEach(function (id) {
    if (!listIds[id]) _invEditorSelected.delete(id);
  });

  var totalItems = users.reduce(function (s, u) {
    return s + (u.inventory || []).length;
  }, 0);
  var totalActive = users.reduce(function (s, u) {
    return (
      s +
      (u.inventory || []).filter(function (x) {
        return !x.used;
      }).length
    );
  }, 0);
  var badge = document.getElementById("invEditorStatsBadge");
  if (badge)
    badge.textContent =
      totalItems + " предметов · " + totalActive + " активных";

  if (!list.length) {
    el.innerHTML =
      '<div class="empty" data-icon="🔍"><b>Никого не найдено</b><small>Попробуйте изменить поисковый запрос</small></div>';
    return;
  }

  var html = "";

  html +=
    '<div class="sm-bulk-bar" id="invEditorBulkBar" style="margin-bottom:14px;">';
  html +=
    '<span>Выбрано: <b id="invEditorSelectedCount">' +
    _invEditorSelected.size +
    "</b></span>";
  html +=
    '<button class="btn small" onclick="selectAllInvEditor()">✅ Выбрать всех в списке</button>';
  html +=
    '<button class="btn small" id="invEditorDeselectBtn" onclick="clearInvEditorSelection()">✖ Снять выбор</button>';
  html +=
    '<button class="btn small danger" id="invEditorClearSelectedBtn" onclick="clearSelectedInventories()">🧹 Очистить БД выбранных</button>';
  html += "</div>";

  html +=
    '<div class="stats" style="grid-template-columns:repeat(3,1fr);margin-bottom:16px;">';
  html +=
    '<div class="stat"><b>' +
    users.length +
    "</b><span>сотрудников</span></div>";
  html +=
    '<div class="stat"><b>' +
    totalItems +
    "</b><span>предметов всего</span></div>";
  html +=
    '<div class="stat"><b style="color:var(--accent);">' +
    totalActive +
    "</b><span>активных</span></div>";
  html += "</div>";
  html += '<div class="shop-grid" style="padding:0;">';
  list.forEach(function (u) {
    var inv = u.inventory || [];
    var activeCount = inv.filter(function (x) {
      return !x.used;
    }).length;
    var usedCount = inv.filter(function (x) {
      return x.used;
    }).length;
    var isMe = u.id === currentId;
    var isSelected = _invEditorSelected.has(u.id);
    var avHTML =
      '<span class="' +
      withFrame(u, "mini-avatar") +
      '" style="width:44px;height:44px;font-size:16px;">' +
      avatarContent(u) +
      "</span>";
    var statusBadge = isFrozen(u)
      ? '<span class="badge badge-frozen">❄️</span>'
      : isOnVacation(u)
        ? '<span class="badge badge-vacation">🌴</span>'
        : '<span class="badge badge-active">🟢</span>';
    var hasSomething =
      inv.length > 0 ||
      (u.purchases || []).length > 0 ||
      (u.freeSpins || 0) > 0;

    html +=
      '<div class="shop-item" style="cursor:default;gap:12px;' +
      (isSelected
        ? "border-color:var(--accent);box-shadow:0 0 0 2px #39c98244;"
        : "") +
      '">';

    html += '<div style="display:flex;gap:10px;align-items:center;">';
    html +=
      '<input type="checkbox" ' +
      (isSelected ? "checked" : "") +
      " onchange=\"toggleInvEditorSelection('" +
      u.id +
      '\',this.checked)" style="width:18px;height:18px;accent-color:var(--accent);cursor:pointer;flex-shrink:0;" title="Выбрать для массовой очистки">';
    html += avHTML;
    html +=
      '<div style="flex:1;min-width:0;"><div style="font-weight:800;font-size:15px;' +
      (safeColor(u.nickColor) ? "color:" + safeColor(u.nickColor) + ";" : "") +
      '">' +
      esc(u.name) +
      (isMe ? ' <span class="muted" style="font-size:11px;">(вы)</span>' : "") +
      "</div><div>" +
      roleLabelHtml(u.role, false) +
      "</div></div>";
    html += statusBadge;
    html += "</div>";

    html +=
      '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;">';
    html +=
      '<div style="background:#00000055;border:1px solid #ffffff0d;border-radius:10px;padding:8px 6px;text-align:center;"><div style="font-size:10px;color:var(--muted);text-transform:uppercase;">📦 Всего</div><div style="font-weight:900;font-size:16px;">' +
      inv.length +
      "</div></div>";
    html +=
      '<div style="background:#00000055;border:1px solid #ffffff0d;border-radius:10px;padding:8px 6px;text-align:center;"><div style="font-size:10px;color:var(--muted);text-transform:uppercase;">⚡ Акт.</div><div style="font-weight:900;font-size:16px;color:var(--accent);">' +
      activeCount +
      "</div></div>";
    html +=
      '<div style="background:#00000055;border:1px solid #ffffff0d;border-radius:10px;padding:8px 6px;text-align:center;"><div style="font-size:10px;color:var(--muted);text-transform:uppercase;">✅ Исп.</div><div style="font-weight:900;font-size:16px;color:var(--muted);">' +
      usedCount +
      "</div></div>";
    html += "</div>";

    html += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;">';
    html +=
      '<button class="btn primary2 small" onclick="openGiveItemModal(\'' +
      u.id +
      "')\">＋ Выдать</button>";
    html +=
      '<button class="btn danger small" onclick="openTakeItemsModal(\'' +
      u.id +
      "')\" " +
      (inv.length ? "" : 'disabled style="opacity:.5;"') +
      ">✕ Изъять</button>";
    html += "</div>";
    html +=
      '<button class="btn small" style="width:100%;background:linear-gradient(135deg,#3d3420,#2a2418);border-color:#5a4e3a;color:var(--gold);font-weight:800;" onclick="openManageKeysModal(\'' +
      u.id +
      "')\">🔑 Управление ключами</button>";

    html +=
      '<button class="btn small danger" style="width:100%;" ' +
      (hasSomething ? "" : 'disabled style="opacity:.5;"') +
      " onclick=\"clearUserInventoryDatabase('" +
      u.id +
      "')\">🧹 Очистить БД инвентаря</button>";

    html +=
      '<button class="btn small" style="width:100%;" onclick="openProfileInTab(\'' +
      u.id +
      "')\">👤 Профиль</button>";
    html += "</div>";
  });
  html += "</div>";
  el.innerHTML = html;
  updateInvEditorBulkBar();
}
/* ============ ВЫБОР ПОЛЬЗОВАТЕЛЕЙ В РЕДАКТОРЕ ИНВЕНТАРЯ ============ */
function toggleInvEditorSelection(userId, checked) {
  if (checked) _invEditorSelected.add(userId);
  else _invEditorSelected.delete(userId);
  updateInvEditorBulkBar();
  var cb = document.querySelector(
    '#invEditorList input[onchange*="' + userId + '"]',
  );
  if (cb) {
    var card = cb.closest(".shop-item");
    if (card) {
      card.style.borderColor = checked ? "var(--accent)" : "";
      card.style.boxShadow = checked ? "0 0 0 2px #39c98244" : "";
    }
  }
}
function selectAllInvEditor() {
  var searchEl = document.getElementById("invEditorSearch");
  var q = searchEl ? (searchEl.value || "").toLowerCase().trim() : "";
  users.forEach(function (u) {
    if (q) {
      var s = (
        (u.name || "") +
        " " +
        (u.role || "") +
        " " +
        (u.login || "")
      ).toLowerCase();
      if (s.indexOf(q) === -1) return;
    }
    _invEditorSelected.add(u.id);
  });
  renderInvEditor();
}
function clearInvEditorSelection() {
  _invEditorSelected.clear();
  renderInvEditor();
}
function updateInvEditorBulkBar() {
  var cnt = document.getElementById("invEditorSelectedCount");
  if (cnt) cnt.textContent = _invEditorSelected.size;
  var has = _invEditorSelected.size > 0;
  var clearBtn = document.getElementById("invEditorClearSelectedBtn");
  if (clearBtn) {
    clearBtn.disabled = !has;
    clearBtn.style.opacity = has ? "1" : ".5";
  }
  var deselBtn = document.getElementById("invEditorDeselectBtn");
  if (deselBtn) {
    deselBtn.disabled = !has;
    deselBtn.style.opacity = has ? "1" : ".5";
  }
}

/* ============ ОЧИСТКА БД ИНВЕНТАРЯ ============ */
function clearInventoryDataForUser(u, admin) {
  if (!u) return 0;
  var hadItems = (u.inventory || []).length;
  if (Array.isArray(u.purchases)) {
    u.purchases.forEach(function (p) {
      if (p && !p.sold) {
        p.sold = true;
        p.soldAt = new Date().toISOString();
        p.soldBy = (admin && admin.name) || "Система";
        p.soldReason = "admin_wipe";
      }
    });
  }
  u.inventory = [];
  u.freeSpins = 0;
  u.keys = {};
  u.buffs = {};
  u.multiOpen = { x3: false, x5: false, x10: false };
  u.canNickColor = false;
  u.canProfileAnim = false;
  u.canAdvancedStats = false;
  u.canProfileBg = false;
  u.nickColor = "";
  u.profileAnim = "none";
  u.profileBg = "";
  u.frame = "";
  delete u.theme;
  u.customColors = Object.assign({}, THEMES.dark);
  u.lbAnimation = "classic";
  u.ownedAnimations = ["classic"];
  u.ownedFrames = [];
  u.ownedThemes = [];
  return hadItems;
}

function clearUserInventoryDatabase(userId) {
  if (!checkBlocked()) return;
  var admin = current();
  if (!admin) return;
  if (!can(admin, "manage_shop")) {
    toast("❌ Нет прав");
    return;
  }
  var u = users.find(function (x) {
    return x.id === userId;
  });
  if (!u) {
    toast("❌ Пользователь не найден");
    return;
  }
  var totalItems = (u.inventory || []).length;
  var hasSomething =
    totalItems > 0 || (u.purchases || []).length > 0 || (u.freeSpins || 0) > 0;
  if (!hasSomething) {
    toast("⚠️ У этого пользователя уже нет предметов", "warn");
    return;
  }
  confirmCritical({
    title: "Очистить БД инвентаря?",
    message:
      "У " +
      u.name +
      " удалятся все предметы (" +
      totalItems +
      " шт.). Также сбросятся разблокировки (цвет ника, анимация профиля, статистика, фон), рамки, темы, анимации лутбоксов, спины, буффы, мульти-открытие. Действие необратимо.",
    requireLogin: true,
    loginToConfirm: admin.login,
    danger: true,
    okText: "🧹 Очистить",
  }).then(function (ok) {
    if (!ok) return;
    var removed = clearInventoryDataForUser(u, admin);
    saveUsers();
    if (u.id === currentId) {
      applyColors(getUserColors(u));
      var el = document.getElementById("topAvatar");
      if (el) {
        el.innerHTML = avatarContent(u);
        el.className = withFrame(u, "avatar");
      }
    }
    addNotification(u.id, "🧹 Админ очистил ваш инвентарь");
    addLog(
      "Очистка инвентаря пользователя",
      u.name + " · " + removed + " предметов",
    );
    playSound("sell");
    toast("🧹 Очищено: " + removed + " предметов у " + u.name, "success");
    try {
      renderInvEditor();
    } catch (e) {}
    try {
      renderInventory();
    } catch (e) {}
    try {
      renderShop();
    } catch (e) {}
    try {
      renderStaff();
    } catch (e) {}
    try {
      renderWheel();
    } catch (e) {}
    try {
      renderLootboxes();
    } catch (e) {}
    try {
      checkFrozenStatus();
    } catch (e) {}
    if (profileUserId === u.id)
      try {
        renderProfileTab(u.id);
      } catch (e) {}
  });
}

