function wipeDatabaseWithExport() {
  checkBlocked() &&
    (can(current(), "export_data") && can(current(), "delete_user")
      ? confirmCritical({
          title: "Очистить базу данных?",
          message:
            "Будут удалены все логи, задачи, переводы и обнулён прогресс пользователей. Настройки магазина, правил и ролей сохранятся.",
          requireLogin: true,
          loginToConfirm: current().login,
          danger: true,
          okText: "🗑️ Очистить",
        }).then(function (e) {
          if (!e) return;
          var r =
            trustSettings && "number" == typeof trustSettings.start
              ? trustSettings.start
              : 50;
          users.forEach(function (e) {
            e.coins = 0;
            e.balance = 0;
            e.coinHistory = [];
            e.balanceHistory = [];
            e.history = [];
            e.trust = r;
            e.trustBase = r;
            e.trustHistory = [];
            e.trustLastEvent = Date.now();
            e.inventory = [];
            e.purchases = [];
            e.lootboxHistory = [];
            e.spinHistory = [];
            e.spinCount = 0;
            e.freeSpins = 0;
            e.lastSpin = 0;
            e.dailyStreak = 0;
            e.lastDailyReward = "";
            e.warnings = [];
            e.warned = false;
            e.warnedReason = "";
            e.warnedUntil = "";
            e.frozen = false;
            e.frozenReason = "";
            e.frozenUntil = "";
            e.onVacation = false;
            e.vacationReason = "";
            e.vacationUntil = "";
            e.keys = {};
            e.buffs = {};
            e.coupons = [];
            e.cart = [];
            e.usedGiftCards = [];
            e.claimedAchievements = {};
            e.bpPremiumSeasons = [];
            e.customBadges = [];
            e.ownedFrames = [];
            e.ownedThemes = [];
            e.ownedAnimations = ["classic"];
            e.lbAnimation = "classic";
            e.frame = "";
            e.profileBg = "";
            e.nickColor = "";
            e.profileAnim = "none";
            e.canNickColor = false;
            e.canProfileAnim = false;
            e.canProfileBg = false;
            e.canAdvancedStats = false;
            e.multiOpen = { x3: false, x5: false, x10: false };
            e.skipLbAnim = false;
          });
          tasks = [];
          transfers = [];
          loginLogs = [];
          txLog = [];
          challenges = [];
          promotionRequests = [];
          caseBattles = [];
          announcements = [];
          giftCards = [];
          promoCodes = [];
          changeLog = [];
          logs = [
            {
              time: new Date().toISOString(),
              user: current().name,
              role: current().role,
              action: "Выполнена полная очистка базы данных",
            },
          ];
          if (typeof save === "function") save();
          if (typeof render === "function") render();
          toast("✅ База данных очищена!");
        })
      : toast("❌ Нет прав для очистки базы", "error"));
}

