function applyThemeColors(tn) {
  var t = THEMES[tn];
  if (!t) return;
  var u = current();
  if (!u) return;
  u.theme = tn;
  u.customColors = Object.assign({}, t);
  saveUsers();
  applyColors(u.customColors);
  for (var i = 0; i < COLOR_KEYS.length; i++) {
    var k = COLOR_KEYS[i];
    var ci = document.getElementById("cp_" + k);
    var ti = document.getElementById("ct_" + k);
    if (ci) ci.value = t[k];
    if (ti) ti.value = t[k];
  }
  document.body.classList.toggle("theme-light", tn === "light");
  toast("🎨 Тема применена");
}
function updateColor(k, v) {
  var ti = document.getElementById("ct_" + k);
  if (ti) ti.value = v;
  document.documentElement.style.setProperty("--" + k, v);
  var u = current();
  if (!u) return;
  var c = getUserColors(u);
  c[k] = v;
  saveUserColors(u.id, c);
}
function updateColorFromText(k, v) {
  if (/^#[0-9a-fA-F]{6}$/.test(v)) {
    var ci = document.getElementById("cp_" + k);
    if (ci) ci.value = v;
    document.documentElement.style.setProperty("--" + k, v);
    var u = current();
    if (!u) return;
    var c = getUserColors(u);
    c[k] = v;
    saveUserColors(u.id, c);
  } else toast("⚠️ Формат: #RRGGBB");
}
function setLbAnimation(animKey) {
  var u = current();
  if (!u || !LB_ANIMS[animKey]) return;
  if (!Array.isArray(u.ownedAnimations)) u.ownedAnimations = ["classic"];
  if (u.ownedAnimations.indexOf(animKey) === -1) {
    toast("❌ Купите");
    return;
  }
  u.lbAnimation = animKey;
  saveUsers();
  toast("🎁 Анимация: " + LB_ANIMS[animKey].name);
  closeModal();
  setTimeout(openSettings, 200);
}
function saveSpinButtonText() {
  var u = current();
  if (!u) return;
  var el = document.getElementById("sbtInput");
  if (!el) return;
  u.spinButtonText = el.value.trim().slice(0, 12);
  saveUsers();
  toast("✅ Надпись сохранена");
  renderWheel();
}
function saveSkipLbSetting() {
  var u = current();
  if (!u) return;
  var el = document.getElementById("skipLbAnim");
  u.skipLbAnim = el ? el.checked : false;
  saveUsers();
  toast(u.skipLbAnim ? "⏭ Анимация отключена" : "🎬 Анимация включена");
  updateSkipLbBtn();
}
function saveSoundSettings() {
  var u = current();
  if (!u) return;
  if (!u.notificationSettings)
    u.notificationSettings = { sounds: true, volume: 0.7 };
  u.notificationSettings.sounds = document.getElementById("sndEnabled").checked;
  u.notificationSettings.volume =
    (parseInt(document.getElementById("sndVolume").value, 10) || 0) / 100;
  saveUsers();
  toast("💾 Настройки звука сохранены");
  closeModal();
  playSound("coin");
}

