function setMood(mood) {
  var u = current();
  if (!u || !MOODS[mood]) return;
  u.mood = mood;
  saveUsers();
  updateTopbarMood();
  try {
    renderStaff();
  } catch (e) {}
  if (profileUserId === u.id)
    try {
      renderProfileTab(u.id);
    } catch (e) {}
  toast("Настроение: " + moodLabel(mood));
}
function setCustomMood(moodKey, emoji) {
  var u = current();
  if (!u || !MOODS[moodKey]) return;
  if (!u.customMoods) u.customMoods = {};
  emoji = (emoji || "").trim();
  if (emoji) u.customMoods[moodKey] = emoji;
  else delete u.customMoods[moodKey];
  saveUsers();
  updateTopbarMood();
  toast("✅ Смайл настроения сохранён");
}
function openMoodPicker() {
  var u = current();
  if (!u) return;
  var cur = u.mood || "online";
  var html =
    '<h2>Настроение</h2><div style="display:flex;flex-direction:column;gap:8px;margin-top:10px;">';
  for (var k in MOODS)
    if (MOODS.hasOwnProperty(k)) {
      var custom = (u.customMoods && u.customMoods[k]) || "";
      html += '<div style="display:flex;gap:6px;align-items:center;">';
      html +=
        '<button class="btn ' +
        (k === cur ? "primary2" : "") +
        '" onclick="setMood(\'' +
        k +
        '\');closeModal();" style="flex:1;justify-content:flex-start;">' +
        moodIcon(k, u) +
        " " +
        MOODS[k].label +
        "</button>";
      html +=
        '<input value="' +
        esc(custom) +
        '" maxlength="4" placeholder="' +
        MOODS[k].icon +
        '" onchange="setCustomMood(\'' +
        k +
        '\',this.value)" style="width:60px;text-align:center;">';
      html += "</div>";
    }
  html +=
    '</div><div class="modal-actions"><button class="btn" onclick="closeModal()">Закрыть</button></div>';
  document.getElementById("modalContent").innerHTML = html;
  document.getElementById("modal").classList.remove("hidden");
}

/* ============ ГЛОБАЛЬНЫЙ ПОИСК ============ */
/* ═══════════════════════════════════════════════════════
   #56 — ГЛОБАЛЬНЫЙ ПОИСК (с выпадашкой по группам)
   ═══════════════════════════════════════════════════════ */
var _gsTimer = null;
function globalSearchDebounced() {
  if (_gsTimer) clearTimeout(_gsTimer);
  _gsTimer = setTimeout(globalSearch, 200);
}
function _gsRow(inner, onclick) {
  return (
    '<div style="padding:8px 10px;border-radius:8px;cursor:pointer;font-size:13px;transition:background .1s;" onmouseover="this.style.background=\'#ffffff08\'" onmouseout="this.style.background=\'\'" onclick="' +
    onclick +
    '">' +
    inner +
    "</div>"
  );
}
function globalSearch() {
  var gs = document.getElementById("globalSearch");
  var box = document.getElementById("globalSearchResults");
  if (!gs || !box) return;
  var q = (gs.value || "").toLowerCase().trim();
  var u = current();
  if (!u) {
    box.classList.add("hidden");
    return;
  }
  if (!q) {
    box.classList.add("hidden");
    box.innerHTML = "";
    return;
  }

  var groups = [];

  /* Сотрудники */
  if (can(u, "view_staff")) {
    var staff = users
      .filter(function (x) {
        return (
          (x.name || "").toLowerCase().indexOf(q) !== -1 ||
          (x.login || "").toLowerCase().indexOf(q) !== -1 ||
          (x.role || "").toLowerCase().indexOf(q) !== -1
        );
      })
      .slice(0, 5);
    if (staff.length)
      groups.push({
        title: "👥 Сотрудники",
        items: staff.map(function (x) {
          var inner =
            '<div style="display:flex;gap:8px;align-items:center;">' +
            '<span class="' +
            withFrame(x, "mini-avatar") +
            '">' +
            avatarContent(x) +
            "</span>" +
            '<div style="flex:1;min-width:0;"><div style="font-weight:700;font-size:13px;">' +
            esc(x.name) +
            "</div>" +
            '<div class="muted" style="font-size:11px;">' +
            esc(x.role) +
            "</div></div></div>";
          return {
            html: _gsRow(
              inner,
              "closeGlobalSearch();openProfileInTab('" + x.id + "')",
            ),
          };
        }),
      });
  }

  /* Задачи */
  if (can(u, "view_tasks")) {
    var canAll = can(u, "view_all_tasks");
    var ts = tasks
      .filter(function (t) {
        if (!canAll && t.assignee !== u.id) return false;
        return (t.title || "").toLowerCase().indexOf(q) !== -1;
      })
      .slice(0, 5);
    if (ts.length)
      groups.push({
        title: "📋 Задачи",
        items: ts.map(function (t) {
          var inner =
            '<div style="font-weight:700;">' +
            esc(t.title) +
            "</div>" +
            '<div class="muted" style="font-size:11px;">' +
            esc(t.assigneeName || "—") +
            " · " +
            (t.status || "") +
            "</div>";
          return {
            html: _gsRow(
              inner,
              "closeGlobalSearch();switchTab('tasks');setTimeout(function(){var el=document.getElementById('taskSearch');if(el){el.value=" +
                jsArg(t.title) +
                ";renderTasks();}},120)",
            ),
          };
        }),
      });
  }

  /* Товары */
  if (can(u, "view_shop")) {
    var items = shopItems
      .filter(function (it) {
        if (!it.active) return false;
        if (!isShopItemVisibleForUser(it, u)) return false;
        return (it.name || "").toLowerCase().indexOf(q) !== -1;
      })
      .slice(0, 5);
    if (items.length)
      groups.push({
        title: "🛒 Товары",
        items: items.map(function (it) {
          var inner =
            '<div style="display:flex;gap:8px;align-items:center;">' +
            '<div style="font-size:22px;">' +
            esc(it.icon || "🛍") +
            "</div>" +
            '<div style="flex:1;min-width:0;"><div style="font-weight:700;font-size:13px;">' +
            esc(it.name) +
            "</div>" +
            '<div class="muted" style="font-size:11px;">' +
            (it.currency === "coins" ? "🪙" : "₽") +
            " " +
            fmtBalance(it.price) +
            "</div></div></div>";
          return {
            html: _gsRow(
              inner,
              "closeGlobalSearch();switchTab('economy');switchEcoSubTab('shop');setTimeout(function(){openShopItemPreview(" +
                jsArg(it.id) +
                ");},150)",
            ),
          };
        }),
      });
  }

  /* Объявления */
  if (can(u, "view_announcements")) {
    var news = announcements
      .filter(function (n) {
        return (n.title || "").toLowerCase().indexOf(q) !== -1;
      })
      .slice(0, 5);
    if (news.length)
      groups.push({
        title: "📢 Объявления",
        items: news.map(function (n) {
          var inner =
            '<div style="font-weight:700;">' +
            esc(n.title) +
            "</div>" +
            '<div class="muted" style="font-size:11px;">' +
            esc(n.author || "—") +
            "</div>";
          return {
            html: _gsRow(inner, "closeGlobalSearch();switchTab('news')"),
          };
        }),
      });
  }

  /* Промокоды */
  if (can(u, "manage_promo")) {
    var promos = promoCodes
      .filter(function (p) {
        return (p.code || "").toLowerCase().indexOf(q) !== -1;
      })
      .slice(0, 5);
    if (promos.length)
      groups.push({
        title: "🎟 Промокоды",
        items: promos.map(function (p) {
          var inner =
            '<div style="font-weight:800;color:var(--gold);font-family:ui-monospace,monospace;">' +
            esc(p.code) +
            "</div>" +
            '<div class="muted" style="font-size:11px;">' +
            getPromoRewardLabel(p) +
            " · " +
            p.uses +
            "/" +
            p.maxUses +
            "</div>";
          return {
            html: _gsRow(
              inner,
              "closeGlobalSearch();switchTab('economy');switchEcoSubTab('promo')",
            ),
          };
        }),
      });
  }

  if (!groups.length) {
    box.innerHTML =
      '<div style="padding:20px;text-align:center;color:var(--muted);font-size:13px;">🔍 Ничего не найдено</div>';
    box.classList.remove("hidden");
    return;
  }

  var html = "";
  groups.forEach(function (g) {
    html += '<div style="padding:4px 0;">';
    html +=
      '<div style="font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);font-weight:800;padding:8px 12px 4px;">' +
      g.title +
      "</div>";
    g.items.forEach(function (it) {
      html += it.html;
    });
    html += "</div>";
  });
  box.innerHTML = html;
  box.classList.remove("hidden");
}
function closeGlobalSearch() {
  var box = document.getElementById("globalSearchResults");
  if (box) box.classList.add("hidden");
  var gs = document.getElementById("globalSearch");
  if (gs) gs.value = "";
}
document.addEventListener("click", function (e) {
  var gs = document.getElementById("globalSearch");
  var box = document.getElementById("globalSearchResults");
  if (!gs || !box) return;
  if (!gs.contains(e.target) && !box.contains(e.target))
    box.classList.add("hidden");
});
document.addEventListener("keydown", function (e) {
  if (e.key === "Escape") {
    var box = document.getElementById("globalSearchResults");
    if (box && !box.classList.contains("hidden")) {
      box.classList.add("hidden");
    }
  }
});
/* ═══ /ГЛОБАЛЬНЫЙ ПОИСК ═══ */

/* ============ СТАФФ-ПАНЕЛЬ ============ */
function switchSfTab(t) {
  window._sfSubTab = t;
  [
    "employees",
    "freeze",
    "vacation",
    "promotion",
    "analytics",
    "balances",
    "invEditor",
    "history",
    "loginLog",
    "logs",
    "roles",
    "userPerms",
  ].forEach(function (x) {
    var el = document.getElementById(
      "sfSection" + x.charAt(0).toUpperCase() + x.slice(1),
    );
    if (el) el.classList.toggle("hidden", x !== t);
    var btn = document.getElementById(
      "sfTab" + x.charAt(0).toUpperCase() + x.slice(1),
    );
    if (btn) btn.classList.toggle("active", x === t);
  });
  renderSfTab(t);
}
function renderSfTab(t) {
  if (t === "employees") renderSfEmployees();
  if (t === "freeze") renderSfFreeze();
  if (t === "vacation") renderSfVacation();
  if (t === "promotion") renderSfPromotion();
  if (t === "analytics") renderSfAnalytics();
  if (t === "balances") renderSfBalances();
  if (t === "invEditor") renderInvEditor();
  if (t === "history") renderSfHistory();
  /* NEW: перенесено из sectionAudit */
  if (t === "loginLog")
    try {
      renderLoginLog();
    } catch (e) {}
  if (t === "logs")
    try {
      renderLogs();
    } catch (e) {}
  if (t === "roles") {
    try {
      renderRolePermissions();
    } catch (e) {}
    try {
      renderTrustSettings();
    } catch (e) {}
  }
  if (t === "userPerms")
    try {
      renderUserPermsList();
    } catch (e) {}
}

// FIX: во всех sf-секциях проверка прав view_staff
function renderSfEmployees() {
  var el = document.getElementById("sfEmployeesList");
  if (!el) return;
  var u = current();
  if (!u) return;
  if (!can(u, "view_staff")) {
    el.innerHTML =
      '<div class="empty" data-icon="🔒"><b>Нет доступа</b><small>Требуется разрешение на просмотр сотрудников</small></div>';
    return;
  }
  var list = users.filter(function (x) {
    return x.id !== currentId;
  });
  var syncAllBtn = can(u, "manage_permissions")
    ? '<div style="margin-bottom:12px;"><button class="btn primary2 small" onclick="syncAllDiscordUsers()">🔄 Синхронизировать всех с Discord</button></div>'
    : "";
  el.innerHTML =
    syncAllBtn +
    '<div class="table-wrap"><table style="min-width:1100px;"><thead><tr><th>Сотрудник</th><th>Роль</th><th>Trust</th><th>Выговоры</th><th>Баланс / Коины</th><th>Бейджи</th><th>Статус</th><th></th></tr></thead><tbody>' +
    list
      .map(function (x) {
        var st = renderUserStatusBadge(x);
        var bh = renderBadgesCollapsed(x, 3);
        var wb = renderWarnsBadge(x);
        return (
          "<tr><td><b>" +
          esc(x.name) +
          '</b></td><td style="' +
          roleStyle(x.role) +
          '">' +
          esc(x.role) +
          "</td><td>" +
          renderTrustMiniBadge(x) +
          "</td><td>" +
          wb +
          "</td><td><b>💵 " +
          fmtBalance(x.balance) +
          '</b><br><span class="muted">🪙 ' +
          fmtBalance(x.coins) +
          '</span></td><td style="max-width:320px;">' +
          bh +
          "</td><td>" +
          st +
          '</td><td><button class="btn small" onclick="openProfileInTab(\'' +
          x.id +
          "')\">👤</button></td></tr>"
        );
      })
      .join("") +
    "</tbody></table></div>";
}
function renderSfFreeze() {
  var el = document.getElementById("sfFreezeList");
  if (!el) return;
  var u = current();
  if (!u) return;
  if (!can(u, "view_staff") && !can(u, "freeze_user")) {
    el.innerHTML = '<div class="empty" data-icon="🔒"><b>Нет доступа</b></div>';
    return;
  }
  var list = users.filter(function (x) {
    return isFrozen(x);
  });
  if (!list.length) {
    el.innerHTML =
      '<div class="empty" data-icon="❄️" style="margin-top:20px;"><b>Никто не заморожен</b><small>Все сотрудники активны. Отличная работа!</small></div>';
    return;
  }
  el.innerHTML = list
    .map(function (x) {
      return (
        '<div class="promo-request-card"><div class="pr-head"><div><div class="pr-title">' +
        esc(x.name) +
        '</div><div class="pr-meta">❄️ ' +
        (x.frozenUntil ? fmtDate(x.frozenUntil) : "бессрочно") +
        " · " +
        esc(x.frozenReason || "—") +
        '</div></div><div><button class="btn small primary2" onclick="unfreezeUser(\'' +
        x.id +
        "')\">🔓 Разморозить</button></div></div></div>"
      );
    })
    .join("");
}
function renderSfVacation() {
  var el = document.getElementById("sfVacationList");
  if (!el) return;
  var u = current();
  if (!u) return;
  if (!can(u, "view_staff") && !can(u, "edit_user")) {
    el.innerHTML = '<div class="empty" data-icon="🔒"><b>Нет доступа</b></div>';
    return;
  }
  var list = users.filter(isOnVacation);
  if (!list.length) {
    el.innerHTML =
      '<div class="empty" data-icon="🌴" style="margin-top:20px;"><b>Все на месте</b><small>На данный момент никто не находится в отпуске.</small></div>';
    return;
  }
  el.innerHTML = list
    .map(function (x) {
      return (
        '<div class="promo-request-card"><div class="pr-head"><div><div class="pr-title">' +
        esc(x.name) +
        '</div><div class="pr-meta">🌴 до ' +
        (x.vacationUntil ? fmtDate(x.vacationUntil) : "—") +
        '</div></div><div><button class="btn small primary2" onclick="unvacation(\'' +
        x.id +
        "')\">🔙 Вернуть</button></div></div></div>"
      );
    })
    .join("");
}
function renderSfPromotion() {
  var el = document.getElementById("sfPromotionList");
  if (!el) return;
  var u = current();
  if (!u) return;
  if (
    !can(u, "view_staff") &&
    !can(u, "edit_user") &&
    !can(u, "manage_permissions")
  ) {
    el.innerHTML = '<div class="empty" data-icon="🔒"><b>Нет доступа</b></div>';
    return;
  }
  var list = promotionRequests
    .filter(function (r) {
      return (
        r.status === "pending" ||
        r.status === "approved" ||
        r.status === "rejected"
      );
    })
    .slice()
    .reverse()
    .slice(0, 50);
  if (!list.length) {
    el.innerHTML =
      '<div class="empty" data-icon="📈" style="margin-top:20px;"><b>Нет запросов на повышение</b><small>Очередь пуста. Все карьерные вопросы решены.</small></div>';
    return;
  }
  var canResolve = can(u, "manage_permissions") || can(u, "edit_user");
  el.innerHTML = list
    .map(function (r) {
      var cls =
        r.status === "pending"
          ? "pending"
          : r.status === "approved"
            ? "approved"
            : "rejected";
      var actions = "";
      if (r.status === "pending" && canResolve) {
        actions =
          '<div style="display:flex;gap:6px;flex-wrap:wrap;"><button class="btn primary2 small" onclick="approvePromotionRequest(\'' +
          r.id +
          '\')">✅ Повысить</button><button class="btn danger small" onclick="rejectPromotionRequest(\'' +
          r.id +
          "')\">❌ Отклонить</button></div>";
      } else if (r.status === "approved") {
        actions =
          '<span class="badge badge-active">✅ Одобрено ' +
          (r.resolvedBy ? "(" + esc(r.resolvedBy) + ")" : "") +
          "</span>";
      } else if (r.status === "rejected") {
        actions =
          '<span class="badge badge-frozen">❌ Отклонено' +
          (r.rejectReason ? ": " + esc(r.rejectReason) : "") +
          "</span>";
      }
      return (
        '<div class="promo-request-card ' +
        cls +
        '"><div class="pr-head"><div><div class="pr-title">' +
        esc(r.userName) +
        ": " +
        esc(r.currentRole) +
        ' <span class="pr-arrow">→</span> ' +
        esc(r.requestedRole) +
        '</div><div class="pr-meta"><span>🕐 ' +
        new Date(r.createdAt).toLocaleString() +
        '</span></div></div></div><div class="pr-reason">' +
        esc(r.reason || "") +
        "</div>" +
        actions +
        "</div>"
      );
    })
    .join("");
}
function approvePromotionRequest(id) {
  if (!checkBlocked() || !rateLimit("promoReq")) return;
  if (!can(current(), "manage_permissions") && !can(current(), "edit_user")) {
    toast("❌ Нет прав");
    return;
  }
  var r = promotionRequests.find(function (x) {
    return x.id === id;
  });
  if (!r || r.status !== "pending") return;
  var u = users.find(function (x) {
    return x.id === r.userId;
  });
  if (!u) {
    toast("❌ Сотрудник не найден");
    return;
  }
  /* FIX #8: нельзя повысить до роли, не ниже своей (кроме Владельца) */
  var _curIdx = ROLE_HIERARCHY.indexOf(current().role);
  var _reqIdx = ROLE_HIERARCHY.indexOf(r.requestedRole);
  if (current().role !== "Владелец" && _reqIdx >= _curIdx) {
    toast(
      "❌ Нельзя повысить до «" + r.requestedRole + "» — она не ниже вашей",
      "error",
    );
    return;
  }
  confirmCritical({
    title: "Повысить сотрудника?",
    message: u.name + ": " + r.currentRole + " → " + r.requestedRole,
    okText: "📈 Повысить",
  }).then(function (ok) {
    if (!ok) return;
    u.role = r.requestedRole;
    addHistoryEntry(u.id, "Повышение", r.currentRole + " → " + r.requestedRole);
    r.status = "approved";
    r.resolvedAt = new Date().toISOString();
    r.resolvedBy = current().name;
    syncDiscordRole(u, r.requestedRole);
    saveUsers();
    savePromotionRequests();
    addNotification(u.id, "📈 Повышение: " + r.requestedRole, {
      mention: true,
    });
    renderSfPromotion();
    renderStaff();
    toast("📈 Повышен", "success");
  });
}
async function rejectPromotionRequest(id) {
  if (!checkBlocked()) return;
  if (!can(current(), "manage_permissions") && !can(current(), "edit_user")) {
    toast("❌ Нет прав");
    return;
  }
  var r = promotionRequests.find(function (x) {
    return x.id === id;
  });
  if (!r || r.status !== "pending") return;
  var reason = await promptModal({
    title: "Отклонить повышение?",
    label: "Причина отказа",
    value: "",
    okText: "❌ Отклонить",
    danger: true,
  });
  if (reason === null) return;
  r.status = "rejected";
  r.rejectReason = (reason || "").trim();
  r.resolvedAt = new Date().toISOString();
  r.resolvedBy = current().name;
  savePromotionRequests();
  var u = users.find(function (x) {
    return x.id === r.userId;
  });
  if (u)
    addNotification(
      u.id,
      "📈 Отказ в повышении" + (r.rejectReason ? ": " + r.rejectReason : ""),
    );
  renderSfPromotion();
  toast("❌ Запрос на повышение отклонён");
}
// FIX: один рендер аналитики, без дублирования с renderAnalytics
function renderSfAnalytics() {
  var el = document.getElementById("sfAnalytics");
  if (!el) return;
  var u = current();
  if (!u) return;
  if (!can(u, "view_staff")) {
    el.innerHTML = '<div class="empty" data-icon="🔒"><b>Нет доступа</b></div>';
    return;
  }
  var totalBal = users.reduce(function (s, x) {
    return s + (Number(x.balance) || 0);
  }, 0);
  var totalCoins = users.reduce(function (s, x) {
    return s + (Number(x.coins) || 0);
  }, 0);
  var avgTrust = users.length
    ? Math.round(
        users.reduce(function (s, x) {
          return s + getEffectiveTrust(x);
        }, 0) / users.length,
      )
    : 0;
  var frozen = users.filter(isFrozen).length;
  var vacation = users.filter(isOnVacation).length;
  var active = users.filter(function (x) {
    return !isFrozen(x) && !isOnVacation(x);
  }).length;
  el.innerHTML =
    '<div class="widget-grid"><div class="widget"><h4>👥 Всего</h4><div class="value">' +
    users.length +
    '</div></div><div class="widget"><h4>🟢 В сети</h4><div class="value" style="color:var(--accent)">' +
    active +
    '</div></div><div class="widget"><h4>❄️ Заморожено</h4><div class="value" style="color:var(--danger)">' +
    frozen +
    '</div></div><div class="widget"><h4>🌴 В отпуске</h4><div class="value" style="color:var(--gold)">' +
    vacation +
    '</div></div><div class="widget"><h4>🎖️ Средний trust</h4><div class="value">' +
    avgTrust +
    '</div></div><div class="widget"><h4>💵 Всего ₽</h4><div class="value">' +
    fmtBalance(totalBal) +
    '</div></div><div class="widget"><h4>🪙 Всего коинов</h4><div class="value">' +
    fmtBalance(totalCoins) +
    '</div></div><div class="widget"><h4>📈 Запросов</h4><div class="value">' +
    promotionRequests.filter(function (r) {
      return r.status === "pending";
    }).length +
    "</div></div></div>";
}

function zeroBalance(userId, currency) {
  if (!checkBlocked() || !rateLimit("zeroBalance")) return;
  var u = users.find(function (x) {
    return x.id === userId;
  });
  if (!u) return;
  var isCoins = currency === "coins";
  if (isCoins && !can(current(), "manage_coins")) {
    toast("Нет прав");
    return;
  }
  if (!isCoins && !can(current(), "manage_balance")) {
    toast("Нет прав");
    return;
  }
  var have = isCoins ? Number(u.coins) || 0 : Number(u.balance) || 0;
  if (have === 0) {
    toast("Уже 0");
    return;
  }
  var sym = isCoins ? "🪙" : "₽";
  confirmCritical({
    title: "Обнулить " + (isCoins ? "коины" : "баланс") + "?",
    message: u.name + " потеряет " + sym + " " + fmtBalance(have) + ".",
    requireLogin: true,
    loginToConfirm: u.login,
    danger: true,
    okText: "🚫 Обнулить",
  }).then(function (ok) {
    if (!ok) return;
    if (isCoins) changeCoins(u.id, -have, "Обнуление");
    else changeBalance(u.id, -have, "Обнуление");
    addLog(
      "Обнулён " + (isCoins ? "баланс коинов" : "баланс ₽") + " у " + u.name,
    );
    toast("🚫 Обнулено", "success");
    renderSfBalances();
    renderStaff();
    if (profileUserId === u.id)
      try {
        renderProfileTab(u.id);
      } catch (e) {}
  });
}

/* ============ ПЕРЕКЛЮЧЕНИЕ ВКЛАДОК ============ */

function openMyProfile() {
  profileUserId = currentId;
  switchTab("profile");
}

function switchTab(tab) {
  var user = current();
  if (!user) return;
  if (tab === "kpi") tab = "leaderboard";
  if (tab === "inventory") tab = "profile";
  if (tab === "staff" && !can(user, "view_staff")) tab = "tasks";
  if (
    tab === "staffFunc" &&
    !can(user, "view_staff") &&
    !can(user, "freeze_user") &&
    !can(user, "edit_user") &&
    !can(user, "manage_shop")
  )
    tab = "tasks";
  if (
    tab === "economy" &&
    !can(user, "view_shop") &&
    !can(user, "transfer_currency") &&
    !can(user, "view_balance") &&
    !can(user, "view_coins")
  )
    tab = "tasks";
  if (tab === "news" && !can(user, "view_announcements")) tab = "tasks";

  /* FIX: синхронизируем hash с вкладкой, чтобы F5 возвращал туда же */
  if (tab !== "profile") {
    var _newHash = "#" + tab;
    if (location.hash !== _newHash) {
      try {
        history.replaceState(
          null,
          "",
          location.pathname + location.search + _newHash,
        );
      } catch (e) {}
    }
  }

  var tabNames = [
    "dashboard",
    "staffFunc",
    "staff",
    "tasks",
    "economy",
    "games",
    "news",
    "leaderboard",
    "rules",
    "jobDesc",
    "promotions",
    "inventory",
    "profile",
    "kpi",
    "battlePass",
  ];
  var TAB_ID_MAP2 = { battlePass: "BattlePass" };
  tabNames.forEach(function (t) {
    var sfx = TAB_ID_MAP2[t] || t.charAt(0).toUpperCase() + t.slice(1);
    var el = document.getElementById("section" + sfx);
    if (el) el.classList.toggle("hidden", t !== tab);
    var btn = document.getElementById("tab" + sfx);
    if (btn) btn.classList.toggle("active", t === tab);
  });

  var ta = document.getElementById("taskActions");
  if (ta) ta.style.display = can(user, "create_task") ? "flex" : "none";
  var isStaffTab = tab === "staff";
  var cb = document.getElementById("createBtn");
  var eb = document.getElementById("exportBtn");
  if (cb)
    cb.classList.toggle("hidden", !isStaffTab || !can(user, "create_user"));
  if (eb)
    eb.classList.toggle("hidden", !isStaffTab || !can(user, "export_data"));
  updateTabsVisibility();

  if (tab === "profile") {
    if (!profileUserId) {
      var cur = current();
      if (cur) {
        profileUserId = cur.id;
        renderProfileTab(cur.id);
      }
    } else {
      var exists = users.some(function (u) {
        return u.id === profileUserId;
      });
      if (!exists) {
        profileUserId = null;
        var cur2 = current();
        if (cur2) {
          profileUserId = cur2.id;
          renderProfileTab(cur2.id);
        }
      } else renderProfileTab(profileUserId);
    }
  }

  if (tab === "dashboard")
    try {
      renderDashboard();
    } catch (e) {
      console.error("DASHBOARD ERROR:", e);
    }
  if (tab === "tasks")
    try {
      renderTasks();
    } catch (e) {}
  if (tab === "economy")
    try {
      switchEcoSubTab(window._ecoSubTab || "transfers");
    } catch (e) {}
  if (tab === "games")
    try {
      renderGames();
    } catch (e) {}
  if (tab === "news")
    try {
      renderNews();
    } catch (e) {}
  if (tab === "leaderboard")
    try {
      renderLeaderboard();
    } catch (e) {}
  if (tab === "rules")
    try {
      renderRules();
    } catch (e) {
      console.error("RULES ERROR:", e);
    }
  if (tab === "jobDesc")
    try {
      renderJobDescTab();
    } catch (e) {
      console.error("JOBDESC ERROR:", e);
    }
  if (tab === "promotions")
    try {
      renderPromotions();
    } catch (e) {}
  if (tab === "inventory")
    try {
      renderInventory();
    } catch (e) {}
  if (tab === "staff")
    try {
      renderStaff();
    } catch (e) {}
  if (tab === "staffFunc")
    try {
      switchSfTab(window._sfSubTab || "employees");
    } catch (e) {}
  if (tab === "battlePass")
    try {
      renderBattlePass();
    } catch (e) {
      console.error("BP ERROR:", e);
      toast("❌ Battle Pass: " + (e.message || e), "error", { duration: 6000 });
    }
}

function switchAuditSubTab(sub) {
  ["loginLog", "logs", "roles", "userPerms"].forEach(function (t) {
    var el = document.getElementById(
      "auditSection" + t.charAt(0).toUpperCase() + t.slice(1),
    );
    if (el) el.classList.toggle("hidden", t !== sub);
    var btn = document.getElementById(
      "auditSub" + t.charAt(0).toUpperCase() + t.slice(1),
    );
    if (btn) btn.classList.toggle("active", t === sub);
  });
  if (sub === "loginLog")
    try {
      renderLoginLog();
    } catch (e) {}
  if (sub === "logs")
    try {
      renderLogs();
    } catch (e) {}
  if (sub === "roles") {
    try {
      renderRolePermissions();
    } catch (e) {}
    try {
      renderTrustSettings();
    } catch (e) {}
  }
  if (sub === "userPerms")
    try {
      renderUserPermsList();
    } catch (e) {}
}

/* ============ TOAST ============ */
function toastTypeFromText(t) {
  if (t === null || t === undefined) return "info";
  var s = String(t);

  /* ❌ Ошибки / удаления */
  if (/^(❌|⚠️|🚫|⛔|🔒|✕|💀|☠️|💔|🗑|🗑️|📁|📷|🥀|🔪)/.test(s)) return "error";

  /* ✅ Успех */
  if (/^(✅|🎉|✔️|💾|🛒|💡|🔓|🎊|☑️|✨|📤|📥)/.test(s)) return "success";

  /* 🪙 Коины */
  if (/^🪙/.test(s)) return "coin";

  /* 🏅 Бейджи */
  if (/^(🏅|🎁|🥇|🥈|🥉|⭐|🌟|💎|👑|🏆|🎖️|🎯|💜|💠|🏹|🎓|🔮|🌈|🎡|🎰)/.test(s))
    return "badge";

  /* 💵 Деньги */
  if (/^(💸|💵|💰)/.test(s)) return "money";

  /* ⚠️ Системные */
  if (/^(🔥|⚡|🌴|❄️|⏳|🔔|📢|📌|ℹ️|💬)/.test(s)) return "warn";

  return "info";
}
function toastIconForType(type) {
  return (
    {
      success: "✅",
      error: "❌",
      warn: "⚠️",
      info: "💬",
      coin: "🪙",
      badge: "🏅",
      money: "💵",
    }[type] || "💬"
  );
}
function toast(t, type, opts) {
  opts = opts || {};
  var containerId =
    opts.position === "top" ? "toastContainerTop" : "toastContainer";
  var c = document.getElementById(containerId);
  if (!c && opts.position === "top") {
    c = document.createElement("div");
    c.id = "toastContainerTop";
    c.className = "toast-container toast-top";
    document.body.appendChild(c);
  }
  if (!c) c = document.getElementById("toastContainer");
  if (!c) return;

  var raw = String(t || "");
  if (!raw) return;
  type = type || toastTypeFromText(raw);
  var validTypes = [
    "success",
    "error",
    "warn",
    "info",
    "coin",
    "badge",
    "money",
  ];
  if (validTypes.indexOf(type) === -1) type = "info";
  var parsed = extractToastEmoji(raw);
  var text = parsed.text || raw;

  var iconHtml = "";
  if (opts.icon !== false) {
    var icon = forceEmojiVS(parsed.icon || toastIconForType(type));
    iconHtml = '<div class="toast-icon">' + esc(icon) + "</div>";
  }

  var el = document.createElement("div");
  el.className = "toast " + type;

  var undoHtml = "";
  if (opts.undo) {
    undoHtml =
      '<button type="button" class="toast-undo">' +
      esc(opts.undoText || "↩ Отменить") +
      "</button>";
  }

  el.innerHTML =
    iconHtml +
    '<div class="toast-body">' +
    '<div class="toast-text">' +
    esc(text) +
    "</div>" +
    (undoHtml ? '<div class="toast-actions">' + undoHtml + "</div>" : "") +
    "</div>" +
    '<button type="button" class="toast-close" aria-label="Закрыть">×</button>' +
    '<div class="toast-bar"></div>';

  var duration = opts.duration || 2800;
  c.appendChild(el);
  void el.offsetWidth;
  el.classList.add("show");
  var dismissed = false;
  var dismiss = function () {
    if (dismissed) return;
    dismissed = true;
    el.classList.remove("show");
    el.classList.add("leaving");
    setTimeout(function () {
      if (el.parentNode) el.parentNode.removeChild(el);
    }, 300);
  };
  var closeBtn = el.querySelector(".toast-close");
  if (closeBtn) closeBtn.onclick = dismiss;
  var undoBtn = el.querySelector(".toast-undo");
  if (undoBtn && opts.undo) {
    undoBtn.onclick = function () {
      try {
        opts.undo();
      } catch (e) {
        console.error(e);
      }
      dismiss();
    };
  }
  setTimeout(dismiss, duration);

  var MAX_TOASTS = 5;
  while (c.children.length > MAX_TOASTS) {
    var oldest = c.firstElementChild;
    if (!oldest) break;
    oldest.classList.add("leaving");
    oldest.remove();
  }
}
// FIX: closeModal не сбрасывает onclick у самого модала (иначе ломает confirmCritical)
// FIX: если открыт критический диалог — корректно его отменяем, чтобы промис не завис
function closeModal() {
  var m = document.getElementById("modal");
  /* FIX #5: приоритет у confirmCritical (он защищён от повторного открытия),
     но зачищаем и «зависший» _pmCancel, чтобы следующий promptModal открылся */
  if (_criticalOpen && typeof _criticalCancel === "function") {
    try {
      _criticalCancel(false);
    } catch (e) {
      console.warn("closeModal critical:", e);
    }
    if (typeof _pmCancel === "function") {
      try {
        _pmCancel(null);
      } catch (_) {}
    }
    return;
  }
  if (typeof _pmCancel === "function") {
    try {
      _pmCancel(null);
    } catch (e) {
      console.warn("closeModal prompt:", e);
    }
    return;
  }
  if (m && !m.classList.contains("hidden")) {
    playSound("close");
    m.classList.add("hidden");
  }
  /* FIX: обновляем Battle Pass секцию, если она открыта за модалкой */
  _bpRefreshIfVisible();
}

