/* ============ АВТОВЫХОД ============ */
var _inactivityTimer = null;
var _inactivityWarnTimer = null;

function resetInactivityTimer() {
  if (_inactivityTimer) clearTimeout(_inactivityTimer);
  if (_inactivityWarnTimer) clearTimeout(_inactivityWarnTimer);
  var u = current();
  if (!u) return;
  var minutes =
    u.notificationSettings &&
    typeof u.notificationSettings.autoLogoutMinutes === "number"
      ? u.notificationSettings.autoLogoutMinutes
      : 30;
  if (minutes === 0) return;
  var warnMs = (minutes - 2) * 60 * 1000;
  var logoutMs = minutes * 60 * 1000;
  if (warnMs > 0) {
    _inactivityWarnTimer = setTimeout(function () {
      if (!current()) return;
      toast("⏳ Автовыход через 2 минуты бездействия", "warn", {
        duration: 5000,
      });
    }, warnMs);
  }
  _inactivityTimer = setTimeout(function () {
    if (!current()) return;
    toast("🚪 Автовыход по бездействию", "info");
    setTimeout(function () {
      logout();
    }, 500);
  }, logoutMs);
}

["mousemove", "keydown", "click", "scroll", "touchstart"].forEach(
  function (evt) {
    document.addEventListener(evt, resetInactivityTimer, {
      passive: true,
      capture: true,
    });
  },
);

function saveAutoLogoutSetting(val) {
  var u = current();
  if (!u) return;
  if (!u.notificationSettings) u.notificationSettings = {};
  u.notificationSettings.autoLogoutMinutes = parseInt(val, 10) || 0;
  saveUsers();
  resetInactivityTimer();
  toast("💾 Настройка сохранена");
}

/* ============ БЫСТРАЯ СМЕНА АККАУНТОВ ============ */
function addToSavedAccounts(u) {
  if (!u) return;
  if (u.notificationSettings && u.notificationSettings.saveAccounts === false)
    return;
  var saved = safeParseArray("savedAccounts", []);
  var now = Date.now();
  saved = saved.filter(function (a) {
    return a.login !== u.login;
  });
  saved.unshift({
    id: u.id,
    login: u.login,
    name: u.name,
    avatar: u.avatar || "",
    frame: u.frame || "",
    savedAt: now,
    expiresAt: now + 7 * 24 * 60 * 60 * 1000,
  });
  if (saved.length > 5) saved = saved.slice(0, 5);
  localStorage.setItem("savedAccounts", JSON.stringify(saved));
}

function renderSavedAccounts() {
  var container = document.getElementById("switchAccountsList");
  var section = document.getElementById("savedAccountsSection");
  if (!container || !section) return;
  var saved = safeParseArray("savedAccounts", []);
  var now = Date.now();
  saved = saved.filter(function (a) {
    return !a.expiresAt || a.expiresAt > now;
  });
  localStorage.setItem("savedAccounts", JSON.stringify(saved));
  var cur = current();
  var others = saved.filter(function (a) {
    return a.login !== (cur ? cur.login : "");
  });
  if (others.length === 0) {
    section.classList.add("hidden");
    return;
  }
  section.classList.remove("hidden");
  container.innerHTML = others
    .map(function (a) {
      var _safeAv = safeUrl(a.avatar);
      var avHtml = _safeAv
        ? '<img src="' +
          _safeAv +
          '" style="width:100%;height:100%;object-fit:cover;">'
        : esc(initials(a.name));
      var frameCls = a.frame && FRAMES[a.frame] ? FRAMES[a.frame].css : "";
      /* FIX: jsArg() вместо esc() внутри onclick — иначе логин с апострофом ломает JS */
      return (
        '<div style="display:flex;gap:6px;align-items:center;width:100%;">' +
        '<button class="switch-acc-btn" onclick="executeQuickSwitch(' +
        jsArg(a.id) +
        ')">' +
        '<div class="switch-acc-avatar ' +
        frameCls +
        '">' +
        avHtml +
        "</div>" +
        '<div style="font-size:13px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;flex:1;min-width:0;">' +
        esc(a.name) +
        "</div>" +
        "</button>" +
        '<button class="switch-acc-del-btn" onclick="event.stopPropagation();forgetSavedAccount(' +
        jsArg(a.login) +
        ')" title="Забыть аккаунт">✕</button>' +
        "</div>"
      );
    })
    .join("");
}

function forgetSavedAccount(login) {
  var saved = safeParseArray("savedAccounts", []);
  saved = saved.filter(function (a) {
    return a.login !== login;
  });
  localStorage.setItem("savedAccounts", JSON.stringify(saved));
  renderSavedAccounts();
  toast("🗑 Аккаунт удалён из списка");
}

function forgetAllSavedAccounts() {
  if (!confirm("Удалить все сохранённые аккаунты на этом устройстве?")) return;
  localStorage.removeItem("savedAccounts");
  renderSavedAccounts();
  toast("🗑 Все сохранённые аккаунты удалены");
}

function saveAccountsSetting() {
  var u = current();
  if (!u) return;
  if (!u.notificationSettings) u.notificationSettings = {};
  var el = document.getElementById("saveAccToggle");
  u.notificationSettings.saveAccounts = el ? el.checked : true;
  saveUsers();
  toast("💾 Настройка сохранена");
}

function executeQuickSwitch(targetId) {
  var saved = safeParseArray("savedAccounts", []);
  var acc = saved.find(function (a) {
    return a.id === targetId;
  });
  if (!acc) return;

  var targetUser = users.find(function (u) {
    return u.id === targetId;
  });
  if (!targetUser) {
    toast("❌ Пользователь не найден", "error");
    saved = saved.filter(function (a) {
      return a.id !== targetId;
    });
    localStorage.setItem("savedAccounts", JSON.stringify(saved));
    return;
  }

  // Аккаунт существует и доступен — переключаемся.
  // Отдельная проверка «пароль сменился» невозможна: сайт хранит пользователей
  // в localStorage без серверной валидации. Если сменили пароль —
  // просто войдите заново через форму логина.

  // Мгновенный вход (минуя форму)
  if (isFrozen(targetUser))
    toast(
      "⚠️ Заморожен" +
        (targetUser.frozenUntil
          ? " до " + fmtDate(targetUser.frozenUntil)
          : ""),
    );
  if (isOnVacation(targetUser))
    toast(
      "🌴 В отпуске" +
        (targetUser.vacationUntil
          ? " до " + fmtDate(targetUser.vacationUntil)
          : ""),
    );

  currentId = targetUser.id;
  localStorage.setItem("teamCurrentUser", currentId);
  addLoginLog(targetUser);
  addLog("Вход (быстрая смена)");
  playSound("message");
  showApp();
  closeUserDropdown();
  toast("✅ Вы вошли как " + targetUser.name, "success");
}

function toggleUserDropdown(e) {
  if (e) e.stopPropagation();
  var dd = document.getElementById("userDropdown");
  if (dd) {
    dd.classList.toggle("hidden");
    if (!dd.classList.contains("hidden")) {
      renderSavedAccounts();
    }
  }
}
function closeUserDropdown() {
  var dd = document.getElementById("userDropdown");
  if (dd) dd.classList.add("hidden");
}
document.addEventListener("click", function (e) {
  var userbar = document.getElementById("userbarTop");
  var dd = document.getElementById("userDropdown");
  if (
    dd &&
    !dd.classList.contains("hidden") &&
    userbar &&
    !userbar.contains(e.target)
  ) {
    closeUserDropdown();
  }
});

/* ============ НАСТРОЙКИ ЛИМИТОВ ============ */
var _limUI = { tab: "global", expanded: {} };
function openLimitsSettings() {
  if (!checkBlocked()) return;
  var u = current();
  if (!u) return;
  if (!can(u, "manage_limits")) {
    toast("❌ Нет прав", "error");
    return;
  }
  _limUI = { tab: "global", expanded: {} };
  renderLimitsUI();
}
function renderLimitsUI() {
  var u = current();
  if (!u) return;
  if (!can(u, "manage_limits")) {
    toast("❌ Нет прав", "error");
    return;
  }
  var html =
    '<div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:14px;">';
  html += '<h2 style="margin:0;">🔢 Лимиты системы</h2>';
  html += '<div style="display:flex;gap:6px;flex-wrap:wrap;">';
  html +=
    '<button class="btn small danger" onclick="resetLimitsFromUI()">↺ Сбросить всё</button>';
  html += "</div></div>";
  html +=
    '<p class="muted" style="font-size:12px;margin:0 0 14px;line-height:1.5;">Значения применяются сразу. Хранятся в этом браузере (localStorage).</p>';
  html +=
    '<div class="field" style="margin-bottom:14px;"><input id="limSearch" placeholder="🔍 Поиск по названию поля..." oninput="filterLimitFields(this.value)"></div>';
  for (var section in LIMITS_META) {
    if (!LIMITS_META.hasOwnProperty(section)) continue;
    var meta = LIMITS_META[section];
    var data = LIMITS[section] || {};
    var isOpen = !!_limUI.expanded[section];
    html +=
      '<div class="perm-role-card ' +
      (isOpen ? "expanded" : "") +
      '" data-lim-section="' +
      section +
      '">';
    html +=
      '<div class="perm-role-header" onclick="_limUI.expanded[\'' +
      section +
      "']=!_limUI.expanded['" +
      section +
      "'];renderLimitsUI()\">";
    html += '<span class="perm-role-icon">' + meta.icon + "</span>";
    html += '<span class="perm-role-title">' + esc(meta.label) + "</span>";
    html += '<span class="perm-role-chevron">▼</span>';
    html += "</div>";
    html +=
      '<div class="perm-role-body" ' +
      (isOpen ? 'style="max-height:none;"' : "") +
      ">";
    html += '<div class="perm-role-body-inner">';
    for (var groupName in meta.sections) {
      if (!meta.sections.hasOwnProperty(groupName)) continue;
      html += '<div style="margin-bottom:14px;">';
      html +=
        '<div style="font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em;font-weight:800;margin-bottom:8px;padding-bottom:4px;border-bottom:1px solid #ffffff08;">' +
        esc(groupName) +
        "</div>";
      html +=
        '<div class="grid" style="grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:10px;">';
      var fields = meta.sections[groupName];
      for (var key in fields) {
        if (!fields.hasOwnProperty(key)) continue;
        var f = fields[key];
        var rawVal = data[key];
        var shownVal = rawVal;
        var unit = f.u || "";
        if (f.kind === "minutes") shownVal = Math.round((rawVal || 0) / 60000);
        else if (f.kind === "seconds")
          shownVal = Math.round((rawVal || 0) / 1000);
        else if (f.kind === "mb")
          shownVal = Math.round((rawVal || 0) / 1048576);
        var isDefault =
          DEFAULT_LIMITS[section] && DEFAULT_LIMITS[section][key] === rawVal;
        html +=
          '<div class="field lim-field" data-search="' +
          esc((f.l + " " + key + " " + meta.label).toLowerCase()) +
          '" style="margin:0;">';
        html +=
          '<label style="display:flex;justify-content:space-between;align-items:center;gap:6px;font-size:11px;">';
        html +=
          "<span>" +
          esc(f.l) +
          ' <span class="muted" style="font-weight:400;">' +
          esc(unit) +
          "</span></span>";
        if (!isDefault)
          html +=
            '<span class="badge badge-gold" style="font-size:9px;padding:1px 5px;">изменено</span>';
        html += "</label>";
        html +=
          '<input type="number" class="lim-input" data-section="' +
          esc(section) +
          '" data-key="' +
          esc(key) +
          '" data-kind="' +
          (f.kind || "") +
          '" data-min="' +
          f.min +
          '" data-max="' +
          f.max +
          '" value="' +
          shownVal +
          '" min="' +
          f.min +
          '" max="' +
          f.max +
          '" placeholder="' +
          (f.zeroText ? f.zeroText : "") +
          '" style="font-size:13px;padding:8px 10px;">';
        html +=
          '<div class="muted" style="font-size:10px;margin-top:2px;">' +
          f.min +
          "–" +
          f.max +
          (f.zeroText ? " (0 = " + f.zeroText + ")" : "") +
          "</div>";
        html += "</div>";
      }
      html += "</div></div>";
    }
    html += "</div></div></div>";
  }
  html +=
    '<div class="modal-actions"><button class="btn" onclick="closeModal()">Закрыть</button><button class="btn primary2" onclick="saveLimitsFromUI()">💾 Сохранить все</button></div>';
  document.getElementById("modalContent").innerHTML = html;
  document.getElementById("modal").classList.remove("hidden");
}
function filterLimitFields(q) {
  q = (q || "").toLowerCase().trim();
  document.querySelectorAll("#modalContent .lim-field").forEach(function (el) {
    var hay = el.getAttribute("data-search") || "";
    el.style.display = !q || hay.indexOf(q) !== -1 ? "" : "none";
  });
}
function saveLimitsFromUI() {
  if (!checkBlocked()) return;
  var u = current();
  if (!u) return;
  if (!can(u, "manage_limits")) {
    toast("❌ Нет прав", "error");
    return;
  }
  if (!rateLimit("saveLimits")) return;
  var errors = [];
  var staged = [];
  document.querySelectorAll(".lim-input").forEach(function (inp) {
    var section = inp.getAttribute("data-section");
    var key = inp.getAttribute("data-key");
    var kind = inp.getAttribute("data-kind");
    var min = parseFloat(inp.getAttribute("data-min"));
    var max = parseFloat(inp.getAttribute("data-max"));
    var raw = parseFloat(inp.value);
    if (!isFinite(raw)) {
      errors.push(section + "." + key + ": не число");
      return;
    }
    if (raw < min || raw > max) {
      errors.push(section + "." + key + ": " + min + "–" + max);
      return;
    }
    var finalVal = raw;
    if (kind === "minutes") finalVal = Math.round(raw * 60000);
    else if (kind === "seconds") finalVal = Math.round(raw * 1000);
    else if (kind === "mb") finalVal = Math.round(raw * 1048576);
    else finalVal = Math.round(raw);
    staged.push({ section: section, key: key, val: finalVal });
  });
  if (errors.length) {
    toast("❌ " + errors.slice(0, 3).join(" · "), "error");
    return;
  }
  staged.forEach(function (x) {
    if (!LIMITS[x.section]) LIMITS[x.section] = {};
    LIMITS[x.section][x.key] = x.val;
  });
  saveLimitsConfig();
  addLog("Лимиты изменены", u.name);
  toast("💾 Лимиты сохранены", "success");
  renderLimitsUI();
}
function resetLimitsFromUI() {
  if (!checkBlocked()) return;
  var u = current();
  if (!u) return;
  if (!can(u, "manage_limits")) {
    toast("❌ Нет прав", "error");
    return;
  }
  confirmCritical({
    title: "Сбросить все лимиты?",
    message: "Все значения вернутся к заводским.",
    danger: true,
    okText: "↺ Сбросить",
  }).then(function (ok) {
    if (!ok) return;
    resetLimitsConfig();
    addLog("Лимиты сброшены", u.name);
    toast("↺ Лимиты сброшены", "success");
    renderLimitsUI();
  });
}

