function saveRulesData() {
  return _safeSet("rulesData", rulesData, "правила");
}
function resetRulesDataToDefault() {
  rulesData = JSON.parse(JSON.stringify(DEFAULT_RULES_DATA));
  saveRulesData();
}

var rulesData = safeParseObject("rulesData", null);
if (
  !rulesData ||
  typeof rulesData !== "object" ||
  !rulesData.main ||
  !Array.isArray(rulesData.main.items) ||
  !rulesData.notes ||
  !Array.isArray(rulesData.notes.items) ||
  !Array.isArray(rulesData.punishments)
) {
  rulesData = JSON.parse(JSON.stringify(DEFAULT_RULES_DATA));
  saveRulesData();
}
if (
  !rulesData.punishmentTable ||
  !Array.isArray(rulesData.punishmentTable.sections) ||
  rulesData.punishmentTable.sections.length === 0
) {
  rulesData.punishmentTable = JSON.parse(
    JSON.stringify(DEFAULT_RULES_DATA.punishmentTable),
  );
  saveRulesData();
}
if (
  !rulesData.jobDescriptions ||
  !Array.isArray(rulesData.jobDescriptions.roles) ||
  rulesData.jobDescriptions.roles.length === 0
) {
  rulesData.jobDescriptions = JSON.parse(
    JSON.stringify(DEFAULT_RULES_DATA.jobDescriptions),
  );
  saveRulesData();
}

var _rulesPTSectionsExpanded = {};
function toggleRptSection(si) {
  _rulesPTSectionsExpanded[si] = !_rulesPTSectionsExpanded[si];
  var sec = document.querySelector('.rpt-section[data-rpt-sec="' + si + '"]');
  if (sec) sec.classList.toggle("expanded", !!_rulesPTSectionsExpanded[si]);
}

function renderRulesTable(d, canEdit) {
  if (!d || !d.punishmentTable) return "";
  var pt = d.punishmentTable;
  var secs = Array.isArray(pt.sections) ? pt.sections : [];
  if (!secs.length) return "";

  var html = '<div class="rpt-wrap">';
  html += '<div class="rpt-hero">';
  if (canEdit) {
    html +=
      '<button class="btn primary2 small rpt-edit-btn" onclick="openRulesPTEditor()">✏️ Редактировать таблицу</button>';
  }
  html +=
    "<h2>" + esc(pt.title || "📋 Таблица наказаний с пояснениями") + "</h2>";
  html += '<div class="rpt-sub">' + esc(pt.subtitle || "") + "</div>";
  html += "</div>";

  secs.forEach(function (sec, si) {
    var cols =
      Array.isArray(sec.columns) && sec.columns.length
        ? sec.columns
        : ["Наказание"];
    var rows = Array.isArray(sec.rows) ? sec.rows : [];
    var expanded = !!_rulesPTSectionsExpanded[si];

    html +=
      '<div class="rpt-section' +
      (expanded ? " expanded" : "") +
      '" data-rpt-sec="' +
      si +
      '">';
    html += '  <div class="rpt-head" onclick="toggleRptSection(' + si + ')">';
    html += '    <span class="rpt-ico">' + esc(sec.icon || "📋") + "</span>";
    html += '    <span class="rpt-title">' + esc(sec.title || "") + "</span>";
    if (sec.ref)
      html += '    <span class="rpt-ref">' + esc(sec.ref) + "</span>";
    html += '    <span class="rpt-chev">▼</span>';
    html += "  </div>";
    html += '  <div class="rpt-body"><div class="rpt-body-inner">';
    if (sec.dangerText) {
      html += '    <div class="rpt-danger">' + esc(sec.dangerText) + "</div>";
    }
    if (rows.length) {
      html +=
        '    <div class="rpt-table-wrap"><table class="rpt-table"><thead><tr>';
      html += "      <th>Пункт</th><th>Нарушение и пояснение</th>";
      cols.forEach(function (c) {
        html += "<th>" + esc(c) + "</th>";
      });
      html += "    </tr></thead><tbody>";
      rows.forEach(function (row) {
        html += "<tr>";
        html += '  <td class="rpt-point">' + esc(row.point || "") + "</td>";
        html += '  <td class="rpt-desc">' + esc(row.desc || "");
        if (row.explanation) {
          html +=
            '    <span class="rpt-explain">' + esc(row.explanation) + "</span>";
        }
        html += "  </td>";
        var pun = Array.isArray(row.punishments) ? row.punishments : [];
        for (var ci = 0; ci < cols.length; ci++) {
          var p = pun[ci] || { text: "—", cls: "" };
          var cls = p.cls ? "rpt-" + p.cls : "";
          html += '  <td class="' + cls + '">' + esc(p.text || "—") + "</td>";
        }
        html += "</tr>";
      });
      html += "    </tbody></table></div>";
    } else {
      html +=
        '    <p class="muted" style="text-align:center;padding:12px;">Нет строк</p>';
    }
    html += "  </div></div>";
    html += "</div>";
  });

  if (Array.isArray(pt.footer) && pt.footer.length) {
    html += '<div class="rpt-footer">';
    pt.footer.forEach(function (line) {
      html += "<p>" + esc(line) + "</p>";
    });
    html += "</div>";
  }
  html += "</div>";
  return html;
}

function renderJobDescriptions(d, canEdit) {
  if (!d || !d.jobDescriptions) return "";
  var jd = d.jobDescriptions;
  var roles = Array.isArray(jd.roles) ? jd.roles : [];
  if (!roles.length) return "";

  var html = '<div class="jd-wrap">';
  html += '<div class="jd-hero">';
  if (canEdit) {
    html +=
      '<button class="btn primary2 small jd-edit-btn" onclick="openJobDescEditor()">✏️ Редактировать</button>';
  }
  html += "<h2>" + esc(jd.title || "💼 Описание должностей") + "</h2>";
  if (jd.intro) {
    html += '<div class="jd-intro">' + esc(jd.intro) + "</div>";
  }
  html += "</div>";

  html += '<div class="jd-list">';
  roles.forEach(function (role, ri) {
    var lvlClass = "level-" + (ri % 4);

    var iconChar = "👤";
    var rn = (role.name || "").toLowerCase();
    if (rn.indexOf("модератор") !== -1) {
      if (rn.indexOf("гл") !== -1) iconChar = "🔥";
      else if (rn.indexOf("ст") !== -1) iconChar = "⭐";
      else if (rn.indexOf("мл") !== -1 || rn.indexOf("стаж") !== -1)
        iconChar = "🌱";
      else iconChar = "🔨";
    } else if (rn.indexOf("администратор") !== -1) {
      if (rn.indexOf("гл") !== -1) iconChar = "🏰";
      else if (rn.indexOf("ст") !== -1) iconChar = "⚔️";
      else if (rn.indexOf("тех") !== -1) iconChar = "🔧";
      else iconChar = "👮";
    } else if (rn.indexOf("куратор") !== -1) iconChar = "🎯";
    else if (rn.indexOf("аналитик") !== -1) iconChar = "📊";
    else if (rn.indexOf("teamlead") !== -1 || rn.indexOf("тимлид") !== -1)
      iconChar = "💻";
    else if (rn.indexOf("поддержк") !== -1) iconChar = "🛟";
    else if (rn.indexOf("отпуск") !== -1) iconChar = "🌴";
    else if (rn.indexOf("работник") !== -1) iconChar = "⭐";
    else if (rn.indexOf("команда") !== -1) iconChar = "🛡️";

    html += '<div class="jd-card ' + lvlClass + '">';
    html += '  <div class="jd-role-head">';
    html += '    <div class="jd-role-icon-wrap">' + iconChar + "</div>";
    html += '    <div class="jd-role-info">';
    html +=
      '      <div class="jd-role-name">@' +
      esc(role.name || "Без названия") +
      "</div>";
    html += "    </div>";
    html += "  </div>";
    html +=
      '  <div class="jd-role-desc">' + esc(role.description || "") + "</div>";
    if (role.norm) {
      html +=
        '  <div class="jd-norm"><div><span class="norm-label">Норма</span>' +
        esc(role.norm) +
        "</div></div>";
    }
    html += "</div>";
  });
  html += "</div>";

  if (Array.isArray(jd.footer) && jd.footer.length) {
    html += '<div class="jd-footer">';

    var badges = [];
    var notes = [];
    var hasTitle = false;

    jd.footer.forEach(function (line) {
      if (!line || String(line).trim() === "") return;
      var text = String(line).trim();

      // Очищаем старые значки ✱ и 📌, если они застряли в localStorage
      text = text.replace(/^[✱📌⚠️\s]+/, "");

      if (text.startsWith("(") && text.endsWith(")")) {
        badges.push(text); // Справки (в скобках)
      } else if (text.indexOf("Примечания") !== -1 && text.length < 20) {
        hasTitle = true; // Заголовок "Примечания:"
      } else {
        // Фиксим пробел после цифры: "1.За" -> "1. За"
        text = text.replace(/^(\d+)\.\s*/, "$1. ");
        notes.push(text); // Обычные пункты
      }
    });

    if (badges.length) {
      html += '<div class="jd-footer-badges">';
      badges.forEach(function (b) {
        html += '<div class="jd-footer-badge">' + esc(b) + "</div>";
      });
      html += "</div>";
    }

    if (hasTitle) {
      html += '<div class="jd-footer-title">Примечания</div>';
    }

    if (notes.length) {
      html += '<div class="jd-footer-list">';
      notes.forEach(function (n, idx) {
        var numMatch = n.match(/^(\d+)\.\s*(.*)$/);
        var num = numMatch ? numMatch[1] : idx + 1;
        var textContent = numMatch ? numMatch[2] : n;

        html += '<div class="jd-footer-item">';
        html += '  <div class="jd-footer-num">' + num + "</div>";
        html += '  <div class="jd-footer-text">' + esc(textContent) + "</div>";
        html += "</div>";
      });
      html += "</div>";
    }

    html += "</div>";
  }

  html += "</div>";
  return html;
}

function renderJobDescTab() {
  var el = document.getElementById("jobDescContainer");
  if (!el) return;
  var d = rulesData || DEFAULT_RULES_DATA;
  var cu = current();
  var canEdit = cu && can(cu, "manage_announcements");
  var content = renderJobDescriptions(d, canEdit);
  if (!content) {
    el.innerHTML =
      '<div class="empty" data-icon="💼"><b>Должностей пока нет</b><small>Нажмите «✏️ Редактировать» на странице правил, чтобы добавить</small></div>';
  } else {
    el.innerHTML = content;
  }
}

function renderRules() {
  var el = document.getElementById("rulesContainer");
  if (!el) return;
  var d = rulesData || DEFAULT_RULES_DATA;
  var cu = current();
  var canEdit = cu && can(cu, "manage_announcements");

  function mainLi(text) {
    return (
      '<li><span class="rm-check">✓</span><span>' + esc(text) + "</span></li>"
    );
  }
  function cardLi(text) {
    return (
      '<li><span class="rc-bullet"></span><span>' + esc(text) + "</span></li>"
    );
  }
  function noteLi(text) {
    return (
      '<li><span class="rn-ico">📌</span><span>' + esc(text) + "</span></li>"
    );
  }

  var html = "";

  html += '<div class="rules-hero">';
  html += "  <h2>" + esc(d.heroTitle || "") + "</h2>";
  html +=
    '  <div class="rules-hero-sub">' + esc(d.heroSubtitle || "") + "</div>";
  html += "</div>";

  if (canEdit) {
    html +=
      '<div style="display:flex;justify-content:flex-end;gap:8px;margin-bottom:16px;flex-wrap:wrap;">';
    html +=
      '  <button class="btn primary2" onclick="openRulesEditor()">✏️ Редактировать правила</button>';
    html +=
      '  <button class="btn" onclick="openRulesPTEditor()">📋 Таблица наказаний</button>';
    html += "</div>";
  }

  var mainItems = d.main && Array.isArray(d.main.items) ? d.main.items : [];
  html += '<div class="rules-main">';
  html +=
    '  <div class="rules-main-title"><span class="rm-ico">' +
    esc((d.main && d.main.icon) || "📘") +
    "</span><span>" +
    esc((d.main && d.main.title) || "Основные правила") +
    "</span></div>";
  if (mainItems.length) {
    html += '  <ul class="rules-main-list">';
    mainItems.forEach(function (t) {
      html += mainLi(t);
    });
    html += "  </ul>";
  } else {
    html +=
      '  <p class="muted" style="text-align:center;padding:16px;">Пунктов нет</p>';
  }
  html += "</div>";

  var punishList = Array.isArray(d.punishments) ? d.punishments : [];
  if (punishList.length) {
    html += '<div class="rules-grid">';
    punishList.forEach(function (p) {
      var lvl =
        p.level === "serious" || p.level === "critical" ? p.level : "minor";
      var ex = Array.isArray(p.examples) ? p.examples : [];
      html += '<div class="rules-card ' + lvl + '">';
      html +=
        '  <div class="rules-card-head"><div class="rules-card-ico">' +
        esc(p.icon || "⚪") +
        "</div>";
      html +=
        '    <div class="rules-card-title"><div class="rc-level">' +
        esc(p.levelLabel || "") +
        '</div><div class="rc-name">' +
        esc(p.name || "") +
        "</div></div>";
      html += "  </div>";
      html +=
        '  <div class="rules-card-body"><div class="rc-label">Примеры нарушений</div><ul class="rules-card-list">';
      ex.forEach(function (t) {
        html += cardLi(t);
      });
      html += "  </ul></div>";
      html +=
        '  <div class="rules-card-penalty"><span class="rc-p-ico">' +
        esc(p.penaltyIcon || "⛔") +
        "</span> " +
        esc(p.penalty || "") +
        "</div>";
      html += "</div>";
    });
    html += "</div>";
  }

  html += renderRulesTable(d, canEdit);

  var noteItems = d.notes && Array.isArray(d.notes.items) ? d.notes.items : [];
  html += '<div class="rules-notes-new">';
  html +=
    '  <div class="rules-notes-title-new"><span class="rn-ico">' +
    esc((d.notes && d.notes.icon) || "⚠️") +
    "</span><span>" +
    esc((d.notes && d.notes.title) || "Примечания") +
    "</span></div>";
  if (noteItems.length) {
    html += '  <ul class="rules-notes-list">';
    noteItems.forEach(function (t) {
      html += noteLi(t);
    });
    html += "  </ul>";
  } else {
    html +=
      '  <p class="muted" style="text-align:center;padding:16px;">Примечаний нет</p>';
  }
  html += "</div>";

  el.innerHTML = html;
}

/* ============ РЕДАКТОР ПРАВИЛ ============ */
function openRulesEditor() {
  if (!checkBlocked()) return;
  var u = current();
  if (!u || !can(u, "manage_announcements")) {
    toast("❌ Нет прав", "error");
    return;
  }
  window._reDraft = JSON.parse(JSON.stringify(rulesData));
  renderRulesEditor();
}

