/* ─── Действия в редакторе: главные правила ─── */
function reAddMainItem() {
  if (!window._reDraft) return;
  window._reDraft.main.items.push("Новый пункт правил");
  renderRulesEditor();
}
function reRemoveMainItem(i) {
  if (!window._reDraft) return;
  if (window._reDraft.main.items.length <= 1) {
    toast("⚠️ Должен остаться хотя бы 1 пункт", "warn");
    return;
  }
  if (!confirm("Удалить этот пункт?")) return;
  window._reDraft.main.items.splice(i, 1);
  renderRulesEditor();
}

/* ─── Действия в редакторе: примечания ─── */
function reAddNoteItem() {
  if (!window._reDraft) return;
  window._reDraft.notes.items.push("Новое примечание");
  renderRulesEditor();
}
function reRemoveNoteItem(i) {
  if (!window._reDraft) return;
  if (window._reDraft.notes.items.length <= 1) {
    toast("⚠️ Должно остаться хотя бы 1 примечание", "warn");
    return;
  }
  if (!confirm("Удалить это примечание?")) return;
  window._reDraft.notes.items.splice(i, 1);
  renderRulesEditor();
}

/* ─── Действия в редакторе: уровни наказаний ─── */
function reAddPunishment() {
  if (!window._reDraft) return;
  window._reDraft.punishments.push({
    id: uid(),
    level: "minor",
    levelLabel: "Уровень " + (window._reDraft.punishments.length + 1),
    name: "Новый уровень",
    icon: "⚪",
    penaltyIcon: "⛔",
    penalty: "Наказание",
    examples: ["Пример нарушения"],
  });
  renderRulesEditor();
}
function reRemovePunishment(i) {
  if (!window._reDraft) return;
  if (window._reDraft.punishments.length <= 1) {
    toast("⚠️ Должен остаться хотя бы 1 уровень", "warn");
    return;
  }
  if (!confirm("Удалить этот уровень наказания?")) return;
  window._reDraft.punishments.splice(i, 1);
  renderRulesEditor();
}
function reAddPunishExample(pi) {
  if (!window._reDraft) return;
  window._reDraft.punishments[pi].examples.push("Новый пример");
  renderRulesEditor();
}
function reRemovePunishExample(pi, ei) {
  if (!window._reDraft) return;
  if (window._reDraft.punishments[pi].examples.length <= 1) {
    toast("⚠️ Должен остаться хотя бы 1 пример", "warn");
    return;
  }
  window._reDraft.punishments[pi].examples.splice(ei, 1);
  renderRulesEditor();
}

/* ─── Сохранение и сброс ─── */
function saveRulesFromEditor() {
  if (!checkBlocked()) return;
  var u = current();
  if (!u || !can(u, "manage_announcements")) {
    toast("❌ Нет прав", "error");
    return;
  }
  if (!window._reDraft) return;
  var d = window._reDraft;

  if (!d.main || !Array.isArray(d.main.items) || !d.main.items.length) {
    toast("❌ Добавьте хотя бы один пункт правил", "error");
    return;
  }
  if (!d.notes || !Array.isArray(d.notes.items) || !d.notes.items.length) {
    toast("❌ Добавьте хотя бы одно примечание", "error");
    return;
  }
  if (!Array.isArray(d.punishments) || !d.punishments.length) {
    toast("❌ Добавьте хотя бы один уровень наказания", "error");
    return;
  }
  d.punishments.forEach(function (p) {
    if (!p || !Array.isArray(p.examples)) p.examples = [];
  });

  rulesData = JSON.parse(JSON.stringify(d));
  saveRulesData();
  window._reDraft = null;
  addLog("Правила обновлены", u.name);
  playSound("taskDone");
  toast("💾 Правила сохранены", "success");
  closeModal();
  renderRules();
}

function confirmResetRules() {
  if (!checkBlocked()) return;
  var u = current();
  if (!u || !can(u, "manage_announcements")) {
    toast("❌ Нет прав", "error");
    return;
  }
  if (
    !confirm(
      "Сбросить правила к заводским настройкам?\n\nВсе текущие изменения будут потеряны.",
    )
  )
    return;
  resetRulesDataToDefault();
  window._reDraft = JSON.parse(JSON.stringify(rulesData));
  addLog("Правила сброшены к умолчанию", u.name);
  toast("↺ Правила сброшены к умолчанию", "success");
  renderRulesEditor();
  renderRules();
}

/* ============ РЕДАКТОР ТАБЛИЦЫ НАКАЗАНИЙ ============ */
var PT_COLOR_OPTIONS = [
  { k: "warn", l: "⚠️ Жёлтый (Warn)" },
  { k: "mute", l: "🟠 Оранжевый (Мут)" },
  { k: "mutevc", l: "🔵 Голубой (Мут VC)" },
  { k: "kick", l: "🔶 Оранжевый (Кик)" },
  { k: "ban", l: "🔴 Красный (Бан)" },
  { k: "perm", l: "🟥 Ярко-красный (Перманент)" },
];

var _rePTDraft = null;
var _rePTExpanded = {};

function openRulesPTEditor() {
  if (!checkBlocked()) return;
  var u = current();
  if (!u || !can(u, "manage_announcements")) {
    toast("❌ Нет прав", "error");
    return;
  }
  if (!rulesData.punishmentTable) {
    rulesData.punishmentTable = JSON.parse(
      JSON.stringify(DEFAULT_RULES_DATA.punishmentTable),
    );
  }
  _rePTDraft = JSON.parse(JSON.stringify(rulesData.punishmentTable));
  _rePTExpanded = {};
  renderRulesPTEditor();
}

function toggleRePTSection(si) {
  _rePTExpanded[si] = !_rePTExpanded[si];
  renderRulesPTEditor();
}

function renderRulesPTEditor() {
  var d = _rePTDraft;
  if (!d) return;
  if (!Array.isArray(d.sections)) d.sections = [];
  if (!Array.isArray(d.footer)) d.footer = [];

  var html = "<h2>📋 Редактор таблицы наказаний</h2>";
  html +=
    '<p class="muted" style="font-size:12px;margin-bottom:14px;">Изменения применяются после нажатия «💾 Сохранить таблицу» внизу.</p>';

  html += '<div class="notes-section">';
  html +=
    '<b style="display:block;color:var(--accent);margin-bottom:10px;">🎨 Заголовок таблицы</b>';
  html +=
    '<div class="field"><label>Заголовок</label><input value="' +
    esc(d.title || "") +
    '" oninput="_rePTDraft.title=this.value"></div>';
  html +=
    '<div class="field"><label>Подзаголовок</label><input value="' +
    esc(d.subtitle || "") +
    '" oninput="_rePTDraft.subtitle=this.value"></div>';
  html += "</div>";

  html +=
    '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;gap:8px;flex-wrap:wrap;">';
  html +=
    '<b style="color:var(--accent);">📑 Разделы таблицы (' +
    d.sections.length +
    ")</b>";
  html +=
    '<button class="btn primary2 small" onclick="rePTAddSection()">＋ Добавить раздел</button>';
  html += "</div>";

  d.sections.forEach(function (sec, si) {
    var isExp = !!_rePTExpanded[si];
    var rows = Array.isArray(sec.rows) ? sec.rows : [];
    var cols = Array.isArray(sec.columns) ? sec.columns : [];

    html += '<div class="notes-section" style="margin-bottom:10px;">';
    html +=
      '<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;cursor:pointer;" onclick="toggleRePTSection(' +
      si +
      ')">';
    html +=
      '<b style="color:var(--text);font-size:14px;">' +
      esc(sec.icon || "📋") +
      " " +
      esc(sec.title || "Раздел " + (si + 1)) +
      ' <span class="muted" style="font-weight:400;font-size:11px;">(' +
      rows.length +
      " строк)</span></b>";
    html += '<div style="display:flex;gap:6px;align-items:center;">';
    html +=
      '<span class="muted" style="font-size:11px;">' +
      (isExp ? "▲ Свернуть" : "▼ Развернуть") +
      "</span>";
    html += "</div></div>";

    if (isExp) {
      html +=
        '<div style="margin-top:12px;border-top:1px solid var(--line);padding-top:12px;">';

      html += '<div class="grid">';
      html +=
        '<div class="field" style="margin:0;"><label>Заголовок раздела</label><input value="' +
        esc(sec.title || "") +
        '" oninput="_rePTDraft.sections[' +
        si +
        '].title=this.value"></div>';
      html +=
        '<div class="field" style="margin:0;"><label>Ссылка на пункт (ref)</label><input value="' +
        esc(sec.ref || "") +
        '" oninput="_rePTDraft.sections[' +
        si +
        '].ref=this.value" placeholder="п. 2.1 – 2.3"></div>';
      html +=
        '<div class="field" style="margin:0;"><label>Иконка</label><input value="' +
        esc(sec.icon || "") +
        '" maxlength="4" oninput="_rePTDraft.sections[' +
        si +
        '].icon=this.value"></div>';
      html +=
        '<div class="field" style="margin:0;grid-column:1/-1;"><label>Danger-box (красное предупреждение, необязательно)</label><input value="' +
        esc(sec.dangerText || "") +
        '" oninput="_rePTDraft.sections[' +
        si +
        '].dangerText=this.value" placeholder="Например: ⚠️ Без предупреждений..."></div>';
      html +=
        '<div class="field" style="margin:0;grid-column:1/-1;"><label>Колонки таблицы (через запятую)</label><input value="' +
        esc(cols.join(", ")) +
        '" onchange="_rePTColsChanged(' +
        si +
        ', this.value)" placeholder="1 раз, 2 раз, 3+ раз"></div>';
      html += "</div>";

      html += '<div style="margin-top:12px;">';
      html +=
        '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;gap:6px;flex-wrap:wrap;">';
      html += '<b style="font-size:12px;">Строки</b>';
      html += '<div style="display:flex;gap:6px;flex-wrap:wrap;">';
      html +=
        '<button class="btn small primary2" onclick="rePTAddRow(' +
        si +
        ')">＋ Строка</button>';
      html +=
        '<button class="btn small" onclick="rePTAddColumn(' +
        si +
        ')" title="Добавить колонку наказаний (во все строки)">＋ Колонка</button>';
      html += "</div>";
      html += "</div>";

      rows.forEach(function (row, ri) {
        var pun = Array.isArray(row.punishments) ? row.punishments : [];
        html +=
          '<div style="background:#0b1710;border:1px solid var(--line);border-radius:10px;padding:10px;margin-bottom:8px;">';
        html +=
          '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">';
        html +=
          '<b style="font-size:12px;color:var(--gold);">Строка ' +
          (ri + 1) +
          "</b>";
        html +=
          '<button class="btn small danger" onclick="rePTRemoveRow(' +
          si +
          "," +
          ri +
          ')">✕ Удалить</button>';
        html += "</div>";
        html += '<div class="grid">';
        html +=
          '<div class="field" style="margin:0;"><label>Пункт</label><input value="' +
          esc(row.point || "") +
          '" oninput="_rePTDraft.sections[' +
          si +
          "].rows[" +
          ri +
          '].point=this.value" placeholder="2.2.1"></div>';
        html +=
          '<div class="field" style="margin:0;"><label>Нарушение</label><input value="' +
          esc(row.desc || "") +
          '" oninput="_rePTDraft.sections[' +
          si +
          "].rows[" +
          ri +
          '].desc=this.value"></div>';
        html +=
          '<div class="field" style="margin:0;grid-column:1/-1;"><label>Пояснение (необязательно)</label><textarea rows="2" oninput="_rePTDraft.sections[' +
          si +
          "].rows[" +
          ri +
          '].explanation=this.value" placeholder="Например: Пояснение: любые слова...">' +
          esc(row.explanation || "") +
          "</textarea></div>";
        html += "</div>";

        html += '<div style="margin-top:8px;">';
        html +=
          '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px;">';
        html +=
          '<span class="muted" style="font-size:11px;text-transform:uppercase;font-weight:800;">Наказания по колонкам (' +
          cols.length +
          ")</span>";
        html += "</div>";
        for (var ci = 0; ci < cols.length; ci++) {
          var p = pun[ci] || { text: "", cls: "warn" };
          html +=
            '<div style="display:flex;gap:6px;margin-bottom:4px;align-items:center;">';
          html +=
            '<span style="font-size:11px;color:var(--muted);width:70px;flex-shrink:0;">' +
            esc(cols[ci]) +
            ":</span>";
          html +=
            '<input value="' +
            esc(p.text || "") +
            '" oninput="_rePTDraft.sections[' +
            si +
            "].rows[" +
            ri +
            "].punishments[" +
            ci +
            '].text=this.value" placeholder="Текст наказания" style="flex:1;">';
          var selOpts = PT_COLOR_OPTIONS.map(function (o) {
            return (
              '<option value="' +
              o.k +
              '" ' +
              (p.cls === o.k ? "selected" : "") +
              ">" +
              o.l +
              "</option>"
            );
          }).join("");
          html +=
            '<select onchange="_rePTDraft.sections[' +
            si +
            "].rows[" +
            ri +
            "].punishments[" +
            ci +
            '].cls=this.value" style="width:180px;">' +
            selOpts +
            "</select>";
          html +=
            '<button class="btn small danger" style="padding:4px 8px;" onclick="rePTRemovePunish(' +
            si +
            "," +
            ri +
            "," +
            ci +
            ')">✕</button>';
          html += "</div>";
        }
        html += "</div>";
        html += "</div>";
      });

      html += "</div>";

      html +=
        '<div style="margin-top:12px;padding-top:12px;border-top:1px dashed var(--line);text-align:right;">';
      html +=
        '<button class="btn small danger" onclick="rePTRemoveSection(' +
        si +
        ')">✕ Удалить раздел</button>';
      html += "</div>";

      html += "</div>";
    }
    html += "</div>";
  });

  html += '<div class="notes-section" style="margin-top:12px;">';
  html +=
    '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">';
  html +=
    '<b style="color:var(--accent);">📌 Нижние примечания (' +
    d.footer.length +
    ")</b>";
  html +=
    '<button class="btn small primary2" onclick="rePTAddFooter()">＋ Добавить</button>';
  html += "</div>";
  d.footer.forEach(function (line, i) {
    html +=
      '<div style="display:flex;gap:6px;margin-bottom:6px;align-items:center;">';
    html +=
      '<input value="' +
      esc(line) +
      '" oninput="_rePTDraft.footer[' +
      i +
      ']=this.value" style="flex:1;">';
    html +=
      '<button class="btn small danger" onclick="rePTRemoveFooter(' +
      i +
      ')">✕</button>';
    html += "</div>";
  });
  if (!d.footer.length)
    html +=
      '<p class="muted" style="font-size:12px;padding:6px;">Нет примечаний</p>';
  html += "</div>";

  html += '<div class="modal-actions">';
  html +=
    '<button class="btn danger" onclick="rePTResetToDefault()">↺ Сбросить к умолчанию</button>';
  html += '<button class="btn" onclick="rePTCancel()">Отмена</button>';
  html +=
    '<button class="btn primary2" onclick="rePTSave()">💾 Сохранить таблицу</button>';
  html += "</div>";

  document.getElementById("modalContent").innerHTML = html;
  document.getElementById("modal").classList.remove("hidden");
}

function _rePTColsChanged(si, raw) {
  var cols = String(raw)
    .split(",")
    .map(function (s) {
      return s.trim();
    })
    .filter(function (s) {
      return s;
    });
  if (!cols.length) cols = ["Наказание"];
  _rePTDraft.sections[si].columns = cols;
  var rows = _rePTDraft.sections[si].rows || [];
  rows.forEach(function (row) {
    if (!Array.isArray(row.punishments)) row.punishments = [];
    while (row.punishments.length < cols.length)
      row.punishments.push({ text: "", cls: "warn" });
    // FIX: не обрезаем punishments — данные сохраняются при временном уменьшении колонок
  });
  renderRulesPTEditor();
}

function rePTAddSection() {
  _rePTDraft.sections.push({
    title: "Новый раздел",
    ref: "",
    icon: "📋",
    dangerText: "",
    columns: ["1 раз", "2 раз", "3 раз"],
    rows: [],
  });
  _rePTExpanded[_rePTDraft.sections.length - 1] = true;
  renderRulesPTEditor();
}
function rePTRemoveSection(si) {
  if (
    !confirm("Удалить раздел «" + (_rePTDraft.sections[si].title || "") + "»?")
  )
    return;
  _rePTDraft.sections.splice(si, 1);
  _rePTExpanded = {};
  renderRulesPTEditor();
}
function rePTAddRow(si) {
  var cols = _rePTDraft.sections[si].columns || [];
  var puns = [];
  for (var i = 0; i < cols.length; i++) puns.push({ text: "", cls: "warn" });
  _rePTDraft.sections[si].rows.push({
    point: "",
    desc: "",
    explanation: "",
    punishments: puns,
  });
  renderRulesPTEditor();
}
function rePTRemoveRow(si, ri) {
  if (!confirm("Удалить строку #" + (ri + 1) + "?")) return;
  _rePTDraft.sections[si].rows.splice(ri, 1);
  renderRulesPTEditor();
}
function rePTAddColumn(si) {
  if (!_rePTDraft || !_rePTDraft.sections[si]) return;
  if (!Array.isArray(_rePTDraft.sections[si].columns))
    _rePTDraft.sections[si].columns = [];
  var newColName = "Колонка " + (_rePTDraft.sections[si].columns.length + 1);
  _rePTDraft.sections[si].columns.push(newColName);
  var rows = _rePTDraft.sections[si].rows || [];
  rows.forEach(function (row) {
    if (!Array.isArray(row.punishments)) row.punishments = [];
    row.punishments.push({ text: "", cls: "warn" });
  });
  renderRulesPTEditor();
}
function rePTRemovePunish(si, ri, ci) {
  if (_rePTDraft.sections[si].columns.length <= 1) {
    toast("⚠️ Должна остаться хотя бы одна колонка", "warn");
    return;
  }
  _rePTDraft.sections[si].columns.splice(ci, 1);
  _rePTDraft.sections[si].rows.forEach(function (row) {
    if (Array.isArray(row.punishments) && row.punishments[ci] !== undefined)
      row.punishments.splice(ci, 1);
  });
  renderRulesPTEditor();
}
function rePTAddFooter() {
  _rePTDraft.footer.push("Новое примечание");
  renderRulesPTEditor();
}
function rePTRemoveFooter(i) {
  _rePTDraft.footer.splice(i, 1);
  renderRulesPTEditor();
}
function rePTResetToDefault() {
  if (
    !confirm(
      "Сбросить таблицу наказаний к заводским настройкам?\n\nВсе изменения будут потеряны.",
    )
  )
    return;
  _rePTDraft = JSON.parse(JSON.stringify(DEFAULT_RULES_DATA.punishmentTable));
  _rePTExpanded = {};
  toast("↺ Таблица сброшена к умолчанию (не забудьте сохранить)", "warn");
  renderRulesPTEditor();
}
function rePTCancel() {
  _rePTDraft = null;
  _rePTExpanded = {};
  closeModal();
}
function rePTSave() {
  if (!checkBlocked()) return;
  var u = current();
  if (!u || !can(u, "manage_announcements")) {
    toast("❌ Нет прав", "error");
    return;
  }
  if (!_rePTDraft) return;
  if (!Array.isArray(_rePTDraft.sections) || !_rePTDraft.sections.length) {
    toast("❌ Добавьте хотя бы один раздел", "error");
    return;
  }
  rulesData.punishmentTable = JSON.parse(JSON.stringify(_rePTDraft));
  saveRulesData();
  _rePTDraft = null;
  _rePTExpanded = {};
  addLog("Таблица наказаний обновлена", u.name);
  playSound("taskDone");
  toast("💾 Таблица наказаний сохранена", "success");
  closeModal();
  renderRules();
}

/* ============ РЕДАКТОР ОПИСАНИЯ ДОЛЖНОСТЕЙ ============ */
var _reJDDraft = null;

function openJobDescEditor() {
  if (!checkBlocked()) return;
  var u = current();
  if (!u || !can(u, "manage_announcements")) {
    toast("❌ Нет прав", "error");
    return;
  }
  if (!rulesData.jobDescriptions) {
    rulesData.jobDescriptions = JSON.parse(
      JSON.stringify(DEFAULT_RULES_DATA.jobDescriptions),
    );
  }
  _reJDDraft = JSON.parse(JSON.stringify(rulesData.jobDescriptions));
  renderJobDescEditor();
}

function renderJobDescEditor() {
  var d = _reJDDraft;
  if (!d) return;
  if (!Array.isArray(d.roles)) d.roles = [];
  if (!Array.isArray(d.footer)) d.footer = [];

  var html = "<h2>💼 Редактор описания должностей</h2>";
  html +=
    '<p class="muted" style="font-size:12px;margin-bottom:14px;">Изменения применяются после нажатия «💾 Сохранить» внизу.</p>';

  html += '<div class="notes-section">';
  html +=
    '<b style="display:block;color:var(--accent);margin-bottom:10px;">🎨 Заголовок раздела</b>';
  html +=
    '<div class="field"><label>Заголовок</label><input value="' +
    esc(d.title || "") +
    '" oninput="_reJDDraft.title=this.value"></div>';
  html +=
    '<div class="field"><label>Подзаголовок</label><input value="' +
    esc(d.subtitle || "") +
    '" oninput="_reJDDraft.subtitle=this.value"></div>';
  html +=
    '<div class="field"><label>Вступительный текст</label><textarea rows="3" oninput="_reJDDraft.intro=this.value">' +
    esc(d.intro || "") +
    "</textarea></div>";
  html += "</div>";

  html +=
    '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;gap:8px;flex-wrap:wrap;">';
  html +=
    '<b style="color:var(--accent);">👥 Должности (' + d.roles.length + ")</b>";
  html +=
    '<button class="btn primary2 small" onclick="reJDAddRole()">＋ Добавить должность</button>';
  html += "</div>";

  d.roles.forEach(function (role, ri) {
    html +=
      '<div class="notes-section" style="margin-bottom:10px;padding:12px;">';
    html +=
      '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">';
    html +=
      '<b style="font-size:13px;color:var(--gold);">Должность #' +
      (ri + 1) +
      "</b>";
    html += '<div style="display:flex;gap:4px;">';
    if (ri > 0)
      html +=
        '<button class="btn small" onclick="reJDMoveRole(' +
        ri +
        ', -1)" title="Выше">↑</button>';
    if (ri < d.roles.length - 1)
      html +=
        '<button class="btn small" onclick="reJDMoveRole(' +
        ri +
        ', 1)" title="Ниже">↓</button>';
    html +=
      '<button class="btn small danger" onclick="reJDRemoveRole(' +
      ri +
      ')" title="Удалить">✕</button>';
    html += "</div></div>";

    html += '<div class="grid">';
    html +=
      '<div class="field" style="margin:0;grid-column:1/-1;"><label>Название роли (без @)</label><input value="' +
      esc(role.name || "") +
      '" oninput="_reJDDraft.roles[' +
      ri +
      '].name=this.value" placeholder="Модератор"></div>';
    html +=
      '<div class="field" style="margin:0;grid-column:1/-1;"><label>Описание обязанностей</label><textarea rows="3" oninput="_reJDDraft.roles[' +
      ri +
      '].description=this.value" placeholder="Основные обязанности...">' +
      esc(role.description || "") +
      "</textarea></div>";
    html +=
      '<div class="field" style="margin:0;grid-column:1/-1;"><label>Норма / актив</label><textarea rows="2" oninput="_reJDDraft.roles[' +
      ri +
      '].norm=this.value" placeholder="Актив 10 часов в неделю...">' +
      esc(role.norm || "") +
      "</textarea></div>";
    html += "</div>";
    html += "</div>";
  });

  html += '<div class="notes-section" style="margin-top:12px;">';
  html +=
    '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">';
  html +=
    '<b style="color:var(--accent);">📌 Нижние примечания (' +
    d.footer.length +
    ")</b>";
  html +=
    '<button class="btn small primary2" onclick="reJDAddFooter()">＋ Добавить</button>';
  html += "</div>";
  d.footer.forEach(function (line, i) {
    html +=
      '<div style="display:flex;gap:6px;margin-bottom:6px;align-items:center;">';
    html +=
      '<input value="' +
      esc(line) +
      '" oninput="_reJDDraft.footer[' +
      i +
      ']=this.value" style="flex:1;">';
    html +=
      '<button class="btn small danger" onclick="reJDRemoveFooter(' +
      i +
      ')">✕</button>';
    html += "</div>";
  });
  if (!d.footer.length)
    html +=
      '<p class="muted" style="font-size:12px;padding:6px;">Нет примечаний</p>';
  html += "</div>";

  html += '<div class="modal-actions">';
  html +=
    '<button class="btn danger" onclick="reJDResetToDefault()">↺ Сбросить к умолчанию</button>';
  html += '<button class="btn" onclick="reJDCancel()">Отмена</button>';
  html +=
    '<button class="btn primary2" onclick="reJDSave()">💾 Сохранить</button>';
  html += "</div>";

  document.getElementById("modalContent").innerHTML = html;
  document.getElementById("modal").classList.remove("hidden");
}

function reJDAddRole() {
  _reJDDraft.roles.push({
    id: "jd-" + uid(),
    name: "Новая должность",
    description: "Обязанности...",
    norm: "Норма...",
  });
  renderJobDescEditor();
}
function reJDRemoveRole(ri) {
  if (
    !confirm("Удалить должность «" + (_reJDDraft.roles[ri].name || "") + "»?")
  )
    return;
  _reJDDraft.roles.splice(ri, 1);
  renderJobDescEditor();
}
function reJDMoveRole(ri, dir) {
  var newIdx = ri + dir;
  if (newIdx < 0 || newIdx >= _reJDDraft.roles.length) return;
  var temp = _reJDDraft.roles[ri];
  _reJDDraft.roles[ri] = _reJDDraft.roles[newIdx];
  _reJDDraft.roles[newIdx] = temp;
  renderJobDescEditor();
}
function reJDAddFooter() {
  _reJDDraft.footer.push("Новое примечание");
  renderJobDescEditor();
}
function reJDRemoveFooter(i) {
  _reJDDraft.footer.splice(i, 1);
  renderJobDescEditor();
}
function reJDResetToDefault() {
  if (
    !confirm(
      "Сбросить описание должностей к заводским настройкам?\n\nВсе изменения будут потеряны.",
    )
  )
    return;
  _reJDDraft = JSON.parse(JSON.stringify(DEFAULT_RULES_DATA.jobDescriptions));
  toast("↺ Должности сброшены к умолчанию (не забудьте сохранить)", "warn");
  renderJobDescEditor();
}
function reJDCancel() {
  _reJDDraft = null;
  closeModal();
}
function reJDSave() {
  if (!checkBlocked()) return;
  var u = current();
  if (!u || !can(u, "manage_announcements")) {
    toast("❌ Нет прав", "error");
    return;
  }
  if (!_reJDDraft) return;
  if (!Array.isArray(_reJDDraft.roles) || !_reJDDraft.roles.length) {
    toast("❌ Добавьте хотя бы одну должность", "error");
    return;
  }
  rulesData.jobDescriptions = JSON.parse(JSON.stringify(_reJDDraft));
  saveRulesData();
  _reJDDraft = null;
  addLog("Описание должностей обновлено", u.name);
  playSound("taskDone");
  toast("💾 Должности сохранены", "success");
  closeModal();
  renderRules();
  renderJobDescTab();
}

/* ═══════════════════════════════════════════════════
   ИСТОРИЯ СОБЫТИЙ (заморозки / отпуска / повышения)
   ═══════════════════════════════════════════════════ */
window._histFilters = { type: "all", search: "", from: "", to: "" };

function getHistoryTypeMeta(action) {
  var a = String(action || "").toLowerCase();

  // Заморозки
  if (a.indexOf("замороз") !== -1)
    return {
      id: "freeze",
      icon: "❄️",
      label: "Заморозка",
      cls: "badge-frozen",
    };
  if (a.indexOf("размороз") !== -1)
    return {
      id: "freeze",
      icon: "🔓",
      label: "Разморозка",
      cls: "badge-active",
    };

  // Отпуска
  if (a.indexOf("возврат из отпуска") !== -1 || a.indexOf("из отпуска") !== -1)
    return {
      id: "vacation",
      icon: "🔙",
      label: "Из отпуска",
      cls: "badge-active",
    };
  if (a.indexOf("отпуск") !== -1)
    return {
      id: "vacation",
      icon: "🌴",
      label: "Отпуск",
      cls: "badge-vacation",
    };

  // Выговоры
  if (a.indexOf("снятие выговор") !== -1)
    return {
      id: "warn",
      icon: "✅",
      label: "Снятие выговора",
      cls: "badge-active",
    };
  if (a.indexOf("выговор") !== -1)
    return { id: "warn", icon: "⚠️", label: "Выговор", cls: "badge-high" };

  // Повышения и роли
  if (a.indexOf("повышен") !== -1)
    return {
      id: "promotion",
      icon: "📈",
      label: "Повышение",
      cls: "badge-gold",
    };
  if (a.indexOf("снят") !== -1 && a.indexOf("должност") !== -1)
    return {
      id: "promotion",
      icon: "🎭",
      label: "Снятие с должности",
      cls: "badge-frozen",
    };
  if (a.indexOf("смен") !== -1 && a.indexOf("рол") !== -1)
    return {
      id: "promotion",
      icon: "🎭",
      label: "Смена роли",
      cls: "badge-gold",
    };

  return { id: "other", icon: "📋", label: "Событие", cls: "" };
}

function _collectHistoryRecords() {
  var all = [];
  users.forEach(function (usr) {
    (usr.history || []).forEach(function (h) {
      if (!h || !h.timestamp) return;
      var meta = getHistoryTypeMeta(h.action);
      all.push({
        userId: usr.id,
        userName: usr.name,
        userRole: usr.role,
        time: h.timestamp,
        by: h.by || "—",
        action: h.action || "",
        details: h.details || "",
        meta: meta,
      });
    });
  });
  all.sort(function (a, b) {
    return new Date(b.time) - new Date(a.time);
  });
  return all;
}

function _filterHistory(records, f) {
  return records.filter(function (r) {
    if (f.type !== "all" && r.meta.id !== f.type) return false;
    if (f.search) {
      var hay = (
        r.userName +
        " " +
        r.by +
        " " +
        r.action +
        " " +
        r.details
      ).toLowerCase();
      if (hay.indexOf(f.search.toLowerCase()) === -1) return false;
    }
    var rt = new Date(r.time).getTime();
    if (f.from) {
      var fromD = new Date(f.from + "T00:00:00").getTime();
      if (isFinite(fromD) && rt < fromD) return false;
    }
    if (f.to) {
      var toD = new Date(f.to + "T23:59:59.999").getTime();
      if (isFinite(toD) && rt > toD) return false;
    }
    return true;
  });
}

function _pluralRu(n, one, few, many) {
  n = Math.abs(n) % 100;
  var n1 = n % 10;
  if (n > 10 && n < 20) return many;
  if (n1 > 1 && n1 < 5) return few;
  if (n1 === 1) return one;
  return many;
}
function _saveFocusByIds(ids) {
  try {
    var ae = document.activeElement;
    if (!ae || !ae.id || ids.indexOf(ae.id) === -1) return null;
    var s = null,
      e = null;
    try {
      s = ae.selectionStart;
      e = ae.selectionEnd;
    } catch (err) {}
    if (typeof s === "number" && typeof e === "number")
      return { id: ae.id, start: s, end: e };
    return { id: ae.id };
  } catch (err) {
    return null;
  }
}
function _restoreFocus(s) {
  if (!s) return;
  var el = document.getElementById(s.id);
  if (!el) return;
  try {
    el.focus();
  } catch (e) {}
  if (
    typeof s.start === "number" &&
    typeof s.end === "number" &&
    el.setSelectionRange
  ) {
    try {
      el.setSelectionRange(s.start, s.end);
    } catch (e) {}
  }
}
function _onHistSearchInput(val) {
  window._histFilters.search = val;
  if (window._histSearchTimer) clearTimeout(window._histSearchTimer);
  window._histSearchTimer = setTimeout(function () {
    renderSfHistory();
  }, 250);
}

function renderSfHistory() {
  var el = document.getElementById("sfHistoryList");
  if (!el) return;
  var u = current();
  if (!u) return;
  if (!can(u, "view_staff") && !can(u, "view_logs")) {
    el.innerHTML =
      '<div class="empty" data-icon="🔒"><b>Нет доступа</b><small>Требуется право «view_staff» или «view_logs»</small></div>';
    return;
  }

  var focusState = _saveFocusByIds([
    "histFilterSearch",
    "histFilterType",
    "histFilterFrom",
    "histFilterTo",
  ]);

  var f = window._histFilters || { type: "all", search: "", from: "", to: "" };
  var all = _collectHistoryRecords();

  var counts = { freeze: 0, vacation: 0, promotion: 0, warn: 0, other: 0 };
  all.forEach(function (r) {
    if (counts[r.meta.id] !== undefined) counts[r.meta.id]++;
  });

  var filtered = _filterHistory(all, f);

  var totalBadge = document.getElementById("sfHistoryTotalBadge");
  if (totalBadge) {
    var word = _pluralRu(filtered.length, "событие", "события", "событий");
    totalBadge.textContent = filtered.length + " " + word;
  }

  var html = "";
  html +=
    '<div class="shop-controls" style="margin-bottom:14px;flex-wrap:wrap;gap:8px;">';
  html +=
    '<div class="search-wrap" style="flex:1;min-width:200px;"><input id="histFilterSearch" placeholder="🔍 Поиск по сотруднику, автору, деталям..." value="' +
    esc(f.search) +
    '" oninput="_onHistSearchInput(this.value)"></div>';
  html +=
    '<select id="histFilterType" onchange="window._histFilters.type=this.value;renderSfHistory()" style="min-width:190px;">';
  [
    ["all", "📋 Все (" + all.length + ")"],
    ["freeze", "❄️ Заморозки (" + counts.freeze + ")"],
    ["vacation", "🌴 Отпуска (" + counts.vacation + ")"],
    ["promotion", "📈 Повышения (" + counts.promotion + ")"],
    ["warn", "⚠️ Выговоры (" + counts.warn + ")"],
    ["other", "📌 Прочее (" + counts.other + ")"],
  ].forEach(function (o) {
    html +=
      '<option value="' +
      o[0] +
      '" ' +
      (f.type === o[0] ? "selected" : "") +
      ">" +
      o[1] +
      "</option>";
  });
  html += "</select>";
  html +=
    '<input id="histFilterFrom" type="date" value="' +
    esc(f.from) +
    '" onchange="window._histFilters.from=this.value;renderSfHistory()" title="С даты" style="min-width:130px;">';
  html +=
    '<input id="histFilterTo" type="date" value="' +
    esc(f.to) +
    '" onchange="window._histFilters.to=this.value;renderSfHistory()" title="По дату" style="min-width:130px;">';
  html +=
    "<button class=\"btn small\" onclick=\"if(window._histSearchTimer)clearTimeout(window._histSearchTimer);window._histFilters={type:'all',search:'',from:'',to:''};renderSfHistory()\">✖ Сброс</button>";
  html +=
    '<button class="btn small" onclick="exportSfHistoryCSV()">⇩ Excel</button>';
  html += "</div>";

  if (!filtered.length) {
    html +=
      '<div class="empty" data-icon="📭"><b>Событий не найдено</b><small>Измените фильтры или диапазон дат</small></div>';
    el.innerHTML = html;
    _restoreFocus(focusState);
    return;
  }

  var groups = {};
  filtered.forEach(function (r) {
    var d = new Date(r.time);
    var key = d.toDateString();
    if (!groups[key]) groups[key] = { date: d, items: [] };
    groups[key].items.push(r);
  });
  var sortedKeys = Object.keys(groups).sort(function (a, b) {
    return new Date(groups[b].date) - new Date(groups[a].date);
  });

  var today = new Date().toDateString();
  var yest = new Date(Date.now() - 86400000).toDateString();

  html += '<div style="display:flex;flex-direction:column;gap:18px;">';
  var _histLimit =
    f.from || f.to || f.search || (f.type && f.type !== "all")
      ? sortedKeys.length
      : 60;
  sortedKeys.slice(0, _histLimit).forEach(function (key) {
    var g = groups[key];
    var label =
      key === today
        ? "Сегодня"
        : key === yest
          ? "Вчера"
          : g.date.toLocaleDateString("ru-RU", {
              day: "2-digit",
              month: "long",
              year: "numeric",
            });

    html += "<div>";
    html +=
      '<div style="font-size:11px;color:var(--muted);font-weight:800;text-transform:uppercase;letter-spacing:.08em;margin-bottom:8px;padding-bottom:6px;border-bottom:1px dashed #ffffff10;display:flex;justify-content:space-between;">';
    html += "<span>📅 " + esc(label) + "</span>";
    html += '<span style="opacity:.6;">' + g.items.length + "</span>";
    html += "</div>";
    html += '<div style="display:flex;flex-direction:column;gap:6px;">';

    g.items.slice(0, 300).forEach(function (r) {
      var timeStr = new Date(r.time).toLocaleTimeString("ru-RU", {
        hour: "2-digit",
        minute: "2-digit",
      });
      html +=
        '<div style="display:grid;grid-template-columns:40px 1fr auto;gap:12px;align-items:center;padding:10px 14px;background:linear-gradient(160deg,#0f1e16,#0a1710);border:1px solid var(--line);border-radius:10px;">';
      html +=
        '<div style="width:40px;height:40px;border-radius:10px;background:#0a1710;border:1px solid var(--line);display:grid;place-items:center;font-size:20px;">' +
        r.meta.icon +
        "</div>";
      html += '<div style="min-width:0;">';
      html +=
        '<div style="font-size:13px;font-weight:800;color:var(--text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' +
        esc(r.userName) +
        ' <span class="badge ' +
        r.meta.cls +
        '" style="font-size:9px;padding:2px 6px;margin-left:4px;vertical-align:middle;">' +
        esc(r.meta.label) +
        "</span>" +
        "</div>";
      html +=
        '<div style="font-size:11.5px;color:var(--muted);margin-top:3px;line-height:1.4;word-break:break-word;">' +
        esc(r.details || r.action || "—") +
        "</div>";
      html +=
        '<div style="font-size:10.5px;color:var(--muted);margin-top:3px;opacity:.75;">👤 Автор: ' +
        esc(r.by) +
        "</div>";
      html += "</div>";
      html +=
        '<div style="font-size:11px;color:var(--muted);white-space:nowrap;text-align:right;">🕐 ' +
        timeStr +
        "</div>";
      html += "</div>";
    });

    html += "</div></div>";
  });
  if (_histLimit < sortedKeys.length) {
    html +=
      '<div class="muted" style="text-align:center;font-size:12px;padding:10px;">Показаны последние 60 дней. Уточните фильтры, чтобы найти более старые записи.</div>';
  }
  html += "</div>";

  el.innerHTML = html;
  _restoreFocus(focusState);
}

/* ============ ИСТОРИЯ ОПЕРАЦИЙ В ЭКОНОМИКЕ ============ */
function renderTransactionHistory() {
  var el = document.getElementById("ecoSectionHistory");
  if (!el) return;
  var user = current();
  if (!user) return;

  if (!window._ecoHistFilters)
    window._ecoHistFilters = { type: "all", search: "", from: "", to: "" };
  var f = window._ecoHistFilters;
  var _fs =
    typeof _saveFocusByIds === "function"
      ? _saveFocusByIds(["ecoHistSearch"])
      : null;

  /* ── Собираем все операции пользователя ── */
  var records = [];

  (user.balanceHistory || []).forEach(function (h) {
    records.push({
      time: h.time,
      type: "balance",
      icon: "💵",
      title: "Изменение баланса",
      amount: h.amount || 0,
      currency: "balance",
      after: h.after,
      reason: h.reason || "",
      by: h.by || "Система",
    });
  });

  (user.coinHistory || []).forEach(function (h) {
    records.push({
      time: h.time,
      type: "coins",
      icon: "🪙",
      title: "Изменение коинов",
      amount: h.amount || 0,
      currency: "coins",
      after: h.after,
      reason: h.reason || "",
      by: h.by || "Система",
    });
  });

  (user.purchases || []).forEach(function (p) {
    records.push({
      time: p.time,
      type: "purchase",
      icon: p.itemIcon || "🛒",
      title: p.itemName || "Покупка",
      amount: -(p.price || 0),
      currency: p.currency || "coins",
      after: null,
      reason: "Покупка в магазине" + (p.sold ? " · продан/использован" : ""),
      by: user.name,
    });
  });

  transfers
    .filter(function (t) {
      return t.fromId === user.id || t.toId === user.id;
    })
    .forEach(function (t) {
      var isIn = t.toId === user.id;
      records.push({
        time: t.time,
        type: "transfer",
        icon: isIn ? "📥" : "📤",
        title: isIn
          ? "Перевод от " + (t.fromName || "—")
          : "Перевод для " + (t.toName || "—"),
        amount: isIn ? t.netAmount || t.amount || 0 : -(t.amount || 0),
        currency: t.currency || "coins",
        after: null,
        reason: t.reason || (isIn ? "Комиссия: " + (t.fee || 0) : ""),
        by: isIn ? t.fromName || "—" : user.name,
      });
    });

  (user.usedGiftCards || []).forEach(function (g) {
    var amt = 0;
    if (g.rewardType === "coins") amt = Number(g.amount) || 0;
    else if (g.rewardType === "balance") amt = Number(g.amount) || 0;
    records.push({
      time: g.usedAt,
      type: "giftcard",
      icon: "🎁",
      title: "Подарочная карта " + (g.code || ""),
      amount: amt,
      currency: g.rewardType === "balance" ? "balance" : "coins",
      after: null,
      reason: g.rewardText || "",
      by: user.name,
    });
  });

  records = records.filter(function (r) {
    return r.time && !isNaN(new Date(r.time).getTime());
  });
  records.sort(function (a, b) {
    return new Date(b.time) - new Date(a.time);
  });

  /* ── Фильтрация ── */
  var filtered = records.filter(function (r) {
    if (f.type !== "all" && r.type !== f.type) return false;
    if (f.search) {
      var hay = (
        r.title +
        " " +
        (r.reason || "") +
        " " +
        (r.by || "")
      ).toLowerCase();
      if (hay.indexOf(f.search.toLowerCase()) === -1) return false;
    }
    var rt = new Date(r.time).getTime();
    if (f.from) {
      var fd = new Date(f.from + "T00:00:00").getTime();
      if (isFinite(fd) && rt < fd) return false;
    }
    if (f.to) {
      var td = new Date(f.to + "T23:59:59.999").getTime();
      if (isFinite(td) && rt > td) return false;
    }
    return true;
  });

  /* ── Итоги ── */
  var totalIn = 0,
    totalOut = 0;
  records.forEach(function (r) {
    if (r.amount > 0) totalIn += r.amount;
    else if (r.amount < 0) totalOut += Math.abs(r.amount);
  });

  var html = "";

  /* Карточки со статистикой */
  html +=
    '<section class="wallet-hero" style="margin-bottom:16px;"><div class="wallet-hero-cards" style="grid-template-columns:repeat(auto-fit,minmax(180px,1fr));">';
  html +=
    '<div class="wallet-hero-card balance"><span class="wh-ico">📊</span><div class="wh-label">Всего операций</div><div class="wh-value">' +
    records.length +
    "</div></div>";
  html +=
    '<div class="wallet-hero-card balance" style="border-color:#39c98244;"><span class="wh-ico">📥</span><div class="wh-label">Всего приход</div><div class="wh-value" style="color:var(--accent);">+' +
    fmtBalance(totalIn) +
    "</div></div>";
  html +=
    '<div class="wallet-hero-card coins" style="border-color:#e45c6d44;"><span class="wh-ico">📤</span><div class="wh-label">Всего расход</div><div class="wh-value" style="color:var(--danger);">−' +
    fmtBalance(totalOut) +
    "</div></div>";
  html +=
    '<div class="wallet-hero-card coins"><span class="wh-ico">🪙</span><div class="wh-label">Сейчас коинов</div><div class="wh-value">' +
    fmtBalance(Number(user.coins) || 0) +
    "</div></div>";
  html +=
    '<div class="wallet-hero-card balance"><span class="wh-ico">💵</span><div class="wh-label">Сейчас баланс</div><div class="wh-value">' +
    fmtBalance(Number(user.balance) || 0) +
    " ₽</div></div>";
  html += "</div></section>";

  /* Фильтры */
  html +=
    '<div class="shop-controls" style="margin-bottom:16px;flex-wrap:wrap;gap:8px;">';
  html +=
    '<div class="search-wrap" style="flex:1;min-width:200px;"><input id="ecoHistSearch" placeholder="🔍 Поиск по названию / причине / автору..." value="' +
    esc(f.search) +
    '" oninput="window._ecoHistFilters.search=this.value;renderTransactionHistory()"></div>';
  html +=
    '<select onchange="window._ecoHistFilters.type=this.value;renderTransactionHistory()" style="min-width:190px;">';
  [
    ["all", "📋 Все (" + records.length + ")"],
    ["balance", "💵 Баланс"],
    ["coins", "🪙 Коины"],
    ["purchase", "🛒 Покупки"],
    ["transfer", "💸 Переводы"],
    ["giftcard", "🎁 Подарочные карты"],
  ].forEach(function (o) {
    html +=
      '<option value="' +
      o[0] +
      '"' +
      (f.type === o[0] ? " selected" : "") +
      ">" +
      o[1] +
      "</option>";
  });
  html += "</select>";
  html +=
    '<input type="date" value="' +
    esc(f.from) +
    '" onchange="window._ecoHistFilters.from=this.value;renderTransactionHistory()" title="С даты" style="min-width:130px;">';
  html +=
    '<input type="date" value="' +
    esc(f.to) +
    '" onchange="window._ecoHistFilters.to=this.value;renderTransactionHistory()" title="По дату" style="min-width:130px;">';
  html +=
    "<button class=\"btn small\" onclick=\"window._ecoHistFilters={type:'all',search:'',from:'',to:''};renderTransactionHistory()\">✖ Сброс</button>";
  html +=
    '<button class="btn small" onclick="exportTransactionsCSV()">⇩ Excel</button>';
  html += "</div>";

  /* Список */
  if (!filtered.length) {
    html +=
      '<div class="empty" data-icon="📭"><b>Операций не найдено</b><small>Измените фильтры или диапазон дат</small></div>';
    el.innerHTML = html;
    if (_fs) _restoreFocus(_fs);
    return;
  }

  html +=
    '<section class="card"><div class="toolbar"><div class="toolbar-row" style="justify-content:space-between;"><h3 style="margin:0;">📜 История операций (' +
    filtered.length +
    ')</h3><span class="badge">Показано: ' +
    Math.min(filtered.length, 500) +
    "</span></div></div>";
  html +=
    '<div style="padding:12px;display:flex;flex-direction:column;gap:6px;max-height:70vh;overflow-y:auto;">';

  filtered.slice(0, 500).forEach(function (r) {
    var sym =
      r.currency === "coins" ? "🪙" : r.currency === "balance" ? "₽" : "";
    var sign = r.amount > 0 ? "+" : r.amount < 0 ? "−" : "";
    var color =
      r.amount > 0
        ? "var(--accent)"
        : r.amount < 0
          ? "var(--danger)"
          : "var(--muted)";
    var amtText = r.amount
      ? sign + fmtBalance(Math.abs(r.amount)) + " " + sym
      : "—";

    var afterText =
      r.after !== null && r.after !== undefined
        ? " · стало: " +
          fmtBalance(r.after) +
          (r.currency === "balance"
            ? " ₽"
            : r.currency === "coins"
              ? " 🪙"
              : " ")
        : "";

    html +=
      '<div style="display:grid;grid-template-columns:44px 1fr auto;gap:12px;align-items:center;padding:10px 14px;background:#0d1a13;border:1px solid var(--line);border-radius:10px;">';
    html +=
      '<div style="width:44px;height:44px;border-radius:10px;background:#0a1710;border:1px solid var(--line);display:grid;place-items:center;font-size:20px;">' +
      esc(r.icon || "📋") +
      "</div>";
    html += '<div style="min-width:0;">';
    html +=
      '<div style="font-size:13px;font-weight:800;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' +
      esc(r.title) +
      "</div>";
    if (r.reason)
      html +=
        '<div style="font-size:11.5px;color:var(--muted);margin-top:2px;line-height:1.35;word-break:break-word;">' +
        esc(r.reason) +
        "</div>";
    html +=
      '<div style="font-size:10.5px;color:var(--muted);margin-top:3px;opacity:.75;">🕐 ' +
      new Date(r.time).toLocaleString("ru-RU") +
      " · 👤 " +
      esc(r.by || "—") +
      afterText +
      "</div>";
    html += "</div>";
    html +=
      '<div style="font-weight:900;font-size:14px;color:' +
      color +
      ';white-space:nowrap;text-align:right;">' +
      amtText +
      "</div>";
    html += "</div>";
  });

  html += "</div></section>";
  el.innerHTML = html;
  if (_fs) _restoreFocus(_fs);
}
