/* ============ FOCUS TRAP + ESC ============ */
(function () {
  function getFocusable(root) {
    return Array.from(
      root.querySelectorAll(
        'a[href], button:not([disabled]), input:not([disabled]):not([type="hidden"]), ' +
          'select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])',
      ),
    ).filter(function (el) {
      return el.offsetParent !== null;
    });
  }
  function trapFocus(modal) {
    if (!modal) return;
    var focusable = getFocusable(modal);
    if (!focusable.length) return;
    var first = focusable[0],
      last = focusable[focusable.length - 1];
    modal.addEventListener("keydown", function (e) {
      if (e.key !== "Tab") return;
      if (e.shiftKey) {
        if (document.activeElement === first) {
          e.preventDefault();
          last.focus();
        }
      } else {
        if (document.activeElement === last) {
          e.preventDefault();
          first.focus();
        }
      }
    });
    setTimeout(function () {
      try {
        first.focus();
      } catch (_) {}
    }, 50);
  }
  var modalEl = document.getElementById("modal");
  var modalContent = document.getElementById("modalContent");
  if (modalEl) {
    modalEl.setAttribute("role", "dialog");
    modalEl.setAttribute("aria-modal", "true");
    var observer = new MutationObserver(function () {
      if (!modalEl.classList.contains("hidden")) {
        setTimeout(function () {
          trapFocus(modalContent);
        }, 30);
      }
    });
    observer.observe(modalEl, { attributes: true, attributeFilter: ["class"] });
  }
  document.addEventListener("keydown", function (e) {
    if (e.key !== "Escape") return;
    if (_criticalOpen && typeof _criticalCancel === "function") {
      try {
        _criticalCancel(false);
      } catch (_) {}
      return;
    }
    var m = document.getElementById("modal");
    if (m && !m.classList.contains("hidden")) {
      if (typeof _pmCancel === "function") {
        try {
          _pmCancel(null);
        } catch (_) {}
        return;
      }
      closeModal();
      return;
    }
    if (notifOpen) {
      notifOpen = false;
      var dd = document.getElementById("notifDropdown");
      if (dd) dd.classList.add("hidden");
    }
    closeUserDropdown();
  });
})();

/* ============ ПРОМПТ-МОДАЛКА ============ */
var _pmCancel = null; // глобал для ESC / backdrop
function promptModal(opts) {
  opts = opts || {};
  /* FIX: не открываем второй промпт, если уже открыт критический диалог
     или другой promptModal. Иначе один перезапишет #modalContent и m.onclick,
     и висящий промис никогда не резолвится. */
  if (typeof _pmCancel === "function" || _criticalOpen) {
    return Promise.resolve(null);
  }
  return new Promise(function (resolve) {
    var html =
      "<h2>" + (opts.danger ? "⚠️ " : "") + esc(opts.title || "Ввод") + "</h2>";
    if (opts.message)
      html +=
        '<p class="muted" style="white-space:pre-wrap;word-break:break-word;font-size:12px;line-height:1.5;max-height:30vh;overflow:auto;">' +
        esc(opts.message) +
        "</p>";
    html +=
      '<div class="field"><label>' + esc(opts.label || "Значение") + "</label>";
    html +=
      '<input id="pmInput" value="' +
      esc(opts.value || "") +
      '" placeholder="' +
      esc(opts.placeholder || "") +
      '"' +
      (opts.type === "number" ? ' type="number"' : "") +
      "></div>";
    html += '<div id="pmError" class="error"></div>';
    html += '<div class="modal-actions">';
    html += '<button class="btn" id="pmCancel">Отмена</button>';
    html +=
      '<button class="btn ' +
      (opts.danger ? "danger" : "primary2") +
      '" id="pmOk">' +
      esc(opts.okText || "OK") +
      "</button>";
    html += "</div>";
    var mc = document.getElementById("modalContent");
    var m = document.getElementById("modal");
    mc.innerHTML = html;
    m.classList.remove("hidden");
    var done = false;
    function close(val) {
      if (done) return;
      done = true;
      _pmCancel = null;
      m.onclick = function (ev) {
        if (ev.target === m) closeModal();
      };
      m.classList.add("hidden");
      resolve(val);
    }
    _pmCancel = close;
    m.onclick = function (ev) {
      if (ev.target === m) close(null);
    };
    document.getElementById("pmCancel").onclick = function () {
      close(null);
    };
    document.getElementById("pmOk").onclick = function () {
      var v = document.getElementById("pmInput").value;
      if (opts.validate && !opts.validate(v)) {
        document.getElementById("pmError").textContent =
          opts.errorMsg || "Некорректное значение";
        return;
      }
      close(v);
    };
    document.getElementById("pmInput").onkeydown = function (e) {
      if (e.key === "Enter") {
        e.preventDefault();
        document.getElementById("pmOk").click();
      }
    };
    setTimeout(function () {
      document.getElementById("pmInput").focus();
    }, 50);
  });
}

