function _bpKeyColor(kd) {
  return kd && kd.color ? kd.color : "#8a9a8f";
}

/* Генерирует читаемую подпись награды, если у неё нет своего label.
   Без этой функции карточки BP показывают «Награда» вместо «🪙 200». */
function _bpRewardLabel(r) {
  if (!r) return "Награда";
  if (r.label) return r.label;
  var t = r.type;
  if (t === "coins") return "🪙 " + fmtBalance(r.amount || 0);
  if (t === "balance") return "💵 " + fmtBalance(r.amount || 0) + " ₽";
  if (t === "key") {
    var kd = getKeyDef(r.keyRarity);
    return (kd ? kd.name : "Ключ") + " ×" + (r.amount || 1);
  }
  if (t === "badge")
    return (r.badgeIcon || "🏅") + " " + (r.badgeName || "Бейдж");
  if (t === "frame") {
    var f = FRAMES[r.frameKey];
    return "🖼 " + (f ? f.name : "Рамка");
  }
  if (t === "theme") return "🎨 " + (r.themeKey || "Тема");
  if (t === "lbAnim") {
    var a = LB_ANIMS[r.animKey];
    return "🎁 " + (a ? a.name : "Анимация");
  }
  if (t === "item") {
    var it = shopItems.find(function (x) {
      return x.id === r.itemId;
    });
    return "📦 " + (it ? it.name : "Предмет");
  }
  if (t === "spinPack") return "🎡 ×" + (r.amount || 1);
  if (t === "unlock") {
    var m = {
      canNickColor: "🎨 Цвет ника",
      canProfileAnim: "✨ Анимация",
      canAdvancedStats: "📊 Статистика",
      canProfileBg: "🖼 Фон",
    };
    return "🔓 " + (m[r.unlockKey] || "Разблокировка");
  }
  return "Награда";
}

