// ============ ГЛОБАЛЬНАЯ СИСТЕМА ПОДТВЕРЖДЕНИЯ ДЕЙСТВИЙ ============
function wrapWithConfirm(funcName, actionText, isDanger) {
  if (typeof window[funcName] === "function" && !window[funcName].__wrapped) {
    var original = window[funcName];
    window[funcName] = async function () {
      var self = this;
      var args = arguments;
      if (_criticalOpen) return; // Защита от дублей

      var ok = await confirmCritical({
        title: isDanger ? "Внимание" : "Подтверждение", // <-- Убрали лишний ⚠️ отсюда
        message: "Вы уверены, что хотите " + actionText + "?",
        danger: isDanger,
        okText: isDanger ? "Да, выполнить" : "✅ Подтвердить",
      });

      if (ok) {
        var oldConfirm = window.confirm;
        window.confirm = function () {
          return true;
        }; // Отключаем встроенный confirm на время выполнения
        try {
          var res = original.apply(self, args);
          if (res instanceof Promise) {
            return res.finally(function () {
              window.confirm = oldConfirm;
            });
          }
          return res;
        } finally {
          if (!(res instanceof Promise)) window.confirm = oldConfirm;
        }
      }
    };
    window[funcName].__wrapped = true;
  }
}

