function bpForceRegenerate() {
  if (!can(current(), "manage_shop")) return;
  if (
    !confirm(
      "⚠️ ВНИМАНИЕ!\n\nЭто удалит все текущие 25 уровней и сгенерирует новые с ключами, рамками и бейджами.\n\nПрогресс игроков (XP) сохранится, но если они уже забрали награды на каких-то уровнях, они останутся у них в инвентаре.",
    )
  )
    return;

  battlePass.levels = generateBPLevels(BP_TRACK_LEVELS, battlePass.season);
  if (typeof _migrateBPToTracks === "function") {
    _migrateBPToTracks();
  }
  saveBattlePass();
  try {
    updateTabsVisibility();
  } catch (_) {} // <--- ДОБАВЛЕНО
  toast("🔥 Награды успешно перегенерированы!", "success");

  // Перерисовываем
  _bpDraft = JSON.parse(JSON.stringify(battlePass));
  renderBattlePassManager();
  renderBattlePass();
}

