(function fixMissingAdminSections() {
  var sfParent = document.getElementById("sectionStaffFunc");
  if (!sfParent) {
    console.warn("❌ sectionStaffFunc не найден");
    return;
  }

  var sections = [
    { id: "sfSectionEmployees", inner: '<div id="sfEmployeesList"></div>' },
    { id: "sfSectionFreeze", inner: '<div id="sfFreezeList"></div>' },
    { id: "sfSectionVacation", inner: '<div id="sfVacationList"></div>' },
    { id: "sfSectionPromotion", inner: '<div id="sfPromotionList"></div>' },
    { id: "sfSectionAnalytics", inner: '<div id="sfAnalytics"></div>' },
    { id: "sfSectionBalances", inner: "" },
    {
      id: "sfSectionHistory",
      inner:
        '<div id="sfHistoryTotalBadge" style="margin-bottom:12px;"></div><div id="sfHistoryList"></div>',
    },
    { id: "sfSectionInvEditor", inner: '<div id="invEditorList"></div>' },
  ];

  var lastSf = null;
  var existing = sfParent.querySelectorAll('[id^="sfSection"]');
  if (existing.length) lastSf = existing[existing.length - 1];

  sections.forEach(function (s) {
    if (document.getElementById(s.id)) return;
    var el = document.createElement("div");
    el.id = s.id;
    el.className = "hidden";
    el.innerHTML = s.inner;
    if (lastSf && lastSf.parentElement === sfParent) {
      lastSf.parentNode.insertBefore(el, lastSf.nextSibling);
      lastSf = el;
    } else {
      sfParent.appendChild(el);
      lastSf = el;
    }
  });

  console.log(
    "✅ Недостающие секции созданы:",
    sections
      .map(function (s) {
        return s.id;
      })
      .join(", "),
  );
})();

