// Настройки для Twemoji (берем SVG-иконки с CDN)
const twemojiOptions = {
  folder: "svg",
  ext: ".svg",
  base: "https://cdn.jsdelivr.net/npm/@twemoji/svg@latest/",
};

// 1. Первичный запуск после загрузки страницы
window.addEventListener("DOMContentLoaded", () => {
  twemoji.parse(document.body, twemojiOptions);

  // 2. Следим за изменениями на странице (вкладки, модалки, тосты)
  const observer = new MutationObserver((mutations) => {
    mutations.forEach((mutation) => {
      mutation.addedNodes.forEach((node) => {
        // Если добавился новый HTML-элемент — обрабатываем его
        if (node.nodeType === 1) {
          twemoji.parse(node, twemojiOptions);
        }
      });
    });
  });

  // Запускаем наблюдение за всем документом
  observer.observe(document.body, {
    childList: true,
    subtree: true,
  });
});

