(function homeTimers() {
  const wheelValue = document.getElementById("wheelTimerValue");
  const dailyValue = document.getElementById("dailyTimerValue");
  const wheelBox = document.getElementById("wheelTimerBox");
  const dailyBox = document.getElementById("dailyTimerBox");
  if (!wheelValue || !dailyValue) return;

  const WHEEL_KEYS = [
    "wheelNextSpin",
    "nextWheelSpin",
    "wheelCooldown",
    "wheel_next",
    "wheel_last_spin",
    "lastWheelSpin",
  ];
  const WHEEL_COOLDOWN_MS = 3 * 60 * 60 * 1000;

  const DAILY_KEYS = ["dailyNextReward", "nextDailyReward", "daily_last_claim"];
  const DAILY_COOLDOWN_MS = 24 * 60 * 60 * 1000;

  function getNextWheelTime() {
    for (let i = 0; i < WHEEL_KEYS.length; i++) {
      const raw = localStorage.getItem(WHEEL_KEYS[i]);
      if (!raw) continue;
      const v = Number(raw);
      if (!v) continue;
      return v < Date.now() ? v + WHEEL_COOLDOWN_MS : v;
    }
    return 0;
  }

  function getNextDailyTime() {
    for (let i = 0; i < DAILY_KEYS.length; i++) {
      const raw = localStorage.getItem(DAILY_KEYS[i]);
      if (!raw) continue;
      const v = Number(raw);
      if (!v) continue;
      return v < Date.now() ? v + DAILY_COOLDOWN_MS : v;
    }
    return 0;
  }

  function fmt(ms) {
    if (ms <= 0) return "Доступно";
    const s = Math.floor(ms / 1000);
    const h = Math.floor(s / 3600);
    const m = Math.floor((s % 3600) / 60);
    const sec = s % 60;
    if (h > 0)
      return (
        h +
        "ч " +
        String(m).padStart(2, "0") +
        "м " +
        String(sec).padStart(2, "0") +
        "с"
      );
    if (m > 0) return m + "м " + String(sec).padStart(2, "0") + "с";
    return sec + "с";
  }

  function tick() {
    const now = Date.now();
    const w = getNextWheelTime() - now;
    const d = getNextDailyTime() - now;
    wheelValue.textContent = fmt(w);
    dailyValue.textContent = fmt(d);
    wheelBox.classList.toggle("ready", w <= 0);
    dailyBox.classList.toggle("ready", d <= 0);
  }

  tick();
  setInterval(tick, 1000);
})();

