function forceUpdateTrust() {
  // 1. Находим все плашки рейтинга (trust-mini-badge)
  const badges = document.querySelectorAll(".trust-mini-badge");
  badges.forEach((badge) => {
    // Если там пусто или "undefined", ставим заглушку
    if (!badge.textContent || badge.textContent.includes("undefined")) {
      badge.textContent = "⚠️ 0"; // Временная заглушка
    }
  });

  // 2. Обновляем средний рейтинг (avgTrust)
  const avgEl = document.getElementById("avgTrust");
  if (avgEl) {
    // Если число не число — ставим 0
    if (isNaN(parseFloat(avgEl.textContent))) {
      avgEl.textContent = "0";
    }
  }

  // 3. Обновляем полосы рейтинга (trust-bar)
  const bars = document.querySelectorAll(".trust-bar");
  bars.forEach((bar) => {
    const fill = bar.querySelector(
      ".trust-bar-fill-0, .trust-bar-fill-1, .trust-bar-fill-2, .trust-bar-fill-3, .trust-bar-fill-4",
    );
    if (fill && fill.style.width === "") {
      fill.style.width = "0%";
    }
  });
}

// Запускаем проверку каждую секунду (на случай, если данные подгружаются с задержкой)
setInterval(forceUpdateTrust, 1000);

// И сразу при загрузке
document.addEventListener("DOMContentLoaded", forceUpdateTrust);

