// ==========================================
// ЯРКИЙ ГРАДИЕНТ ДЛЯ ДОЛЖНОСТЕЙ (КАК В BIRDFLOP)
// ==========================================

function lerpColor(a, b, t) {
  const ah = parseInt(a.replace("#", ""), 16),
    bh = parseInt(b.replace("#", ""), 16),
    ar = ah >> 16,
    ag = (ah >> 8) & 0xff,
    ab = ah & 0xff,
    br = bh >> 16,
    bg = (bh >> 8) & 0xff,
    bb = bh & 0xff;
  const rr = Math.round(ar + (br - ar) * t),
    rg = Math.round(ag + (bg - ag) * t),
    rb = Math.round(ab + (bb - ab) * t);
  return "#" + ((1 << 24) + (rr << 16) + (rg << 8) + rb).toString(16).slice(1);
}

function applyLetterGradient(el, color1, color2, dir = "135deg") {
  if (el.querySelector(".gradient-letter")) return;
  const text = el.textContent.trim();
  const len = text.length;
  if (len === 0) return;

  let html = "";
  for (let i = 0; i < len; i++) {
    const t = i / (len - 1 || 1);
    const color = lerpColor(color1, color2, t);
    html += `<span class="gradient-letter" style="color: ${color}; font-weight: 900; font-size: 16px; text-shadow: 0 0 10px ${color};">${text[i]}</span>`;
  }
  el.innerHTML = html;
  el.style.background = "transparent";
  el.style.border = "none";
  el.style.padding = "0";
  el.style.display = "inline-block";
}

function applyDiscordGradients() {
  let savedColors = {};
  try {
    savedColors = JSON.parse(localStorage.getItem("roleColors") || "{}");
  } catch (e) {}
  if (typeof roleColors !== "undefined" && Object.keys(roleColors).length > 0) {
    savedColors = roleColors;
  }

  // Ищем все элементы, в которых есть текст должности
  const allElements = document.querySelectorAll(
    "span, b, small, strong, i, div",
  );

  allElements.forEach((el) => {
    // Пропускаем большие контейнеры
    if (el.children.length > 1) return;

    const text = el.textContent.trim();
    if (!text) return;
    if (text.length > 30) return;

    for (const role in savedColors) {
      const grad = savedColors[role];
      if (grad && grad.includes("|")) {
        // Убираем эмодзи для сравнения
        const cleanText = text
          .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}]/gu, "")
          .trim();
        const cleanRole = role.trim();

        if (cleanText === cleanRole || text.includes(cleanRole)) {
          const parts = grad.split("|");
          const c1 = parts[0];
          const c2 = parts[1];

          // Если внутри есть эмодзи, сохраняем его, а текст красим
          const emojiMatch = text.match(
            /[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}]/u,
          );
          let emoji = emojiMatch ? emojiMatch[0] + " " : "";

          applyLetterGradient(el, c1, c2, emoji);
          break;
        }
      }
    }
  });
}

// Обновленная функция для градиента по буквам (с сохранением эмодзи)
function applyLetterGradient(el, color1, color2, emoji = "") {
  if (el.querySelector(".gradient-letter")) return;

  // Получаем текст без эмодзи
  const text = el.textContent
    .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}]/gu, "")
    .trim();
  const len = text.length;
  if (len === 0) return;

  let html = emoji; // Добавляем эмодзи в начало
  for (let i = 0; i < len; i++) {
    const t = i / (len - 1 || 1);
    const color = lerpColor(color1, color2, t);
    html += `<span class="gradient-letter" style="color: ${color}; font-weight: 900; font-size: 16px; text-shadow: 0 0 10px ${color};">${text[i]}</span>`;
  }
  el.innerHTML = html;
  el.style.background = "transparent";
  el.style.border = "none";
  el.style.padding = "0";
  el.style.display = "inline-block";
}

