window.hrRequests = JSON.parse(localStorage.getItem("hrRequests") || "[]");
window._hrCabinetTab = window._hrCabinetTab || "actions"; // 'actions' | 'tickets'
window._hrSelfFilter = window._hrSelfFilter || "all";
window._hrFilterStatus = window._hrFilterStatus || "all";
window._hrFilterType = window._hrFilterType || "";
window._hrSearchQuery = window._hrSearchQuery || "";
window._pendingHrImg = "";

function _saveHrRequests() {
  try {
    localStorage.setItem(
      "hrRequests",
      JSON.stringify(window.hrRequests || new Array()),
    );
  } catch (e) {}
}

function _canManageHrRequests(u) {
  if (!u) return false;
  return (
    can(u, "manage_staff") ||
    can(u, "manage_permissions") ||
    can(u, "edit_task")
  );
}

